  // Determine popover position
  // Default: Bottom-Right of the cursor target
  const viewportWidth = typeof window !== 'undefined' ? window.innerWidth : 1000;
  const isRightSide = popover ? popover.rect.left > viewportWidth * 0.6 : false;

  const POPOVER_OFFSET = 5;

