export default ResultsTable;

import { GoogleGenAI, Type } from "@google/genai";
import { SeafoodInputItem, SeafoodResultItem, Rating } from "../types";
import { getSeafoodById } from "./referenceDatabase";

// This declaration is necessary because the library is loaded from a script tag in index.html
declare var process: {
  env: {
    API_KEY: string;
  };
};

// Schema for a single analysis result
const singleItemSchema = {
  type: Type.OBJECT,
  properties: {
    uniqueId: {
      type: Type.STRING,
      description: "The official Seafood Watch Recommendation ID (Column A from the dataset). It MUST be a specific, existing ID (typically a 4-6 digit integer like 24301). Do NOT generate sequential IDs.",
    },
    officialKDEs: {
      type: Type.STRING,
      description: "The official description from the Seafood Watch dataset corresponding to this Unique ID (e.g., 'Sockeye Salmon | Bristol Bay | Drift Gillnet').",
    },
    rating: {
      type: Type.STRING,
      enum: [Rating.BestChoice, Rating.GoodAlternative, Rating.Avoid, Rating.Certified, Rating.NA],
      description: "The Seafood Watch environmental rating.",
    },
    reliabilityScore: {
      type: Type.NUMBER,
      description: "A confidence score from 0 to 100 for the rating accuracy.",
    },
    notes: {
      type: Type.STRING,
      description: "Explanation for the rating, especially if data is missing or ambiguous.",
    },
  },
  required: ["uniqueId", "officialKDEs", "rating", "reliabilityScore", "notes"],
};

// Schema for the batched response, which is an array of single items
const responseSchema = {
    type: Type.ARRAY,
    items: singleItemSchema
};

const systemInstruction = `You are the official data integration engine for the Monterey Bay Aquarium Seafood Watch program. You have access to the master database of Seafood Watch ratings.

Task:
Analyze the provided seafood product data and map each item to its corresponding **Official Seafood Watch Recommendation**.

CRITICAL RULES FOR UNIQUE ID (Column A):
1. **NO SEQUENTIAL IDs**: Never output IDs like "1", "2", "3" or "001".
2. **REAL IDs ONLY**: You must output the actual Recommendation ID from the Seafood Watch database. These are typically 4, 5, or 6 digit integers (e.g., "5391", "24051", "10023").
3. If you identify a "Certified" product (e.g. MSC, ASC), set uniqueId to "N/A".
4. If you cannot find a specific matching ID in the database, set uniqueId to "N/A".

CRITICAL RULES FOR OFFICIAL KDEs:
1. In the 'officialKDEs' field, you must provide the official text description for that ID from the database (Species + Location + Method).
2. Do NOT simply repeat the user's input. Use the standardized nomenclature from the Seafood Watch dataset.

Rating Logic:
1. **Certified**: If the item has a valid certification (MSC, ASC, BAP, etc.) and the species is eligible, assign "Certified".
2. Otherwise, match species, country, and method to the database to find "Best Choice", "Good Alternative", or "Avoid".
3. Calculate 'reliabilityScore' (0-100) based on how well the input matches the official KDEs.

Notes Rules:
1. Provide a concise explanation for the rating.
2. **Strictly Forbidden:** Do NOT include the phrase "No valid Seafood Watch certification found." in the notes. If certification is absent or invalid, simply describe the wild/farmed rating without mentioning missing certification.

Respond ONLY with a single, raw JSON array matching the schema.`;

type AnalysisResult = Pick<SeafoodResultItem, 'uniqueId' | 'matchedKDEs' | 'rating' | 'reliabilityScore' | 'notes'>;

const BATCH_SIZE = 15; // Process 15 items per API call to reduce request size
const API_DELAY_MS = 6000; // 6-second delay between batches (10 RPM) to stay safely under limits

async function rateBatch(items: SeafoodInputItem[]): Promise<AnalysisResult[]> {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const totalRetries = 5;
    let retries = totalRetries;
    let delay = 5000; // Initial retry delay of 5s

    const failedResult: AnalysisResult = {
        uniqueId: "N/A",
        matchedKDEs: "Analysis Failed",
        rating: Rating.NA,
        reliabilityScore: 0,
        notes: "An error occurred during analysis.",
    };
    const rateLimitResult: AnalysisResult = {
        uniqueId: "N/A",
        matchedKDEs: "Rate Limit Exceeded",
        rating: Rating.NA,
        reliabilityScore: 0,
        notes: "Rate limit exceeded. Try a smaller file or wait a minute.",
    }

    while (retries > 0) {
        try {
            const prompt = `Batch Input: ${JSON.stringify(items)}`;

            const response = await ai.models.generateContent({
                model: 'gemini-2.5-flash',
                contents: prompt,
                config: {
                systemInstruction: systemInstruction,
                responseMimeType: "application/json",
                responseSchema: responseSchema,
                temperature: 0.1,
                },
            });

            const jsonText = response.text.trim();
            const results: any[] = JSON.parse(jsonText);

            if (!Array.isArray(results) || results.length !== items.length) {
                console.error(`API response mismatch: expected ${items.length} items, got ${results.length}.`);
                throw new Error(`API returned an incorrect number of items for the batch.`);
            }

            // Validate and format results
            return results.map(result => {
                const uniqueId = result.uniqueId || "N/A";
                let matchedKDEs = result.officialKDEs || "N/A";
                let rating = result.rating || Rating.NA;

                // HYDRATION: If we have a local record for this ID, use the official data
                // This prevents AI hallucinations about what ID 414 actually is.
                if (uniqueId !== "N/A") {
                    const officialRecord = getSeafoodById(uniqueId);
                    if (officialRecord) {
                        matchedKDEs = officialRecord.matchedKDEs;
                        rating = officialRecord.rating;
                    }
                }

                return {
                    uniqueId,
                    matchedKDEs, 
                    rating,
                    reliabilityScore: result.reliabilityScore || 0,
                    notes: result.notes || "No notes provided.",
                };
            });

        } catch (error) {
            console.error("Error processing batch with Gemini:", error);

            const errorString = JSON.stringify(error);
            if (errorString.includes('429')) {
                retries--;
                if (retries === 0) {
                    return items.map(() => rateLimitResult);
                }
                const jitter = Math.random() * 1000;
                console.warn(`Rate limit hit. Retrying in ${Math.round((delay + jitter) / 1000)}s... (${retries} retries left)`);
                await new Promise(resolve => setTimeout(resolve, delay + jitter));
                delay *= 2; 
            } else {
                return items.map(() => failedResult);
            }
        }
    }

    return items.map(() => rateLimitResult);
}

export async function rateSeafoodData(
  data: SeafoodInputItem[],
  onProgress: (processed: number, total: number) => void,
  signal?: AbortSignal
): Promise<AnalysisResult[]> {
  const allResults: AnalysisResult[] = [];
  const total = data.length;

  const rateLimitNote = "Rate limit exceeded. Try a smaller file or wait a minute.";
  const processingStoppedNote = "Processing stopped due to API rate limits.";

  for (let i = 0; i < total; i += BATCH_SIZE) {
    if (signal?.aborted) {
        throw new DOMException('Analysis aborted by user', 'AbortError');
    }

    const batch = data.slice(i, i + BATCH_SIZE);
    const batchResults = await rateBatch(batch);
    allResults.push(...batchResults);

    const processedCount = allResults.length;
    onProgress(processedCount, total);

    const isRateLimited = batchResults.every(r => r.notes === rateLimitNote);
    if (isRateLimited) {
        console.warn("API rate limit hit. Aborting further processing.");

        const remainingCount = total - processedCount;
        if (remainingCount > 0) {
            const stoppedResult: AnalysisResult = {
                uniqueId: "N/A",
                matchedKDEs: "Aborted",
                rating: Rating.NA,
                reliabilityScore: 0,
                notes: processingStoppedNote,
            };
            for (let j = 0; j < remainingCount; j++) {
                allResults.push(stoppedResult);
            }
            onProgress(total, total);
        }
        break;
    }

    if (processedCount < total) {
      await new Promise(resolve => setTimeout(resolve, API_DELAY_MS));
    }
  }

  return allResults;
}

export async function updateAnalysisForId(
  item: SeafoodInputItem,
  newId: string
): Promise<AnalysisResult> {

    // 1. First, try a deterministic lookup from our reference database.
    // This bypasses AI hallucinations (e.g., ensures ID 414 is Blue Crab, not Abalone).
    const officialRecord = getSeafoodById(newId);

    if (officialRecord) {
        return {
            uniqueId: newId,
            matchedKDEs: officialRecord.matchedKDEs,
            rating: officialRecord.rating,
            reliabilityScore: 100, // User manually confirmed this ID, so reliability is 100%
            notes: "Manually verified against official Seafood Watch records.",
        };
    }

    // 2. If ID not found in our static CSV (e.g. it's a very new ID), fall back to AI
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

    const singleUpdateSchema = {
        type: Type.OBJECT,
        properties: {
            officialKDEs: {
                type: Type.STRING,
                description: "The official description from the Seafood Watch dataset for the ID provided by the user.",
            },
            rating: {
                type: Type.STRING,
                enum: [Rating.BestChoice, Rating.GoodAlternative, Rating.Avoid, Rating.Certified, Rating.NA],
                description: "The official Seafood Watch rating corresponding to the provided ID.",
            },
            notes: {
                type: Type.STRING,
                description: "Brief reasoning for the rating associated with this ID.",
            },
        },
        required: ["officialKDEs", "rating", "notes"],
    };

    const systemInstruction = `You are a Seafood Watch data expert. The user has manually identified a seafood product as belonging to a specific Seafood Watch Recommendation ID: "${newId}". 

    Your task:
    1. Accept this ID ("${newId}") as the absolute truth.
    2. Lookup the details for ID "${newId}" in the Seafood Watch database.
    3. Return the Official KDE description (Species, Location, Method) and the Rating for this exact ID.
    4. If the ID does not exist or is invalid, return Rating "N/A".`;

    const prompt = `Product Data: ${JSON.stringify(item)}\n\nUser assigned ID: ${newId}`;

    try {
        const response = await ai.models.generateContent({
            model: 'gemini-2.5-flash',
            contents: prompt,
            config: {
                systemInstruction: systemInstruction,
                responseMimeType: "application/json",
                responseSchema: singleUpdateSchema,
                temperature: 0.1,
            },
        });

        const result = JSON.parse(response.text.trim());

        return {
            uniqueId: newId,
            matchedKDEs: result.officialKDEs || "Manual Update",
            rating: result.rating || Rating.NA,
            reliabilityScore: 100, 
            notes: result.notes || "Manually updated by user.",
        };

    } catch (error) {
        console.error("Error updating analysis for ID:", error);
        return {
            uniqueId: newId,
            matchedKDEs: "Error",
            rating: Rating.NA,
            reliabilityScore: 0,
            notes: "Error updating rating. Please try again.",
        };
    }
}

export async function getColumnMapping(
  mappableFields: string[],
  fileHeaders: string[]
): Promise<{ mapping: Record<string, string>; isFallback: boolean }> {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  const properties: Record<string, object> = {};
  mappableFields.forEach(field => {
    properties[field] = {
      type: Type.STRING,
      enum: [...fileHeaders, 'N/A'],
      description: `The best matching column header from the file for the required field '${field}'. Select 'N/A' if no good match is found.`
    };
  });

  const schema = {
    type: Type.OBJECT,
    properties: properties,
    required: mappableFields,
  };

  const systemInstruction = `You are an expert data mapping specialist. Your task is to analyze a list of required data fields and a list of column headers from an uploaded file. For each required field, you must identify the best matching column header from the file's headers. If no suitable match is found for a field, you must map it to 'N/A'. The data is related to seafood sourcing, so be mindful of synonyms (e.g., 'species' vs 'common name', 'origin' vs 'country'). Respond ONLY with a single, raw JSON object that conforms to the provided schema. Do not add any extra text, explanations, or markdown formatting.`;

  const prompt = `Please map these required fields: ${JSON.stringify(mappableFields)} to the available file headers: ${JSON.stringify(fileHeaders)}.`;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash',
      contents: prompt,
      config: {
        systemInstruction: systemInstruction,
        responseMimeType: "application/json",
        responseSchema: schema,
        temperature: 0.0,
      },
    });

    const jsonText = response.text.trim();
    const mappingResult = JSON.parse(jsonText);

    const isValid = mappableFields.every(field => 
      Object.prototype.hasOwnProperty.call(mappingResult, field) &&
      (fileHeaders.includes(mappingResult[field]) || mappingResult[field] === 'N/A')
    );

    if (isValid) {
      console.log("Successfully mapped columns with AI.");
      return { mapping: mappingResult, isFallback: false };
    } else {
      console.warn("AI mapping result was invalid or incomplete.", mappingResult);
      throw new Error("Invalid mapping structure returned by AI.");
    }

  } catch (error) {
    console.error("AI column mapping failed. Using keyword-based fallback.", error);
    const staticMapping = performStaticMapping(mappableFields, fileHeaders);
    return { mapping: staticMapping, isFallback: true };
  }
}


export async function analyzeSheetLayout(
  sheetPreviews: { sheetName: string; data: (string | number)[][] }[]
): Promise<{ bestSheetName: string; bestHeaderRow: number }> {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  const schema = {
    type: Type.OBJECT,
    properties: {
      bestSheetName: {
        type: Type.STRING,
        description: "The name of the sheet most likely containing the main dataset.",
      },
      bestHeaderRow: {
        type: Type.NUMBER,
        description: "The 1-based index of the row most likely to be the header row.",
      },
    },
    required: ["bestSheetName", "bestHeaderRow"],
  };

  const systemInstruction = `You are an expert spreadsheet data analyst. Your task is to examine previews from multiple sheets in a spreadsheet file and determine which sheet contains the primary dataset and which row is the header. The data is related to seafood sourcing, so look for columns like 'species', 'common name', 'country', 'origin', 'production method', 'farmed', 'wild', 'certification', 'supplier', etc. The header row is the one that contains these descriptive titles. It is often the first row, but could be preceded by title rows or empty rows. Ignore summary sheets, charts, or instruction sheets. Respond with the sheet name and the 1-based row number of the header.`;

  const prompt = `Analyze the following sheet previews and identify the best sheet and header row:\n\n${JSON.stringify(sheetPreviews)}`;

  const totalRetries = 5;
  let retries = totalRetries;
  let delay = 5000;

  while (retries > 0) {
    try {
      const response = await ai.models.generateContent({
        model: 'gemini-2.5-flash',
        contents: prompt,
        config: {
          systemInstruction: systemInstruction,
          responseMimeType: "application/json",
          responseSchema: schema,
          temperature: 0.0,
        },
      });

      const jsonText = response.text.trim();
      const result = JSON.parse(jsonText);

      if (
        result &&
        typeof result.bestSheetName === 'string' &&
        typeof result.bestHeaderRow === 'number' &&
        sheetPreviews.some(p => p.sheetName === result.bestSheetName) &&
        result.bestHeaderRow > 0
      ) {
        return result; 
      } else {
        throw new Error("Invalid response from AI model.");
      }
    } catch (error) {
      retries--;
      console.error(`Error analyzing sheet layout (retry ${totalRetries - retries} of ${totalRetries}):`, error);
      const errorString = JSON.stringify(error);
      if (retries > 0 && errorString.includes('429')) {
        const jitter = Math.random() * 1000;
        console.warn(`Rate limit hit on analyzeSheetLayout. Retrying in ${Math.round((delay + jitter) / 1000)}s...`);
        await new Promise(resolve => setTimeout(resolve, delay + jitter));
        delay *= 2;
      } else if (retries > 0) {
        await new Promise(resolve => setTimeout(resolve, 500));
      }
    }
  }

  console.warn("All retries failed for analyzeSheetLayout. Falling back to default.");
  return {
    bestSheetName: sheetPreviews[0]?.sheetName || '',
    bestHeaderRow: 1,
  };
}

function performStaticMapping(mappableFields: string[], fileHeaders: string[]): Record<string, string> {
  const mapping: Record<string, string> = {};
  const availableHeaders = [...fileHeaders];

  for (const field of mappableFields) {
    let bestMatch = 'N/A';
    let highestScore = -1;

    const fieldWords = new Set(field.toLowerCase().replace(/[_-]/g, ' ').split(/\s+/).filter(w => w.length > 2));

    for (const header of availableHeaders) {
      if (!header) continue;

      let currentScore = 0;
      const headerLower = header.toLowerCase();

      if (headerLower === field.toLowerCase()) {
        currentScore = 100;
      } else if (headerLower.includes(field.toLowerCase()) || field.toLowerCase().includes(headerLower)) {
        currentScore = 50;
      }

      const headerWords = new Set(headerLower.replace(/[_-]/g, ' ').split(/\s+/).filter(Boolean));
      let sharedWords = 0;
      for (const fWord of fieldWords) {
        if (headerWords.has(fWord)) {
          sharedWords++;
        }
      }
      currentScore += sharedWords * 10;

      if (currentScore > highestScore) {
        highestScore = currentScore;
        bestMatch = header;
      }
    }

    if (highestScore > 10) { 
        mapping[field] = bestMatch;
    } else {
        mapping[field] = 'N/A';
    }
  }

  return mapping;
}

