  initializeDatabase();

  const record = parsedDatabase?.get(id);
  if (!record) return null;

  // Map Color to Rating Enum
  let rating = Rating.NA;
  const color = record.RatingColor.toLowerCase();
  if (color === 'green') rating = Rating.BestChoice;
  else if (color === 'yellow') rating = Rating.GoodAlternative;
  else if (color === 'red') rating = Rating.Avoid;
  else if (color === 'certified') rating = Rating.Certified;

  // Construct Official KDE string
  // Format: Species | Location | Method
  const locationParts = [record.SubnationalArea, record.EconomicZone].filter(p => p && p !== '""').join(', ');
  const matchedKDEs = `${record.CommonName} | ${locationParts} | ${record.Methods}`;

  return {
    matchedKDEs,
    rating
  };
}

