  const [previewData, setPreviewData] = useState<(string|number)[][]>([]);
  const [isPreviewLoading, setIsPreviewLoading] = useState<boolean>(false);
  const [previewWarning, setPreviewWarning] = useState<string | null>(null);


  const [uploadHistory, setUploadHistory] = useState<UploadSummary[]>([]);
  const [progress, setProgress] = useState<{ processed: number; total: number } | null>(null);

  // State for results view
  const [resultsViewMode, setResultsViewMode] = useState<ResultsViewMode>('table');
  const [activeFilter, setActiveFilter] = useState<{title: string; data: any[]} | null>(null);
  const [isFilterModalOpen, setIsFilterModalOpen] = useState(false);
  const [modalFilterData, setModalFilterData] = useState<{title: string; data: SeafoodResultItem[]} | null>(null);

  const analysisAbortController = useRef<AbortController | null>(null);


  useEffect(() => {
    // Load history on initial mount
    setUploadHistory(getUploadHistory());

    // Attempt to load the full database from the root/public folder.
    // Ensure you place 'seafood-watch-data.csv' in your public folder for production.
    loadDatabaseFromUrl('seafood-watch-data.csv');
  }, []);

  const resetAnalyzerState = () => {
    setResults(null);
    setDisplayResults(null);
    setDisplayHeaders([]);
    setError(null);
    setOriginalData(null);
    setOriginalHeaders([]);
    setCurrentFileName('');
    setProgress(null);
    setWorkbook(null);
    setSheetNames([]);
    setSelectedSheet('');
    setHeaderRowIndex(1);
    setPreviewData([]);
    setColumnMapping({});
    setAuditReport(null);
    setVisibleColumns(new Set());
    setResultsViewMode('table');
    setActiveFilter(null);
    setIsFilterModalOpen(false);
    setModalFilterData(null);
    setAnalyzerState('upload');
    setIsPreviewLoading(false);
    setPreviewWarning(null);
    analysisAbortController.current = null;
  };

  const generatePreviewData = (worksheet: any) => {
    const previewJson: (string|number)[][] = XLSX.utils.sheet_to_json(worksheet, { header: 1, defval: '', raw: false, blankrows: false });
    setPreviewData(previewJson.slice(0, 15)); // Preview first 15 rows
  };

  const handleProcessFile = useCallback(async (file: File) => {
    resetAnalyzerState();
    setAnalyzerState('preview');
    setIsPreviewLoading(true);

    const reader = new FileReader();
    reader.onload = async (e) => {
      try {
        const data = e.target?.result;
        if (!data) throw new Error("File data could not be read.");

        let wb: any;
        try {
          wb = XLSX.read(data, { type: 'binary', cellNF: false, cellText: false });
        } catch (parseError) {
          console.error("File parsing error:", parseError);
          throw new Error("Could not parse file. Please ensure it is a valid, uncorrupted XLSX or CSV file.");
        }

        const names = wb.SheetNames;
        if (names.length === 0) {
          throw new Error("The uploaded file is empty or contains no sheets.");
        }

        setWorkbook(wb);
        setSheetNames(names);
        setCurrentFileName(file.name);

        let bestSheetName = names[0];
        let bestHeaderRow = 1;

        try {
          const sheetPreviews = names.map(name => {
            const ws = wb.Sheets[name];
            const sheetData = XLSX.utils.sheet_to_json(ws, { header: 1, defval: '', raw: false, blankrows: false }).slice(0, 15);
            return { sheetName: name, data: sheetData };
          });

          const layout = await analyzeSheetLayout(sheetPreviews);
          bestSheetName = layout.bestSheetName;
          bestHeaderRow = layout.bestHeaderRow;
        } catch (aiError) {
          console.warn("AI sheet analysis failed, falling back to default.", aiError);
          setPreviewWarning("AI analysis for sheet layout failed. We've selected the first sheet and header row as a default. Please verify the selections are correct.");
        }

        setSelectedSheet(bestSheetName);
        setHeaderRowIndex(bestHeaderRow);
        generatePreviewData(wb.Sheets[bestSheetName]);

      } catch (err: any) {
        console.error(err);
        setError(`Error processing file: ${err.message}`);
        setAnalyzerState('upload');
      } finally {
        setIsPreviewLoading(false);
      }
    };
    reader.onerror = () => {
      setError('There was an error reading the file. It may be too large or corrupted.');
      setAnalyzerState('upload');
      setIsPreviewLoading(false);
    }
    reader.readAsBinaryString(file);
  }, []);

  const handleSheetChange = (sheetName: string) => {
    if (workbook) {
      setSelectedSheet(sheetName);
      generatePreviewData(workbook.Sheets[sheetName]);
    }
  };

  const handleHeaderRowChange = (newRowIndex: number) => {
    setHeaderRowIndex(newRowIndex);
  };

  const handleConfirmPreview = useCallback(() => {
    setError(null);
    if (!workbook || !selectedSheet) {
        setError("Workbook data is missing. Please re-upload.");
        setAnalyzerState('upload');
        return;
    }

    try {
        const worksheet = workbook.Sheets[selectedSheet];
        const dataAsArray: any[][] = XLSX.utils.sheet_to_json(worksheet, { header: 1, defval: '', blankrows: false });

        if (dataAsArray.length < headerRowIndex) {
            throw new Error(`Header row ${headerRowIndex} does not exist in the data.`);
        }

        const rawHeaders: string[] = dataAsArray[headerRowIndex - 1].map(header => String(header).trim());

        const headers: string[] = [];
        const counts: Record<string, number> = {};

        for (const header of rawHeaders) {
            if (!header) {
                headers.push('');
                continue;
            }

            counts[header] = (counts[header] || 0) + 1;

            if (counts[header] > 1) {
                let newHeader = `${header} (${counts[header]})`;
                while (rawHeaders.includes(newHeader) || headers.includes(newHeader)) {
                    counts[header]++;
                    newHeader = `${header} (${counts[header]})`;
                }
                headers.push(newHeader);
            } else {
                headers.push(header);
            }
        }

        const jsonData = dataAsArray.slice(headerRowIndex).map(row => {
            const rowObject: SeafoodInputItem = {};
            headers.forEach((header, index) => {
                if(header) {
                    rowObject[header] = row[index];
                }
            });
            return rowObject;
        }).filter(obj => Object.keys(obj).length > 0);

        if (jsonData.length === 0) {
          throw new Error("The selected sheet and header row result in no data to process.");
        }

        setOriginalData(jsonData);
        setOriginalHeaders(headers.filter(h => h));
        setAnalyzerState('mapping');

    } catch(err: any) {
        setError(`Error processing sheet: ${err.message}`);
    }
  }, [workbook, selectedSheet, headerRowIndex]);

  const handleConfirmMapping = useCallback((mapping: Record<string, string>) => {
    if (!originalData) {
        setError("Original data missing.");
        setAnalyzerState('upload');
        return;
    }
    setColumnMapping(mapping);

    // Perform Audit
    const report = performDataAudit(originalData, mapping);
    setAuditReport(report);
    setAnalyzerState('audit');

  }, [originalData]);

  const handleStartAnalysis = useCallback(async () => {
    if (!originalData) return;

    setAnalyzerState('loading');
    setError(null);

    analysisAbortController.current = new AbortController();

    try {
        // Filter out rows that don't have a Common Name
        const commonNameHeader = columnMapping['Common name'];
        let dataToProcess = originalData;

        if (commonNameHeader && commonNameHeader !== 'N/A') {
            dataToProcess = originalData.filter(row => {
                const val = row[commonNameHeader];
                return val !== undefined && val !== null && String(val).trim() !== '';
            });
        }

        setProgress({ processed: 0, total: dataToProcess.length });

        if (dataToProcess.length === 0) {
             throw new Error("No valid rows found to process. Please ensure your data has values in the 'Common name' column.");
        }

        const transformedData = dataToProcess.map(row => {
            const newRow: { [key: string]: string | number } = {};
            for (const mappableField of MAPPABLE_FIELDS) {
                const userColumnName = columnMapping[mappableField];
                if (userColumnName && userColumnName !== 'N/A' && row[userColumnName] !== undefined) {
                    newRow[mappableField] = row[userColumnName];
                }
            }
            return newRow;
        });

        const handleProgressUpdate = (processed: number, total: number) => {
          setProgress({ processed, total });
        };

        const analysisResults = await rateSeafoodData(transformedData, handleProgressUpdate, analysisAbortController.current.signal);

        const finalResults = dataToProcess.map((originalItem, index) => {
            const analysisPart = analysisResults[index];

            return {
                ...originalItem,
                uniqueId: analysisPart.uniqueId,
                matchedKDEs: analysisPart.matchedKDEs, // Use the official KDEs returned by AI
                rating: analysisPart.rating,
                reliabilityScore: analysisPart.reliabilityScore,
                notes: analysisPart.notes,
            };
        });

        setResults(finalResults);

        const mappedHeaders = Object.values(columnMapping).filter(h => h && h !== 'N/A') as string[];
        const defaultVisible = new Set<string>([
            ...mappedHeaders,
            'uniqueId', 
            'rating', 
            'reliabilityScore', 
            'notes'
        ]);

        setDisplayResults(finalResults);
        setDisplayHeaders(originalHeaders);
        setVisibleColumns(defaultVisible);

        const matchedCount = finalResults.filter(r => r.rating !== Rating.NA).length;
        const matchPercentage = finalResults.length > 0 ? (matchedCount / finalResults.length) * 100 : 0;
        const totalReliability = finalResults.reduce((acc, r) => acc + r.reliabilityScore, 0);
        const averageReliability = finalResults.length > 0 ? totalReliability / finalResults.length : 0;
        const ratingDistribution = finalResults.reduce<{[key in Rating]?: number}>((acc, item) => {
            acc[item.rating] = (acc[item.rating] || 0) + 1;
            return acc;
        }, {});

        const noteCounts = finalResults.reduce((acc, item) => {
          acc[item.notes] = (acc[item.notes] || 0) + 1;
          return acc;
        }, {} as { [key: string]: number });
        const commonIssues = Object.entries(noteCounts)
          .sort(([, countA], [, countB]) => (countB as number) - (countA as number))
          .slice(0, 5)
          .map(([issue, count]) => ({ issue, count: count as number }));
        const newHistory = saveUploadToHistory({
            fileName: currentFileName, rowCount: finalResults.length, matchPercentage,
            averageReliability, ratingDistribution, commonIssues,
        });
        setUploadHistory(newHistory);
        setAnalyzerState('results');

    } catch (err: any) {
        if (err.name === 'AbortError' || err.message.includes('aborted')) {
            console.log('Analysis was cancelled by the user.');
            return;
        }
        console.error(err);
        setError(`An error occurred during analysis: ${err.message}`);
        setAnalyzerState('audit'); // Go back to audit on error so they can retry
    }
  }, [originalData, currentFileName, originalHeaders, columnMapping]);

  const handleCancelAnalysis = useCallback(() => {
    if (analysisAbortController.current) {
        analysisAbortController.current.abort();
    }
    setAnalyzerState('audit');
    setError(null);
  }, []);

  const handleUpdateResult = useCallback(async (index: number, newUniqueId: string) => {
     if (!results || !results[index]) return;

     // Optimistic update to show loading state
     const updatedResults = [...results];
     updatedResults[index] = { ...updatedResults[index], isUpdating: true, uniqueId: newUniqueId };
     setResults(updatedResults);
     setDisplayResults(updatedResults);

     try {
         const originalItem = updatedResults[index];
         const updatedAnalysis = await updateAnalysisForId(originalItem, newUniqueId);

         const finalResults = [...results];
         finalResults[index] = {
             ...originalItem,
             ...updatedAnalysis,
             isUpdating: false
         };

         setResults(finalResults);
         setDisplayResults(finalResults);

     } catch (err) {
         console.error("Failed to update result:", err);
         // Revert on failure
         const revertedResults = [...results];
         revertedResults[index] = { ...revertedResults[index], isUpdating: false };
         setResults(revertedResults);
         setDisplayResults(revertedResults);
         setError("Failed to update the record. Please try again.");
     }
  }, [results]);

  const handleExport = useCallback(() => {
    if (!results || originalHeaders.length === 0) return;
    const headers = [...originalHeaders, 'Unique ID', 'Matched KDEs', 'Rating', 'Reliability Score', 'Notes'];
    const escapeCsv = (val: any): string => {
        if (val === undefined || val === null) return '';
        const str = String(val);
        if (str.includes(',') || str.includes('"') || str.includes('\n')) {
            return `"${str.replace(/"/g, '""')}"`;
        }
        return str;
    };
    const csvContent = [
        headers.join(','),
        ...results.map(row => {
            const originalValues = originalHeaders.map(header => escapeCsv(row[header]));
            const analysisValues = [
                escapeCsv(row.uniqueId), 
                escapeCsv(row.matchedKDEs),
                escapeCsv(row.rating), 
                escapeCsv(row.reliabilityScore), 
                escapeCsv(row.notes)
            ];
            return [...originalValues, ...analysisValues].join(',');
        })
    ].join('\n');
    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    if (link.href) URL.revokeObjectURL(link.href);
    const url = URL.createObjectURL(blob);
    link.href = url;
    link.setAttribute('download', `${currentFileName.replace(/\.[^/.]+$/, "")}_analyzed.csv`);
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  }, [results, originalHeaders, currentFileName]);

  const handleChartSegmentClick = (title: string, data: SeafoodResultItem[]) => {
    setModalFilterData({ title, data });
    setIsFilterModalOpen(true);
  };
  const handleConfirmFilter = () => {
    if (modalFilterData) {
      setActiveFilter({ title: modalFilterData.title, data: modalFilterData.data });
      setResultsViewMode('table');
    }
    setIsFilterModalOpen(false);
  };
  const handleClearFilter = () => setActiveFilter(null);
  const handleCancelFilter = () => setIsFilterModalOpen(false);
  const handleVisibleColumnsChange = (newVisible: Set<string>) => {
    setVisibleColumns(newVisible);
  };
  const handleCancel = () => resetAnalyzerState();
  const handleReturnToPreview = () => { setOriginalData(null); setOriginalHeaders([]); setAnalyzerState('preview'); };
  const handleReturnToMapping = () => { setAnalyzerState('mapping'); }; // New helper for Audit back button
  const handleAnalyzeNew = () => { resetAnalyzerState(); setView('analyzer'); };
  const handleReturnToDashboard = () => { resetAnalyzerState(); setView('dashboard'); };

  const renderContent = () => {
    if (view === 'dashboard') {
      return (
          <div className="animate-fade-in-up">
              <Dashboard history={uploadHistory} onAnalyzeNew={handleAnalyzeNew} />
          </div>
      );
    }

    // Analyzer Views Wrapper
    return (
      <div className="animate-fade-in-up" key={analyzerState}>
        {error && (
            <div className="bg-red-100 border border-red-400 text-red-700 px-4 py-3 rounded-lg relative my-6 max-w-4xl mx-auto" role="alert">
            <strong className="font-bold">Error:</strong><span className="block sm:inline ml-2">{error}</span>
            </div>
        )}
        {analyzerState === 'upload' && <FileUpload onProcessFile={handleProcessFile} isLoading={false} />}
        {analyzerState === 'preview' && <DataPreview isAnalyzing={isPreviewLoading} sheetNames={sheetNames} selectedSheet={selectedSheet} onSheetChange={handleSheetChange} headerRowIndex={headerRowIndex} onHeaderRowChange={handleHeaderRowChange} previewData={previewData} onConfirm={handleConfirmPreview} onCancel={handleCancel} warning={previewWarning}/>}
        {analyzerState === 'mapping' && originalHeaders.length > 0 && <ColumnMapper fileHeaders={originalHeaders} mappableFields={MAPPABLE_FIELDS} onConfirm={handleConfirmMapping} onCancel={handleReturnToPreview}/>}
        {analyzerState === 'audit' && auditReport && <DataQualityAudit report={auditReport} onConfirm={handleStartAnalysis} onBack={handleReturnToMapping} />}
        {analyzerState === 'loading' && <Loader progress={progress} onCancel={handleCancelAnalysis} />}
        {analyzerState === 'results' && results && displayResults && (
          <div className="flex flex-col items-center space-y-6">
            <div 
              className="flex justify-center p-1 bg-gray-200 rounded-lg"
              role="tablist"
              aria-label="Result view modes"
            >
              <button 
                id="tab-table"
                role="tab"
                aria-selected={resultsViewMode === 'table'}
                aria-controls="tabpanel-table"
                onClick={() => setResultsViewMode('table')} 
                className={`px-4 py-2 text-sm font-semibold rounded-md transition-colors ${resultsViewMode === 'table' ? 'bg-white shadow text-gray-800' : 'text-gray-600'}`}>
                  Table
              </button>
              <button 
                id="tab-charts"
                role="tab"
                aria-selected={resultsViewMode === 'charts'}
                aria-controls="tabpanel-charts"
                onClick={() => setResultsViewMode('charts')} 
                className={`px-4 py-2 text-sm font-semibold rounded-md transition-colors ${resultsViewMode === 'charts' ? 'bg-white shadow text-gray-800' : 'text-gray-600'}`}>
                  Charts
              </button>
            </div>

            <div className="w-full max-w-7xl">
              {resultsViewMode === 'table' ? (
                 <div id="tabpanel-table" role="tabpanel" aria-labelledby="tab-table">
                    <ResultsTable 
                        results={activeFilter ? activeFilter.data : displayResults} 
                        originalHeaders={displayHeaders} 
                        onExport={handleExport}
                        filterTitle={activeFilter?.title}
                        onClearFilter={handleClearFilter}
                        visibleColumns={visibleColumns}
                        onVisibleColumnsChange={handleVisibleColumnsChange}
                        onUpdateResult={handleUpdateResult}
                    />
                 </div>
              ) : (
                <div id="tabpanel-charts" role="tabpanel" aria-labelledby="tab-charts">
                    <ChartsView 
                        results={results} 
                        columnMapping={columnMapping} 
                        onSegmentClick={handleChartSegmentClick}
                    />
                </div>
              )}
            </div>

            <button onClick={handleReturnToDashboard} className="px-6 py-2 font-semibold text-white bg-[#00629B] rounded-md hover:bg-[#00497b] focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-[#00629B] transition-colors duration-200">Back to Dashboard</button>
          </div>
        )}
         <Modal 
            isOpen={isFilterModalOpen} 
            onClose={handleCancelFilter} 
            onConfirm={handleConfirmFilter}
            title="View Filtered Data"
         >
            <p>Would you like to see the {modalFilterData?.data.length} items for "{modalFilterData?.title}" in the data table?</p>
         </Modal>
      </div>
    );
  };

  return (
    <div className="min-h-screen bg-gray-50 text-gray-800 font-sans">
      <Header />
      <main className="container mx-auto p-4 sm:p-6 md:p-8">
        {renderContent()}
      </main>
      <footer className="text-center py-4 text-gray-500 text-sm">
        <p>&copy; {new Date().getFullYear()} Monterey Bay Aquarium Seafood Watch Program</p>
      </footer>
    </div>
  );
};

export default App;

import React, { useState, useCallback, useRef, useEffect, useMemo } from 'react';
import { SeafoodResultItem } from '../types';
import RatingBadge from './RatingBadge';
import ColumnToggler from './ColumnToggler';

interface ResultsTableProps {
  results: any[];
  originalHeaders: string[];
  onExport: () => void;
  filterTitle?: string;
  onClearFilter?: () => void;
  visibleColumns: Set<string>;
  onVisibleColumnsChange: (newVisible: Set<string>) => void;
  onUpdateResult?: (index: number, newUniqueId: string) => Promise<void>;
}

type SortDirection = 'ascending' | 'descending';

const SortIcon: React.FC<{ direction: SortDirection | null }> = ({ direction }) => {
    if (!direction) return null;
    return (
      <svg
        className="w-4 h-4 ml-1 inline-block text-gray-500 flex-shrink-0"
        aria-hidden="true"
        fill="currentColor"
        viewBox="0 0 20 20"
        xmlns="http://www.w3.org/2000/svg"
      >
        {direction === 'descending' ? (
          <path
            fillRule="evenodd"
            d="M5.293 7.293a1 1 0 011.414 0L10 10.586l3.293-3.293a1 1 0 111.414 1.414l-4 4a1 1 0 01-1.414 0l-4-4a1 1 0 010-1.414z"
            clipRule="evenodd"
          />
        ) : (
          <path
            fillRule="evenodd"
            d="M14.707 12.707a1 1 0 01-1.414 0L10 9.414l-3.293 3.293a1 1 0 01-1.414-1.414l4-4a1 1 0 011.414 0l4 4a1 1 0 010 1.414z"
            clipRule="evenodd"
          />
        )}
      </svg>
    );
};


const ResultsTable: React.FC<ResultsTableProps> = ({ 
  results, 
  originalHeaders, 
  onExport, 
  filterTitle, 
  onClearFilter,
  visibleColumns, 
  onVisibleColumnsChange,
  onUpdateResult
}) => {
  const [columnWidths, setColumnWidths] = useState<Record<string, number>>({});
  const isResizing = useRef<string | null>(null);
  const [sortConfig, setSortConfig] = useState<{ key: string; direction: SortDirection } | null>(null);
  const [searchTerm, setSearchTerm] = useState('');

  // Popover State (replaces Tooltip)
  const [popover, setPopover] = useState<{ 
    content: string; 
    rect: DOMRect; 
    rowIndex: number; 
    currentId: string 
  } | null>(null);
  const popoverRef = useRef<HTMLDivElement>(null);

  // Edit State
  const [editingId, setEditingId] = useState<{ index: number; value: string } | null>(null);


  // Refs for synced scrolling
  const tableContainerRef = useRef<HTMLDivElement>(null);
  const topScrollRef = useRef<HTMLDivElement>(null);
  const [scrollWidth, setScrollWidth] = useState(0);

  const sortedResults = useMemo(() => {
    // Add original index to items to track them after sorting
    const itemsWithIndex = results.map((item, index) => ({ ...item, _originalIndex: index }));

    if (!sortConfig) {
      return itemsWithIndex;
    }
    const sortableItems = [...itemsWithIndex];
    sortableItems.sort((a, b) => {
        const aVal = a[sortConfig.key];
        const bVal = b[sortConfig.key];

        if (aVal == null) return 1;
        if (bVal == null) return -1;

        if (typeof aVal === 'number' && typeof bVal === 'number') {
            return sortConfig.direction === 'ascending' ? aVal - bVal : bVal - aVal;
        }

        const aStr = String(aVal);
        const bStr = String(bVal);
        const comparison = aStr.localeCompare(bStr, undefined, { numeric: true, sensitivity: 'base' });

        return sortConfig.direction === 'ascending' ? comparison : -comparison;
      });

    return sortableItems;
  }, [results, sortConfig]);

  const filteredAndSortedResults = useMemo(() => {
    if (!searchTerm) {
      return sortedResults;
    }
    const lowercasedFilter = searchTerm.toLowerCase();
    return sortedResults.filter(item => {
       const { _originalIndex, isUpdating, ...searchableItem } = item;
      return Object.values(searchableItem).some(value =>
        String(value).toLowerCase().includes(lowercasedFilter)
      );
    });
  }, [sortedResults, searchTerm]);

  // Sync scrollbars
  useEffect(() => {
    const syncScroll = (source: 'top' | 'bottom') => {
      const top = topScrollRef.current;
      const bottom = tableContainerRef.current;
      if (!top || !bottom) return;

      if (source === 'top') {
        bottom.scrollLeft = top.scrollLeft;
      } else {
        top.scrollLeft = bottom.scrollLeft;
      }
    };

    const top = topScrollRef.current;
    const bottom = tableContainerRef.current;

    if (top && bottom) {
      const handleTopScroll = () => syncScroll('top');
      const handleBottomScroll = () => syncScroll('bottom');

      top.addEventListener('scroll', handleTopScroll);
      bottom.addEventListener('scroll', handleBottomScroll);

      return () => {
        top.removeEventListener('scroll', handleTopScroll);
        bottom.removeEventListener('scroll', handleBottomScroll);
      };
    }
  }, []);

  // Update scroll width when data or columns change
  useEffect(() => {
    if (tableContainerRef.current) {
      setScrollWidth(tableContainerRef.current.scrollWidth);
    }
  }, [visibleColumns, filteredAndSortedResults, columnWidths]);

  // Handle outside clicks to close popover
  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
        if (popover && popoverRef.current && !popoverRef.current.contains(event.target as Node)) {
            setPopover(null);
        }
    };

    // Also close on scroll to prevent detached popovers
    const handleScroll = () => {
        if (popover) setPopover(null);
    };

    document.addEventListener('mousedown', handleClickOutside);
    window.addEventListener('scroll', handleScroll, true); // Capture phase for all scrollable elements

    return () => {
        document.removeEventListener('mousedown', handleClickOutside);
        window.removeEventListener('scroll', handleScroll, true);
    };
  }, [popover]);

  const requestSort = (key: string) => {
    let direction: SortDirection = 'ascending';
    if (sortConfig && sortConfig.key === key && sortConfig.direction === 'ascending') {
      direction = 'descending';
    }
    setSortConfig({ key, direction });
  };

  const handleIdClick = (e: React.MouseEvent, rowIndex: number, currentId: string, content: string) => {
    e.stopPropagation();
    const rect = e.currentTarget.getBoundingClientRect();
    setPopover({ 
        rowIndex, 
        currentId,
        content, 
        rect
    });
  };

   // Editing handlers
   const startEditing = (index: number, value: string) => {
    setEditingId({ index, value });
    setPopover(null); // Ensure popover is closed
};

const handleEditChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (editingId) {
        setEditingId({ ...editingId, value: e.target.value });
    }
};

const submitEdit = async () => {
    if (editingId && onUpdateResult) {
        const { index, value } = editingId;
        const originalItem = results[index];

        if (originalItem.uniqueId !== value) {
             await onUpdateResult(index, value);
        }
    }
    setEditingId(null);
};

const handleEditKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter') {
        submitEdit();
    } else if (e.key === 'Escape') {
        setEditingId(null);
    }
};


  if (!results.length) {
    return <p className="text-center text-gray-500 my-8">
        {filterTitle ? `No data matches the filter "${filterTitle}".` : 'No data to display.'}
    </p>;
  }

  const addedHeaders = [
    { key: 'uniqueId', title: 'Unique ID' },
    // Matched KDEs removed as column
    { key: 'rating', title: 'Rating' },
    { key: 'reliabilityScore', title: 'Reliability' },
    { key: 'notes', title: 'Notes' },
  ];

  const allColumns = [
    ...originalHeaders.map(h => ({ key: h, title: h })),
    ...addedHeaders.map(h => ({ key: h.key, title: h.title }))
  ];

  const visibleOriginalHeaders = originalHeaders.filter(h => visibleColumns.has(h));
  const visibleAddedHeaders = addedHeaders.filter(h => visibleColumns.has(h.key));

  useEffect(() => {
    setColumnWidths(prevWidths => {
        const newWidths = { ...prevWidths };
        visibleOriginalHeaders.forEach(h => {
            if (!newWidths[h]) newWidths[h] = 100;
        });
        visibleAddedHeaders.forEach(h => {
            if (!newWidths[h.key]) {
                if (h.key === 'notes') newWidths[h.key] = 400;
                else if (h.key === 'reliabilityScore') newWidths[h.key] = 90;
                else if (h.key === 'uniqueId') newWidths[h.key] = 90;
                else newWidths[h.key] = 90;
            }
        });
        return newWidths;
    });
  }, [visibleOriginalHeaders, visibleAddedHeaders]);

  const handleMouseDown = useCallback((e: React.MouseEvent<HTMLDivElement>, headerKey: string) => {
    isResizing.current = headerKey;
    const startX = e.clientX;
    const startWidth = columnWidths[headerKey] || 0;

    const handleMouseMove = (moveEvent: MouseEvent) => {
      if (isResizing.current !== headerKey) return;
      const width = startWidth + (moveEvent.clientX - startX);
      if (width > 50) { // Min width
        setColumnWidths(prev => ({ ...prev, [headerKey]: width }));
      }
    };

    const handleMouseUp = () => {
      isResizing.current = null;
      window.removeEventListener('mousemove', handleMouseMove);
      window.removeEventListener('mouseup', handleMouseUp);
      document.body.style.cursor = 'default';
      document.body.style.userSelect = 'auto';
    };

    window.addEventListener('mousemove', handleMouseMove);
    window.addEventListener('mouseup', handleMouseUp);
    e.preventDefault();
    document.body.style.cursor = 'col-resize';
    document.body.style.userSelect = 'none';
  }, [columnWidths]);

  const renderUniqueId = (item: any, originalIndex: number) => {
    if (item.isUpdating) {
        return (
           <div className="flex items-center space-x-2">
               <div className="w-3 h-3 border-2 border-blue-600 border-dashed rounded-full animate-spin"></div>
               <span className="text-xs text-gray-500">Updating...</span>
           </div>
        );
    }

    if (editingId && editingId.index === originalIndex) {
        return (
            <input
              type="text"
              value={editingId.value}
              onChange={handleEditChange}
              onBlur={submitEdit}
              onKeyDown={handleEditKeyDown}
              autoFocus
              className="w-full text-xs border-b border-blue-500 focus:outline-none bg-transparent"
            />
        );
    }

    // Determine if this item is the currently active popover source to highlight it
    const isActive = popover && popover.rowIndex === originalIndex;

    return (
      <span 
          className={`font-mono text-xs cursor-pointer px-2 py-1 rounded transition-colors border ${isActive ? 'bg-blue-600 text-white border-blue-600' : 'text-blue-700 hover:bg-blue-100 border-transparent hover:border-blue-200'}`}
          title="Click to view details & edit"
          onClick={(e) => handleIdClick(e, originalIndex, item.uniqueId, item.matchedKDEs)}
      >
          {item.uniqueId}
          <span className="sr-only">Click to view details</span>
      </span>
    );
  };

  const addedColumnRenderers: Record<string, (item: any, originalIndex: number) => React.ReactNode> = {
    uniqueId: (item, originalIndex) => renderUniqueId(item, originalIndex),
    rating: (item) => <RatingBadge rating={item.rating} />,
    reliabilityScore: (item) => (
        <div className="flex items-center" aria-label={`Reliability: ${item.reliabilityScore}%`}>
            <div role="progressbar" aria-valuenow={item.reliabilityScore} aria-valuemin={0} aria-valuemax={100} className="w-16 bg-gray-200 rounded-full h-2.5">
                <div className="bg-blue-600 h-2.5 rounded-full" style={{ width: `${item.reliabilityScore}%` }}></div>
            </div>
            <span className="ml-2 font-medium text-xs">{item.reliabilityScore}%</span>
        </div>
    ),
    notes: (item) => <span className="block leading-tight">{item.notes}</span>,
  };

  // Determine popover position
  const viewportWidth = typeof window !== 'undefined' ? window.innerWidth : 1000;
  const POPOVER_WIDTH = 320; // 20rem (w-80) approx 320px
  const POPOVER_OFFSET = 10;

  // Calculate availability on the right side
  const spaceOnRight = popover ? (viewportWidth - popover.rect.right) : 0;
  // If there isn't enough space on the right, place it on the left of the cell
  const placeOnLeft = spaceOnRight < (POPOVER_WIDTH + POPOVER_OFFSET);

  return (
    <div className="w-full bg-white p-6 md:p-8 rounded-lg shadow-lg border border-gray-200 relative">
      <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center mb-6 gap-4">
        <div className="flex-grow">
          <h2 id="results-heading" className="text-2xl font-bold text-gray-800">Analysis Results</h2>
          <p className="text-sm text-gray-500 mt-1">Tip: Click a Unique ID to view details or make corrections.</p>
          {filterTitle && (
            <div className="flex items-center gap-3 mt-2">
                <p className="text-sm text-gray-600">
                    Showing data for: <span className="font-semibold bg-blue-100 text-blue-800 px-2 py-1 rounded-md">{filterTitle}</span>
                </p>
                <button 
                    onClick={onClearFilter}
                    className="text-sm text-blue-600 hover:underline"
                >
                    Clear Filter
                </button>
            </div>
          )}
          <div className="mt-4 flex items-center gap-4">
            <div className="relative flex-grow max-w-sm">
                <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
                    <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5 text-gray-400" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" />
                    </svg>
                </div>
                <input
                    type="search"
                    id="table-search"
                    aria-label="Search results"
                    placeholder={`Search in ${results.length} results...`}
                    value={searchTerm}
                    onChange={(e) => setSearchTerm(e.target.value)}
                    className="block w-full pl-10 pr-3 py-2 border border-gray-300 rounded-md leading-5 bg-white placeholder-gray-500 focus:outline-none focus:placeholder-gray-400 focus:ring-1 focus:ring-blue-500 focus:border-blue-500 sm:text-sm"
                />
            </div>
            {searchTerm && (
                <button
                    onClick={() => setSearchTerm('')}
                    className="text-sm text-blue-600 hover:underline"
                >
                    Clear Search
                </button>
            )}
          </div>
        </div>
        <div className="flex items-center gap-4 flex-shrink-0">
          <ColumnToggler 
            allColumns={allColumns}
            visibleColumns={visibleColumns}
            onVisibilityChange={onVisibleColumnsChange}
          />
          <button
            onClick={onExport}
            className="flex items-center gap-2 px-4 py-2 text-sm font-semibold text-white bg-green-600 rounded-md hover:bg-green-700 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-green-600 transition-colors duration-200"
          >
            <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth="2">
                <path strokeLinecap="round" strokeLinejoin="round" d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-4l-4 4m0 0l-4-4m4 4V4" />
            </svg>
            Export Full Dataset (CSV)
          </button>
        </div>
      </div>

      {/* Top Scrollbar */}
      <div 
        ref={topScrollRef}
        className="overflow-x-auto w-full mb-1"
        style={{ height: '12px' }}
      >
        <div style={{ width: scrollWidth, height: '1px' }}></div>
      </div>

      <div 
        ref={tableContainerRef}
        className="overflow-x-auto max-h-[70vh]" // Constrain height for sticky header
      >
        {filteredAndSortedResults.length > 0 ? (
            <table className="min-w-full divide-y divide-gray-200 table-fixed" aria-labelledby="results-heading">
            {/* Sticky Header */}
            <thead className="bg-gray-100 sticky top-0 z-10 shadow-sm">
                <tr>
                {visibleOriginalHeaders.map((header) => (
                    <th 
                        key={header} 
                        scope="col" 
                        className="px-2 py-2 text-left text-xs font-bold text-gray-600 uppercase tracking-wider relative group bg-gray-100 align-bottom border-b border-gray-200"
                        style={{ width: columnWidths[header] ? `${columnWidths[header]}px` : undefined }}
                        aria-sort={sortConfig?.key === header ? sortConfig.direction : 'none'}
                    >
                    <button onClick={() => requestSort(header)} className="flex items-end w-full h-full">
                        <span className="whitespace-normal break-words leading-tight">{header}</span>
                        <SortIcon direction={sortConfig?.key === header ? sortConfig.direction : null} />
                    </button>
                    <div
                        onMouseDown={(e) => handleMouseDown(e, header)}
                        aria-hidden="true"
                        className="absolute top-0 right-0 h-full w-2 cursor-col-resize hover:bg-blue-200"
                    />
                    </th>
                ))}
                {visibleAddedHeaders.map((header) => (
                    <th 
                        key={header.key} 
                        scope="col" 
                        className="px-2 py-2 text-left text-xs font-bold text-blue-800 bg-blue-100 uppercase tracking-wider relative group align-bottom border-b border-blue-200"
                        style={{ width: columnWidths[header.key] ? `${columnWidths[header.key]}px` : undefined }}
                        aria-sort={sortConfig?.key === header.key ? sortConfig.direction : 'none'}
                    >
                    <button onClick={() => requestSort(header.key)} className="flex items-end w-full h-full">
                        <span className="whitespace-normal break-words leading-tight">{header.title}</span>
                        <SortIcon direction={sortConfig?.key === header.key ? sortConfig.direction : null} />
                    </button>
                    <div
                        onMouseDown={(e) => handleMouseDown(e, header.key)}
                        aria-hidden="true"
                        className="absolute top-0 right-0 h-full w-2 cursor-col-resize hover:bg-blue-300"
                    />
                    </th>
                ))}
                </tr>
            </thead>
            <tbody className="bg-white divide-y divide-gray-200">
                {filteredAndSortedResults.map((item, index) => (
                <tr key={index} className="hover:bg-gray-50">
                    {visibleOriginalHeaders.map((header) => (
                    <td key={`${header}-${index}`} className="px-2 py-2 text-xs text-gray-700 break-words align-top leading-tight">
                        {item[header]}
                    </td>
                    ))}
                    {visibleAddedHeaders.map((header) => (
                        <td key={`${header.key}-${index}`} className="px-2 py-2 text-xs text-gray-700 bg-blue-50/50 align-top leading-tight">
                            {addedColumnRenderers[header.key](item, item._originalIndex)}
                        </td>
                    ))}
                </tr>
                ))}
            </tbody>
            </table>
        ) : (
            <p className="text-center text-gray-500 my-8 py-4">
                No results found for your search: "{searchTerm}".
            </p>
        )}
      </div>

      {/* Sticky Popover Portal */}
      {popover && (
          <div 
            ref={popoverRef}
            className="fixed z-50 bg-white rounded-lg shadow-2xl border border-gray-200 w-80 max-w-[90vw] flex flex-col animate-fade-in-up"
            style={{ 
                top: popover.rect.top,
                left: placeOnLeft ? 'auto' : (popover.rect.right + POPOVER_OFFSET),
                right: placeOnLeft ? (viewportWidth - popover.rect.left + POPOVER_OFFSET) : 'auto',
                maxHeight: '300px'
            }}
          >
              <div className="px-4 py-3 border-b border-gray-100 bg-gray-50 rounded-t-lg flex justify-between items-center">
                  <span className="font-bold text-gray-700 text-sm">Seafood Watch Match Details</span>
                  <button 
                    onClick={() => setPopover(null)} 
                    className="text-gray-400 hover:text-gray-600 focus:outline-none"
                    aria-label="Close details"
                  >
                    <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" />
                    </svg>
                  </button>
              </div>
              <div className="p-4 text-sm text-gray-600 overflow-y-auto max-h-48">
                  <p className="mb-2"><span className="font-semibold text-gray-800">Current ID:</span> {popover.currentId}</p>
                  <p className="mb-1 font-semibold text-gray-800">Official Description:</p>
                  <p className="leading-relaxed bg-gray-50 p-2 rounded border border-gray-100">{popover.content || 'No description available.'}</p>
              </div>
              <div className="px-4 py-3 border-t border-gray-100 bg-gray-50 rounded-b-lg flex justify-end">
                  <button 
                      onClick={() => startEditing(popover.rowIndex, popover.currentId)}
                      className="text-white bg-blue-600 hover:bg-blue-700 px-3 py-1.5 rounded text-xs font-semibold uppercase tracking-wide transition-colors shadow-sm"
                  >
                      Edit ID
                  </button>
              </div>
          </div>
      )}
    </div>
  );
};

export default ResultsTable;

import React, { useState, useCallback, useEffect, useRef } from 'react';
import { SeafoodInputItem, SeafoodResultItem, Rating, UploadSummary } from './types';
import { rateSeafoodData, analyzeSheetLayout, updateAnalysisForId } from './services/geminiService';
import { loadDatabaseFromUrl } from './services/referenceDatabase';
import { getUploadHistory, saveUploadToHistory } from './services/historyService';
import { performDataAudit, AuditReport } from './services/dataAuditService';
import Header from './components/Header';
import FileUpload from './components/FileUpload';
import ResultsTable from './components/ResultsTable';
import Loader from './components/Loader';
import Dashboard from './components/Dashboard';
import ColumnMapper from './components/ColumnMapper';
import DataPreview from './components/DataPreview';
import ChartsView from './components/ChartsView';
import Modal from './components/Modal';
import DataQualityAudit from './components/DataQualityAudit';

// This declaration is necessary because the library is loaded from a script tag in index.html
declare var XLSX: any;

type View = 'dashboard' | 'analyzer';
type AnalyzerState = 'upload' | 'preview' | 'mapping' | 'audit' | 'loading' | 'results';
type ResultsViewMode = 'table' | 'charts';

const MAPPABLE_FIELDS = [
  'Wild or Farmed',
  'Common name',
  'Scientific name',
  'Source country',
  'Body of water',
  'Production Method',
  'Certification',
  'Supplier',
  'Product Name',
  'Volume',
];

const App: React.FC = () => {
  const [view, setView] = useState<View>('dashboard');
  const [analyzerState, setAnalyzerState] = useState<AnalyzerState>('upload');
  const [results, setResults] = useState<SeafoodResultItem[] | null>(null);
  const [error, setError] = useState<string | null>(null);

  // State for raw data and headers
  const [originalData, setOriginalData] = useState<SeafoodInputItem[] | null>(null);
  const [originalHeaders, setOriginalHeaders] = useState<string[]>([]);
  const [currentFileName, setCurrentFileName] = useState<string>('');

  // State for column mapping and display-optimized results
  const [columnMapping, setColumnMapping] = useState<Record<string, string>>({});
  const [displayResults, setDisplayResults] = useState<any[] | null>(null);
  const [displayHeaders, setDisplayHeaders] = useState<string[]>([]);
  const [visibleColumns, setVisibleColumns] = useState<Set<string>>(new Set());
  const [auditReport, setAuditReport] = useState<AuditReport | null>(null);


  // State for preview step
  const [workbook, setWorkbook] = useState<any>(null); // XLSX workbook object
  const [sheetNames, setSheetNames] = useState<string[]>([]);
  const [selectedSheet, setSelectedSheet] = useState<string>('');
  const [headerRowIndex, setHeaderRowIndex] = useState<number>(1);
  const [previewData, setPreviewData] = useState<(string|number)[][]>([]);
  const [isPreviewLoading, setIsPreviewLoading] = useState<boolean>(false);
  const [previewWarning, setPreviewWarning] = useState<string | null>(null);


  const [uploadHistory, setUploadHistory] = useState<UploadSummary[]>([]);
  const [progress, setProgress] = useState<{ processed: number; total: number } | null>(null);

  // State for results view
  const [resultsViewMode, setResultsViewMode] = useState<ResultsViewMode>('table');
  const [activeFilter, setActiveFilter] = useState<{title: string; data: any[]} | null>(null);
  const [isFilterModalOpen, setIsFilterModalOpen] = useState(false);
  const [modalFilterData, setModalFilterData] = useState<{title: string; data: SeafoodResultItem[]} | null>(null);

  const analysisAbortController = useRef<AbortController | null>(null);


  useEffect(() => {
    // Load history on initial mount
    setUploadHistory(getUploadHistory());

    // Attempt to load the full database from the root/public folder.
    // Ensure you place 'seafood-watch-data.csv' in your public folder for production.
    loadDatabaseFromUrl('seafood-watch-data.csv');
  }, []);

  const resetAnalyzerState = () => {
    setResults(null);
    setDisplayResults(null);
    setDisplayHeaders([]);
    setError(null);
    setOriginalData(null);
    setOriginalHeaders([]);
    setCurrentFileName('');
    setProgress(null);
    setWorkbook(null);
    setSheetNames([]);
    setSelectedSheet('');
    setHeaderRowIndex(1);
    setPreviewData([]);
    setColumnMapping({});
    setAuditReport(null);
    setVisibleColumns(new Set());
    setResultsViewMode('table');
    setActiveFilter(null);
    setIsFilterModalOpen(false);
    setModalFilterData(null);
    setAnalyzerState('upload');
    setIsPreviewLoading(false);
    setPreviewWarning(null);
    analysisAbortController.current = null;
  };

  const generatePreviewData = (worksheet: any) => {
    const previewJson: (string|number)[][] = XLSX.utils.sheet_to_json(worksheet, { header: 1, defval: '', raw: false, blankrows: false });
    setPreviewData(previewJson.slice(0, 15)); // Preview first 15 rows
  };

  const handleProcessFile = useCallback(async (file: File) => {
    resetAnalyzerState();
    setAnalyzerState('preview');
    setIsPreviewLoading(true);

    const reader = new FileReader();
    reader.onload = async (e) => {
      try {
        const data = e.target?.result;
        if (!data) throw new Error("File data could not be read.");

        let wb: any;
        try {
          wb = XLSX.read(data, { type: 'binary', cellNF: false, cellText: false });
        } catch (parseError) {
          console.error("File parsing error:", parseError);
          throw new Error("Could not parse file. Please ensure it is a valid, uncorrupted XLSX or CSV file.");
        }

        const names = wb.SheetNames;
        if (names.length === 0) {
          throw new Error("The uploaded file is empty or contains no sheets.");
        }

        setWorkbook(wb);
        setSheetNames(names);
        setCurrentFileName(file.name);

        let bestSheetName = names[0];
        let bestHeaderRow = 1;

        try {
          const sheetPreviews = names.map(name => {
            const ws = wb.Sheets[name];
            const sheetData = XLSX.utils.sheet_to_json(ws, { header: 1, defval: '', raw: false, blankrows: false }).slice(0, 15);
            return { sheetName: name, data: sheetData };
          });

          const layout = await analyzeSheetLayout(sheetPreviews);
          bestSheetName = layout.bestSheetName;
          bestHeaderRow = layout.bestHeaderRow;
        } catch (aiError) {
          console.warn("AI sheet analysis failed, falling back to default.", aiError);
          setPreviewWarning("AI analysis for sheet layout failed. We've selected the first sheet and header row as a default. Please verify the selections are correct.");
        }

        setSelectedSheet(bestSheetName);
        setHeaderRowIndex(bestHeaderRow);
        generatePreviewData(wb.Sheets[bestSheetName]);

      } catch (err: any) {
        console.error(err);
        setError(`Error processing file: ${err.message}`);
        setAnalyzerState('upload');
      } finally {
        setIsPreviewLoading(false);
      }
    };
    reader.onerror = () => {
      setError('There was an error reading the file. It may be too large or corrupted.');
      setAnalyzerState('upload');
      setIsPreviewLoading(false);
    }
    reader.readAsBinaryString(file);
  }, []);

  const handleSheetChange = (sheetName: string) => {
    if (workbook) {
      setSelectedSheet(sheetName);
      generatePreviewData(workbook.Sheets[sheetName]);
    }
  };

  const handleHeaderRowChange = (newRowIndex: number) => {
    setHeaderRowIndex(newRowIndex);
  };

  const handleConfirmPreview = useCallback(() => {
    setError(null);
    if (!workbook || !selectedSheet) {
        setError("Workbook data is missing. Please re-upload.");
        setAnalyzerState('upload');
        return;
    }

    try {
        const worksheet = workbook.Sheets[selectedSheet];
        const dataAsArray: any[][] = XLSX.utils.sheet_to_json(worksheet, { header: 1, defval: '', blankrows: false });

        if (dataAsArray.length < headerRowIndex) {
            throw new Error(`Header row ${headerRowIndex} does not exist in the data.`);
        }

        const rawHeaders: string[] = dataAsArray[headerRowIndex - 1].map(header => String(header).trim());

        const headers: string[] = [];
        const counts: Record<string, number> = {};

        for (const header of rawHeaders) {
            if (!header) {
                headers.push('');
                continue;
            }

            counts[header] = (counts[header] || 0) + 1;

            if (counts[header] > 1) {
                let newHeader = `${header} (${counts[header]})`;
                while (rawHeaders.includes(newHeader) || headers.includes(newHeader)) {
                    counts[header]++;
                    newHeader = `${header} (${counts[header]})`;
                }
                headers.push(newHeader);
            } else {
                headers.push(header);
            }
        }

        const jsonData = dataAsArray.slice(headerRowIndex).map(row => {
            const rowObject: SeafoodInputItem = {};
            headers.forEach((header, index) => {
                if(header) {
                    rowObject[header] = row[index];
                }
            });
            return rowObject;
        }).filter(obj => Object.keys(obj).length > 0);

        if (jsonData.length === 0) {
          throw new Error("The selected sheet and header row result in no data to process.");
        }

        setOriginalData(jsonData);
        setOriginalHeaders(headers.filter(h => h));
        setAnalyzerState('mapping');

    } catch(err: any) {
        setError(`Error processing sheet: ${err.message}`);
    }
  }, [workbook, selectedSheet, headerRowIndex]);

  const handleConfirmMapping = useCallback((mapping: Record<string, string>) => {
    if (!originalData) {
        setError("Original data missing.");
        setAnalyzerState('upload');
        return;
    }
    setColumnMapping(mapping);

    // Perform Audit
    const report = performDataAudit(originalData, mapping);
    setAuditReport(report);
    setAnalyzerState('audit');

  }, [originalData]);

  const handleStartAnalysis = useCallback(async () => {
    if (!originalData) return;

    setAnalyzerState('loading');
    setError(null);

    analysisAbortController.current = new AbortController();

    try {
        // Filter out rows that don't have a Common Name
        const commonNameHeader = columnMapping['Common name'];
        let dataToProcess = originalData;

        if (commonNameHeader && commonNameHeader !== 'N/A') {
            dataToProcess = originalData.filter(row => {
                const val = row[commonNameHeader];
                return val !== undefined && val !== null && String(val).trim() !== '';
            });
        }

        setProgress({ processed: 0, total: dataToProcess.length });

        if (dataToProcess.length === 0) {
             throw new Error("No valid rows found to process. Please ensure your data has values in the 'Common name' column.");
        }

        const transformedData = dataToProcess.map(row => {
            const newRow: { [key: string]: string | number } = {};
            for (const mappableField of MAPPABLE_FIELDS) {
                const userColumnName = columnMapping[mappableField];
                if (userColumnName && userColumnName !== 'N/A' && row[userColumnName] !== undefined) {
                    newRow[mappableField] = row[userColumnName];
                }
            }
            return newRow;
        });

        const handleProgressUpdate = (processed: number, total: number) => {
          setProgress({ processed, total });
        };

        const analysisResults = await rateSeafoodData(transformedData, handleProgressUpdate, analysisAbortController.current.signal);

        const finalResults = dataToProcess.map((originalItem, index) => {
            const analysisPart = analysisResults[index];

            return {
                ...originalItem,
                uniqueId: analysisPart.uniqueId,
                matchedKDEs: analysisPart.matchedKDEs, // Use the official KDEs returned by AI
                rating: analysisPart.rating,
                reliabilityScore: analysisPart.reliabilityScore,
                notes: analysisPart.notes,
            };
        });

        setResults(finalResults);

        const mappedHeaders = Object.values(columnMapping).filter(h => h && h !== 'N/A') as string[];
        const defaultVisible = new Set<string>([
            ...mappedHeaders,
            'uniqueId', 
            'rating', 
            'reliabilityScore', 
            'notes'
        ]);

        setDisplayResults(finalResults);
        setDisplayHeaders(originalHeaders);
        setVisibleColumns(defaultVisible);

        const matchedCount = finalResults.filter(r => r.rating !== Rating.NA).length;
        const matchPercentage = finalResults.length > 0 ? (matchedCount / finalResults.length) * 100 : 0;
        const totalReliability = finalResults.reduce((acc, r) => acc + r.reliabilityScore, 0);
        const averageReliability = finalResults.length > 0 ? totalReliability / finalResults.length : 0;
        const ratingDistribution = finalResults.reduce<{[key in Rating]?: number}>((acc, item) => {
            acc[item.rating] = (acc[item.rating] || 0) + 1;
            return acc;
        }, {});

        const noteCounts = finalResults.reduce((acc, item) => {
          acc[item.notes] = (acc[item.notes] || 0) + 1;
          return acc;
        }, {} as { [key: string]: number });
        const commonIssues = Object.entries(noteCounts)
          .sort(([, countA], [, countB]) => (countB as number) - (countA as number))
          .slice(0, 5)
          .map(([issue, count]) => ({ issue, count: count as number }));
        const newHistory = saveUploadToHistory({
            fileName: currentFileName, rowCount: finalResults.length, matchPercentage,
            averageReliability, ratingDistribution, commonIssues,
        });
        setUploadHistory(newHistory);
        setAnalyzerState('results');

    } catch (err: any) {
        if (err.name === 'AbortError' || err.message.includes('aborted')) {
            console.log('Analysis was cancelled by the user.');
            return;
        }
        console.error(err);
        setError(`An error occurred during analysis: ${err.message}`);
        setAnalyzerState('audit'); // Go back to audit on error so they can retry
    }
  }, [originalData, currentFileName, originalHeaders, columnMapping]);

  const handleCancelAnalysis = useCallback(() => {
    if (analysisAbortController.current) {
        analysisAbortController.current.abort();
    }
    setAnalyzerState('audit');
    setError(null);
  }, []);

  const handleUpdateResult = useCallback(async (index: number, newUniqueId: string) => {
     if (!results || !results[index]) return;

     // Optimistic update to show loading state
     const updatedResults = [...results];
     updatedResults[index] = { ...updatedResults[index], isUpdating: true, uniqueId: newUniqueId };
     setResults(updatedResults);
     setDisplayResults(updatedResults);

     try {
         const originalItem = updatedResults[index];
         const updatedAnalysis = await updateAnalysisForId(originalItem, newUniqueId);

         const finalResults = [...results];
         finalResults[index] = {
             ...originalItem,
             ...updatedAnalysis,
             isUpdating: false
         };

         setResults(finalResults);
         setDisplayResults(finalResults);

     } catch (err) {
         console.error("Failed to update result:", err);
         // Revert on failure
         const revertedResults = [...results];
         revertedResults[index] = { ...revertedResults[index], isUpdating: false };
         setResults(revertedResults);
         setDisplayResults(revertedResults);
         setError("Failed to update the record. Please try again.");
     }
  }, [results]);

  const handleExport = useCallback(() => {
    if (!results || originalHeaders.length === 0) return;
    const headers = [...originalHeaders, 'Unique ID', 'Matched KDEs', 'Rating', 'Reliability Score', 'Notes'];
    const escapeCsv = (val: any): string => {
        if (val === undefined || val === null) return '';
        const str = String(val);
        if (str.includes(',') || str.includes('"') || str.includes('\n')) {
            return `"${str.replace(/"/g, '""')}"`;
        }
        return str;
    };
    const csvContent = [
        headers.join(','),
        ...results.map(row => {
            const originalValues = originalHeaders.map(header => escapeCsv(row[header]));
            const analysisValues = [
                escapeCsv(row.uniqueId), 
                escapeCsv(row.matchedKDEs),
                escapeCsv(row.rating), 
                escapeCsv(row.reliabilityScore), 
                escapeCsv(row.notes)
            ];
            return [...originalValues, ...analysisValues].join(',');
        })
    ].join('\n');
    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    if (link.href) URL.revokeObjectURL(link.href);
    const url = URL.createObjectURL(blob);
    link.href = url;
    link.setAttribute('download', `${currentFileName.replace(/\.[^/.]+$/, "")}_analyzed.csv`);
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  }, [results, originalHeaders, currentFileName]);

  const handleChartSegmentClick = (title: string, data: SeafoodResultItem[]) => {
    setModalFilterData({ title, data });
    setIsFilterModalOpen(true);
  };
  const handleConfirmFilter = () => {
    if (modalFilterData) {
      setActiveFilter({ title: modalFilterData.title, data: modalFilterData.data });
      setResultsViewMode('table');
    }
    setIsFilterModalOpen(false);
  };
  const handleClearFilter = () => setActiveFilter(null);
  const handleCancelFilter = () => setIsFilterModalOpen(false);
  const handleVisibleColumnsChange = (newVisible: Set<string>) => {
    setVisibleColumns(newVisible);
  };
  const handleCancel = () => resetAnalyzerState();
  const handleReturnToPreview = () => { setOriginalData(null); setOriginalHeaders([]); setAnalyzerState('preview'); };
  const handleReturnToMapping = () => { setAnalyzerState('mapping'); }; // New helper for Audit back button
  const handleAnalyzeNew = () => { resetAnalyzerState(); setView('analyzer'); };
  const handleReturnToDashboard = () => { resetAnalyzerState(); setView('dashboard'); };

  const renderContent = () => {
    if (view === 'dashboard') {
      return (
          <div className="animate-fade-in-up">
              <Dashboard history={uploadHistory} onAnalyzeNew={handleAnalyzeNew} />
          </div>
      );
    }

    // Analyzer Views Wrapper
    return (
      <div className="animate-fade-in-up" key={analyzerState}>
        {error && (
            <div className="bg-red-100 border border-red-400 text-red-700 px-4 py-3 rounded-lg relative my-6 max-w-4xl mx-auto" role="alert">
            <strong className="font-bold">Error:</strong><span className="block sm:inline ml-2">{error}</span>
            </div>
        )}
        {analyzerState === 'upload' && <FileUpload onProcessFile={handleProcessFile} isLoading={false} />}
        {analyzerState === 'preview' && <DataPreview isAnalyzing={isPreviewLoading} sheetNames={sheetNames} selectedSheet={selectedSheet} onSheetChange={handleSheetChange} headerRowIndex={headerRowIndex} onHeaderRowChange={handleHeaderRowChange} previewData={previewData} onConfirm={handleConfirmPreview} onCancel={handleCancel} warning={previewWarning}/>}
        {analyzerState === 'mapping' && originalHeaders.length > 0 && <ColumnMapper fileHeaders={originalHeaders} mappableFields={MAPPABLE_FIELDS} onConfirm={handleConfirmMapping} onCancel={handleReturnToPreview}/>}
        {analyzerState === 'audit' && auditReport && <DataQualityAudit report={auditReport} onConfirm={handleStartAnalysis} onBack={handleReturnToMapping} />}
        {analyzerState === 'loading' && <Loader progress={progress} onCancel={handleCancelAnalysis} />}
        {analyzerState === 'results' && results && displayResults && (
          <div className="flex flex-col items-center space-y-6">
            <div 
              className="flex justify-center p-1 bg-gray-200 rounded-lg"
              role="tablist"
              aria-label="Result view modes"
            >
              <button 
                id="tab-table"
                role="tab"
                aria-selected={resultsViewMode === 'table'}
                aria-controls="tabpanel-table"
                onClick={() => setResultsViewMode('table')} 
                className={`px-4 py-2 text-sm font-semibold rounded-md transition-colors ${resultsViewMode === 'table' ? 'bg-white shadow text-gray-800' : 'text-gray-600'}`}>
                  Table
              </button>
              <button 
                id="tab-charts"
                role="tab"
                aria-selected={resultsViewMode === 'charts'}
                aria-controls="tabpanel-charts"
                onClick={() => setResultsViewMode('charts')} 
                className={`px-4 py-2 text-sm font-semibold rounded-md transition-colors ${resultsViewMode === 'charts' ? 'bg-white shadow text-gray-800' : 'text-gray-600'}`}>
                  Charts
              </button>
            </div>

            <div className="w-full max-w-7xl">
              {resultsViewMode === 'table' ? (
                 <div id="tabpanel-table" role="tabpanel" aria-labelledby="tab-table">
                    <ResultsTable 
                        results={activeFilter ? activeFilter.data : displayResults} 
                        originalHeaders={displayHeaders} 
                        columnMapping={columnMapping}
                        onExport={handleExport}
                        filterTitle={activeFilter?.title}
                        onClearFilter={handleClearFilter}
                        visibleColumns={visibleColumns}
                        onVisibleColumnsChange={handleVisibleColumnsChange}
                        onUpdateResult={handleUpdateResult}
                    />
                 </div>
              ) : (
                <div id="tabpanel-charts" role="tabpanel" aria-labelledby="tab-charts">
                    <ChartsView 
                        results={results} 
                        columnMapping={columnMapping} 
                        onSegmentClick={handleChartSegmentClick}
                    />
                </div>
              )}
            </div>

            <button onClick={handleReturnToDashboard} className="px-6 py-2 font-semibold text-white bg-[#00629B] rounded-md hover:bg-[#00497b] focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-[#00629B] transition-colors duration-200">Back to Dashboard</button>
          </div>
        )}
         <Modal 
            isOpen={isFilterModalOpen} 
            onClose={handleCancelFilter} 
            onConfirm={handleConfirmFilter}
            title="View Filtered Data"
         >
            <p>Would you like to see the {modalFilterData?.data.length} items for "{modalFilterData?.title}" in the data table?</p>
         </Modal>
      </div>
    );
  };

  return (
    <div className="min-h-screen bg-gray-50 text-gray-800 font-sans">
      <Header />
      <main className="container mx-auto p-4 sm:p-6 md:p-8">
        {renderContent()}
      </main>
      <footer className="text-center py-4 text-gray-500 text-sm">
        <p>&copy; {new Date().getFullYear()} Monterey Bay Aquarium Seafood Watch Program</p>
      </footer>
    </div>
  );
};

export default App;

import React, { useState, useCallback, useRef, useEffect, useMemo } from 'react';
import { SeafoodResultItem } from '../types';
import RatingBadge from './RatingBadge';
import ColumnToggler from './ColumnToggler';

interface ResultsTableProps {
  results: any[];
  originalHeaders: string[];
  columnMapping?: Record<string, string>;
  onExport: () => void;
  filterTitle?: string;
  onClearFilter?: () => void;
  visibleColumns: Set<string>;
  onVisibleColumnsChange: (newVisible: Set<string>) => void;
  onUpdateResult?: (index: number, newUniqueId: string) => Promise<void>;
}

type SortDirection = 'ascending' | 'descending';

const SortIcon: React.FC<{ direction: SortDirection | null }> = ({ direction }) => {
    if (!direction) return null;
    return (
      <svg
        className="w-4 h-4 ml-1 inline-block text-gray-500 flex-shrink-0"
        aria-hidden="true"
        fill="currentColor"
        viewBox="0 0 20 20"
        xmlns="http://www.w3.org/2000/svg"
      >
        {direction === 'descending' ? (
          <path
            fillRule="evenodd"
            d="M5.293 7.293a1 1 0 011.414 0L10 10.586l3.293-3.293a1 1 0 111.414 1.414l-4 4a1 1 0 01-1.414 0l-4-4a1 1 0 010-1.414z"
            clipRule="evenodd"
          />
        ) : (
          <path
            fillRule="evenodd"
            d="M14.707 12.707a1 1 0 01-1.414 0L10 9.414l-3.293 3.293a1 1 0 01-1.414-1.414l4-4a1 1 0 011.414 0l4 4a1 1 0 010 1.414z"
            clipRule="evenodd"
          />
        )}
      </svg>
    );
};


const ResultsTable: React.FC<ResultsTableProps> = ({ 
  results, 
  originalHeaders,
  columnMapping = {},
  onExport, 
  filterTitle, 
  onClearFilter,
  visibleColumns, 
  onVisibleColumnsChange,
  onUpdateResult
}) => {
  const [columnWidths, setColumnWidths] = useState<Record<string, number>>({});
  const isResizing = useRef<string | null>(null);
  const [sortConfig, setSortConfig] = useState<{ key: string; direction: SortDirection } | null>(null);
  const [searchTerm, setSearchTerm] = useState('');

  // Expanded Row State (Accordion)
  const [expandedRowIndex, setExpandedRowIndex] = useState<number | null>(null);
  // Temporary state for the input field inside the expanded view
  const [editValue, setEditValue] = useState<string>('');


  // Refs for synced scrolling
  const tableContainerRef = useRef<HTMLDivElement>(null);
  const topScrollRef = useRef<HTMLDivElement>(null);
  const [scrollWidth, setScrollWidth] = useState(0);

  const sortedResults = useMemo(() => {
    // Add original index to items to track them after sorting
    const itemsWithIndex = results.map((item, index) => ({ ...item, _originalIndex: index }));

    if (!sortConfig) {
      return itemsWithIndex;
    }
    const sortableItems = [...itemsWithIndex];
    sortableItems.sort((a, b) => {
        const aVal = a[sortConfig.key];
        const bVal = b[sortConfig.key];

        if (aVal == null) return 1;
        if (bVal == null) return -1;

        if (typeof aVal === 'number' && typeof bVal === 'number') {
            return sortConfig.direction === 'ascending' ? aVal - bVal : bVal - aVal;
        }

        const aStr = String(aVal);
        const bStr = String(bVal);
        const comparison = aStr.localeCompare(bStr, undefined, { numeric: true, sensitivity: 'base' });

        return sortConfig.direction === 'ascending' ? comparison : -comparison;
      });

    return sortableItems;
  }, [results, sortConfig]);

  const filteredAndSortedResults = useMemo(() => {
    if (!searchTerm) {
      return sortedResults;
    }
    const lowercasedFilter = searchTerm.toLowerCase();
    return sortedResults.filter(item => {
       const { _originalIndex, isUpdating, ...searchableItem } = item;
      return Object.values(searchableItem).some(value =>
        String(value).toLowerCase().includes(lowercasedFilter)
      );
    });
  }, [sortedResults, searchTerm]);

  // Sync scrollbars
  useEffect(() => {
    const syncScroll = (source: 'top' | 'bottom') => {
      const top = topScrollRef.current;
      const bottom = tableContainerRef.current;
      if (!top || !bottom) return;

      if (source === 'top') {
        bottom.scrollLeft = top.scrollLeft;
      } else {
        top.scrollLeft = bottom.scrollLeft;
      }
    };

    const top = topScrollRef.current;
    const bottom = tableContainerRef.current;

    if (top && bottom) {
      const handleTopScroll = () => syncScroll('top');
      const handleBottomScroll = () => syncScroll('bottom');

      top.addEventListener('scroll', handleTopScroll);
      bottom.addEventListener('scroll', handleBottomScroll);

      return () => {
        top.removeEventListener('scroll', handleTopScroll);
        bottom.removeEventListener('scroll', handleBottomScroll);
      };
    }
  }, []);

  // Update scroll width when data or columns change
  useEffect(() => {
    if (tableContainerRef.current) {
      setScrollWidth(tableContainerRef.current.scrollWidth);
    }
  }, [visibleColumns, filteredAndSortedResults, columnWidths]);


  const requestSort = (key: string) => {
    let direction: SortDirection = 'ascending';
    if (sortConfig && sortConfig.key === key && sortConfig.direction === 'ascending') {
      direction = 'descending';
    }
    setSortConfig({ key, direction });
  };

  const toggleRow = (e: React.MouseEvent, rowIndex: number, currentId: string) => {
      e.stopPropagation();
      if (expandedRowIndex === rowIndex) {
          setExpandedRowIndex(null);
          setEditValue('');
      } else {
          setExpandedRowIndex(rowIndex);
          setEditValue(currentId);
      }
  };

  const handleSubmitEdit = async (index: number) => {
      if (onUpdateResult && editValue) {
          await onUpdateResult(index, editValue);
          // Don't close row automatically, user might want to see update.
      }
  };


  if (!results.length) {
    return <p className="text-center text-gray-500 my-8">
        {filterTitle ? `No data matches the filter "${filterTitle}".` : 'No data to display.'}
    </p>;
  }

  const addedHeaders = [
    { key: 'uniqueId', title: 'Unique ID' },
    { key: 'rating', title: 'Rating' },
    { key: 'reliabilityScore', title: 'Reliability' },
    { key: 'notes', title: 'Notes' },
  ];

  const allColumns = [
    ...originalHeaders.map(h => ({ key: h, title: h })),
    ...addedHeaders.map(h => ({ key: h.key, title: h.title }))
  ];

  const visibleOriginalHeaders = originalHeaders.filter(h => visibleColumns.has(h));
  const visibleAddedHeaders = addedHeaders.filter(h => visibleColumns.has(h.key));
  const totalColSpan = visibleOriginalHeaders.length + visibleAddedHeaders.length;

  useEffect(() => {
    setColumnWidths(prevWidths => {
        const newWidths = { ...prevWidths };
        visibleOriginalHeaders.forEach(h => {
            if (!newWidths[h]) newWidths[h] = 100;
        });
        visibleAddedHeaders.forEach(h => {
            if (!newWidths[h.key]) {
                if (h.key === 'notes') newWidths[h.key] = 400;
                else if (h.key === 'reliabilityScore') newWidths[h.key] = 90;
                else if (h.key === 'uniqueId') newWidths[h.key] = 100;
                else newWidths[h.key] = 90;
            }
        });
        return newWidths;
    });
  }, [visibleOriginalHeaders, visibleAddedHeaders]);

  const handleMouseDown = useCallback((e: React.MouseEvent<HTMLDivElement>, headerKey: string) => {
    isResizing.current = headerKey;
    const startX = e.clientX;
    const startWidth = columnWidths[headerKey] || 0;

    const handleMouseMove = (moveEvent: MouseEvent) => {
      if (isResizing.current !== headerKey) return;
      const width = startWidth + (moveEvent.clientX - startX);
      if (width > 50) { // Min width
        setColumnWidths(prev => ({ ...prev, [headerKey]: width }));
      }
    };

    const handleMouseUp = () => {
      isResizing.current = null;
      window.removeEventListener('mousemove', handleMouseMove);
      window.removeEventListener('mouseup', handleMouseUp);
      document.body.style.cursor = 'default';
      document.body.style.userSelect = 'auto';
    };

    window.addEventListener('mousemove', handleMouseMove);
    window.addEventListener('mouseup', handleMouseUp);
    e.preventDefault();
    document.body.style.cursor = 'col-resize';
    document.body.style.userSelect = 'none';
  }, [columnWidths]);

  const renderUniqueId = (item: any, originalIndex: number) => {
    if (item.isUpdating) {
        return (
           <div className="flex items-center space-x-2">
               <div className="w-3 h-3 border-2 border-blue-600 border-dashed rounded-full animate-spin"></div>
               <span className="text-xs text-gray-500">Updating...</span>
           </div>
        );
    }

    const isExpanded = expandedRowIndex === originalIndex;

    return (
      <button 
          onClick={(e) => toggleRow(e, originalIndex, item.uniqueId)}
          className={`flex items-center space-x-2 px-2 py-1 rounded transition-colors w-full text-left font-mono text-xs border ${isExpanded ? 'bg-blue-600 text-white border-blue-600' : 'text-blue-700 hover:bg-blue-50 border-transparent hover:border-blue-200'}`}
          title="Click to view details & edit"
          aria-expanded={isExpanded}
      >
          <span>{item.uniqueId}</span>
          <svg 
            xmlns="http://www.w3.org/2000/svg" 
            className={`h-3 w-3 transition-transform duration-200 ${isExpanded ? 'rotate-180' : ''}`} 
            fill="none" 
            viewBox="0 0 24 24" 
            stroke="currentColor"
          >
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 9l-7 7-7-7" />
          </svg>
      </button>
    );
  };

  const addedColumnRenderers: Record<string, (item: any, originalIndex: number) => React.ReactNode> = {
    uniqueId: (item, originalIndex) => renderUniqueId(item, originalIndex),
    rating: (item) => <RatingBadge rating={item.rating} />,
    reliabilityScore: (item) => (
        <div className="flex items-center" aria-label={`Reliability: ${item.reliabilityScore}%`}>
            <div role="progressbar" aria-valuenow={item.reliabilityScore} aria-valuemin={0} aria-valuemax={100} className="w-16 bg-gray-200 rounded-full h-2.5">
                <div className="bg-blue-600 h-2.5 rounded-full" style={{ width: `${item.reliabilityScore}%` }}></div>
            </div>
            <span className="ml-2 font-medium text-xs">{item.reliabilityScore}%</span>
        </div>
    ),
    notes: (item) => <span className="block leading-tight">{item.notes}</span>,
  };

  // Helper to extract input details for comparison
  const getInputDetail = (item: any, fieldKey: string) => {
      const header = columnMapping[fieldKey];
      if (!header || header === 'N/A') return <span className="text-gray-400 italic">Not mapped</span>;
      const val = item[header];
      return val ? <span className="font-medium text-gray-900">{String(val)}</span> : <span className="text-gray-400 italic">Empty</span>;
  };


  return (
    <div className="w-full bg-white p-6 md:p-8 rounded-lg shadow-lg border border-gray-200 relative">
      <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center mb-6 gap-4">
        <div className="flex-grow">
          <h2 id="results-heading" className="text-2xl font-bold text-gray-800">Analysis Results</h2>
          <p className="text-sm text-gray-500 mt-1">Tip: Click a Unique ID to expand the row and compare details.</p>
          {filterTitle && (
            <div className="flex items-center gap-3 mt-2">
                <p className="text-sm text-gray-600">
                    Showing data for: <span className="font-semibold bg-blue-100 text-blue-800 px-2 py-1 rounded-md">{filterTitle}</span>
                </p>
                <button 
                    onClick={onClearFilter}
                    className="text-sm text-blue-600 hover:underline"
                >
                    Clear Filter
                </button>
            </div>
          )}
          <div className="mt-4 flex items-center gap-4">
            <div className="relative flex-grow max-w-sm">
                <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
                    <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5 text-gray-400" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" />
                    </svg>
                </div>
                <input
                    type="search"
                    id="table-search"
                    aria-label="Search results"
                    placeholder={`Search in ${results.length} results...`}
                    value={searchTerm}
                    onChange={(e) => setSearchTerm(e.target.value)}
                    className="block w-full pl-10 pr-3 py-2 border border-gray-300 rounded-md leading-5 bg-white placeholder-gray-500 focus:outline-none focus:placeholder-gray-400 focus:ring-1 focus:ring-blue-500 focus:border-blue-500 sm:text-sm"
                />
            </div>
            {searchTerm && (
                <button
                    onClick={() => setSearchTerm('')}
                    className="text-sm text-blue-600 hover:underline"
                >
                    Clear Search
                </button>
            )}
          </div>
        </div>
        <div className="flex items-center gap-4 flex-shrink-0">
          <ColumnToggler 
            allColumns={allColumns}
            visibleColumns={visibleColumns}
            onVisibilityChange={onVisibleColumnsChange}
          />
          <button
            onClick={onExport}
            className="flex items-center gap-2 px-4 py-2 text-sm font-semibold text-white bg-green-600 rounded-md hover:bg-green-700 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-green-600 transition-colors duration-200"
          >
            <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth="2">
                <path strokeLinecap="round" strokeLinejoin="round" d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-4l-4 4m0 0l-4-4m4 4V4" />
            </svg>
            Export Full Dataset (CSV)
          </button>
        </div>
      </div>

      {/* Top Scrollbar */}
      <div 
        ref={topScrollRef}
        className="overflow-x-auto w-full mb-1"
        style={{ height: '12px' }}
      >
        <div style={{ width: scrollWidth, height: '1px' }}></div>
      </div>

      <div 
        ref={tableContainerRef}
        className="overflow-x-auto max-h-[70vh]" // Constrain height for sticky header
      >
        {filteredAndSortedResults.length > 0 ? (
            <table className="min-w-full divide-y divide-gray-200 table-fixed" aria-labelledby="results-heading">
            {/* Sticky Header */}
            <thead className="bg-gray-100 sticky top-0 z-10 shadow-sm">
                <tr>
                {visibleOriginalHeaders.map((header) => (
                    <th 
                        key={header} 
                        scope="col" 
                        className="px-2 py-2 text-left text-xs font-bold text-gray-600 uppercase tracking-wider relative group bg-gray-100 align-bottom border-b border-gray-200"
                        style={{ width: columnWidths[header] ? `${columnWidths[header]}px` : undefined }}
                        aria-sort={sortConfig?.key === header ? sortConfig.direction : 'none'}
                    >
                    <button onClick={() => requestSort(header)} className="flex items-end w-full h-full">
                        <span className="whitespace-normal break-words leading-tight">{header}</span>
                        <SortIcon direction={sortConfig?.key === header ? sortConfig.direction : null} />
                    </button>
                    <div
                        onMouseDown={(e) => handleMouseDown(e, header)}
                        aria-hidden="true"
                        className="absolute top-0 right-0 h-full w-2 cursor-col-resize hover:bg-blue-200"
                    />
                    </th>
                ))}
                {visibleAddedHeaders.map((header) => (
                    <th 
                        key={header.key} 
                        scope="col" 
                        className="px-2 py-2 text-left text-xs font-bold text-blue-800 bg-blue-100 uppercase tracking-wider relative group align-bottom border-b border-blue-200"
                        style={{ width: columnWidths[header.key] ? `${columnWidths[header.key]}px` : undefined }}
                        aria-sort={sortConfig?.key === header.key ? sortConfig.direction : 'none'}
                    >
                    <button onClick={() => requestSort(header.key)} className="flex items-end w-full h-full">
                        <span className="whitespace-normal break-words leading-tight">{header.title}</span>
                        <SortIcon direction={sortConfig?.key === header.key ? sortConfig.direction : null} />
                    </button>
                    <div
                        onMouseDown={(e) => handleMouseDown(e, header.key)}
                        aria-hidden="true"
                        className="absolute top-0 right-0 h-full w-2 cursor-col-resize hover:bg-blue-300"
                    />
                    </th>
                ))}
                </tr>
            </thead>
            <tbody className="bg-white divide-y divide-gray-200">
                {filteredAndSortedResults.map((item, index) => {
                    const isExpanded = expandedRowIndex === item._originalIndex;
                    return (
                        <React.Fragment key={index}>
                            <tr className={`${isExpanded ? 'bg-blue-50' : 'hover:bg-gray-50'}`}>
                                {visibleOriginalHeaders.map((header) => (
                                <td key={`${header}-${index}`} className="px-2 py-2 text-xs text-gray-700 break-words align-top leading-tight">
                                    {item[header]}
                                </td>
                                ))}
                                {visibleAddedHeaders.map((header) => (
                                    <td key={`${header.key}-${index}`} className="px-2 py-2 text-xs text-gray-700 bg-blue-50/50 align-top leading-tight">
                                        {addedColumnRenderers[header.key](item, item._originalIndex)}
                                    </td>
                                ))}
                            </tr>
                            {isExpanded && (
                                <tr className="bg-gray-50 shadow-inner">
                                    <td colSpan={totalColSpan} className="px-4 py-4 sm:px-8 border-b border-gray-200">
                                        <div className="grid grid-cols-1 md:grid-cols-2 gap-8 text-sm">
                                            {/* Left: Input Details */}
                                            <div className="space-y-3">
                                                <h4 className="font-bold text-gray-700 uppercase tracking-wide border-b pb-1 text-xs">Your Input (Product Details)</h4>
                                                <div className="grid grid-cols-[120px_1fr] gap-2">
                                                    <span className="text-gray-500">Common Name:</span>
                                                    {getInputDetail(item, 'Common name')}

                                                    <span className="text-gray-500">Scientific Name:</span>
                                                    {getInputDetail(item, 'Scientific name')}

                                                    <span className="text-gray-500">Country:</span>
                                                    {getInputDetail(item, 'Source country')}

                                                    <span className="text-gray-500">Method:</span>
                                                    {getInputDetail(item, 'Production Method')}

                                                    <span className="text-gray-500">Wild/Farmed:</span>
                                                    {getInputDetail(item, 'Wild or Farmed')}
                                                </div>
                                            </div>

                                            {/* Right: Match Details */}
                                            <div className="space-y-3 border-t md:border-t-0 md:border-l md:pl-8 pt-4 md:pt-0 border-gray-200">
                                                <h4 className="font-bold text-blue-700 uppercase tracking-wide border-b border-blue-100 pb-1 text-xs">Seafood Watch Database Match</h4>
                                                <div className="space-y-3">
                                                    <div>
                                                        <span className="block text-gray-500 text-xs mb-1">Official Description (KDEs):</span>
                                                        <div className="bg-white border border-gray-200 p-2 rounded text-gray-800 leading-snug">
                                                            {item.matchedKDEs || 'N/A'}
                                                        </div>
                                                    </div>
                                                    <div className="flex items-center justify-between">
                                                        <div className="flex items-center gap-2">
                                                            <span className="text-gray-500">Rating:</span>
                                                            <RatingBadge rating={item.rating} />
                                                        </div>
                                                        <div className="flex items-center gap-2">
                                                            <span className="text-gray-500">Reliability:</span>
                                                            <span className={`font-bold ${item.reliabilityScore > 80 ? 'text-green-600' : 'text-yellow-600'}`}>{item.reliabilityScore}%</span>
                                                        </div>
                                                    </div>

                                                    <div className="bg-blue-50 p-3 rounded border border-blue-100 mt-2">
                                                        <label htmlFor={`edit-id-${index}`} className="block text-xs font-bold text-blue-800 mb-1">
                                                            Correct Unique ID
                                                        </label>
                                                        <div className="flex gap-2">
                                                            <input 
                                                                id={`edit-id-${index}`}
                                                                type="text" 
                                                                value={editValue} 
                                                                onChange={(e) => setEditValue(e.target.value)}
                                                                className="flex-grow text-sm border border-gray-300 rounded px-2 py-1 focus:outline-none focus:ring-1 focus:ring-blue-500"
                                                                placeholder="Enter correct ID..."
                                                            />
                                                            <button 
                                                                onClick={() => handleSubmitEdit(item._originalIndex)}
                                                                className="bg-blue-600 text-white text-xs px-3 py-1 rounded hover:bg-blue-700 focus:outline-none focus:ring-2 focus:ring-offset-1 focus:ring-blue-600 disabled:opacity-50 disabled:cursor-not-allowed"
                                                                disabled={!editValue || editValue === item.uniqueId}
                                                            >
                                                                Update
                                                            </button>
                                                        </div>
                                                        <p className="text-[10px] text-blue-600 mt-1">
                                                            Enter a valid ID from the Seafood Watch database to force a match.
                                                        </p>
                                                    </div>
                                                </div>
                                            </div>
                                        </div>
                                    </td>
                                </tr>
                            )}
                        </React.Fragment>
                    );
                })}
            </tbody>
            </table>
        ) : (
            <p className="text-center text-gray-500 my-8 py-4">
                No results found for your search: "{searchTerm}".
            </p>
        )}
      </div>
    </div>
  );
};

export default ResultsTable;

import React, { useState, useCallback, useRef, useEffect, useMemo } from 'react';
import { SeafoodResultItem } from '../types';
import RatingBadge from './RatingBadge';
import ColumnToggler from './ColumnToggler';

interface ResultsTableProps {
  results: any[];
  originalHeaders: string[];
  columnMapping?: Record<string, string>;
  onExport: () => void;
  filterTitle?: string;
  onClearFilter?: () => void;
  visibleColumns: Set<string>;
  onVisibleColumnsChange: (newVisible: Set<string>) => void;
  onUpdateResult?: (index: number, newUniqueId: string) => Promise<void>;
}

type SortDirection = 'ascending' | 'descending';

const SortIcon: React.FC<{ direction: SortDirection | null }> = ({ direction }) => {
    if (!direction) return null;
    return (
      <svg
        className="w-4 h-4 ml-1 inline-block text-gray-500 flex-shrink-0"
        aria-hidden="true"
        fill="currentColor"
        viewBox="0 0 20 20"
        xmlns="http://www.w3.org/2000/svg"
      >
        {direction === 'descending' ? (
          <path
            fillRule="evenodd"
            d="M5.293 7.293a1 1 0 011.414 0L10 10.586l3.293-3.293a1 1 0 111.414 1.414l-4 4a1 1 0 01-1.414 0l-4-4a1 1 0 010-1.414z"
            clipRule="evenodd"
          />
        ) : (
          <path
            fillRule="evenodd"
            d="M14.707 12.707a1 1 0 01-1.414 0L10 9.414l-3.293 3.293a1 1 0 01-1.414-1.414l4-4a1 1 0 011.414 0l4 4a1 1 0 010 1.414z"
            clipRule="evenodd"
          />
        )}
      </svg>
    );
};


const ResultsTable: React.FC<ResultsTableProps> = ({ 
  results, 
  originalHeaders,
  columnMapping = {},
  onExport, 
  filterTitle, 
  onClearFilter,
  visibleColumns, 
  onVisibleColumnsChange,
  onUpdateResult
}) => {
  const [columnWidths, setColumnWidths] = useState<Record<string, number>>({});
  const isResizing = useRef<string | null>(null);
  const [sortConfig, setSortConfig] = useState<{ key: string; direction: SortDirection } | null>(null);
  const [searchTerm, setSearchTerm] = useState('');

  // Expanded Row State (Accordion)
  const [expandedRowIndex, setExpandedRowIndex] = useState<number | null>(null);
  // Temporary state for the input field inside the expanded view
  const [editValue, setEditValue] = useState<string>('');


  // Refs for synced scrolling
  const tableContainerRef = useRef<HTMLDivElement>(null);
  const topScrollRef = useRef<HTMLDivElement>(null);
  const [scrollWidth, setScrollWidth] = useState(0);

  const sortedResults = useMemo(() => {
    // Add original index to items to track them after sorting
    const itemsWithIndex = results.map((item, index) => ({ ...item, _originalIndex: index }));

    if (!sortConfig) {
      return itemsWithIndex;
    }
    const sortableItems = [...itemsWithIndex];
    sortableItems.sort((a, b) => {
        const aVal = a[sortConfig.key];
        const bVal = b[sortConfig.key];

        if (aVal == null) return 1;
        if (bVal == null) return -1;

        if (typeof aVal === 'number' && typeof bVal === 'number') {
            return sortConfig.direction === 'ascending' ? aVal - bVal : bVal - aVal;
        }

        const aStr = String(aVal);
        const bStr = String(bVal);
        const comparison = aStr.localeCompare(bStr, undefined, { numeric: true, sensitivity: 'base' });

        return sortConfig.direction === 'ascending' ? comparison : -comparison;
      });

    return sortableItems;
  }, [results, sortConfig]);

  const filteredAndSortedResults = useMemo(() => {
    if (!searchTerm) {
      return sortedResults;
    }
    const lowercasedFilter = searchTerm.toLowerCase();
    return sortedResults.filter(item => {
       const { _originalIndex, isUpdating, ...searchableItem } = item;
      return Object.values(searchableItem).some(value =>
        String(value).toLowerCase().includes(lowercasedFilter)
      );
    });
  }, [sortedResults, searchTerm]);

  // Sync scrollbars
  useEffect(() => {
    const syncScroll = (source: 'top' | 'bottom') => {
      const top = topScrollRef.current;
      const bottom = tableContainerRef.current;
      if (!top || !bottom) return;

      if (source === 'top') {
        bottom.scrollLeft = top.scrollLeft;
      } else {
        top.scrollLeft = bottom.scrollLeft;
      }
    };

    const top = topScrollRef.current;
    const bottom = tableContainerRef.current;

    if (top && bottom) {
      const handleTopScroll = () => syncScroll('top');
      const handleBottomScroll = () => syncScroll('bottom');

      top.addEventListener('scroll', handleTopScroll);
      bottom.addEventListener('scroll', handleBottomScroll);

      return () => {
        top.removeEventListener('scroll', handleTopScroll);
        bottom.removeEventListener('scroll', handleBottomScroll);
      };
    }
  }, []);

  // Update scroll width when data or columns change
  useEffect(() => {
    if (tableContainerRef.current) {
      setScrollWidth(tableContainerRef.current.scrollWidth);
    }
  }, [visibleColumns, filteredAndSortedResults, columnWidths]);


  const requestSort = (key: string) => {
    let direction: SortDirection = 'ascending';
    if (sortConfig && sortConfig.key === key && sortConfig.direction === 'ascending') {
      direction = 'descending';
    }
    setSortConfig({ key, direction });
  };

  const toggleRow = (e: React.MouseEvent, rowIndex: number, currentId: string) => {
      e.stopPropagation();
      if (expandedRowIndex === rowIndex) {
          setExpandedRowIndex(null);
          setEditValue('');
      } else {
          setExpandedRowIndex(rowIndex);
          setEditValue(currentId);
      }
  };

  const handleSubmitEdit = async (index: number) => {
      if (onUpdateResult && editValue) {
          await onUpdateResult(index, editValue);
          // Don't close row automatically, user might want to see update.
      }
  };


  if (!results.length) {
    return <p className="text-center text-gray-500 my-8">
        {filterTitle ? `No data matches the filter "${filterTitle}".` : 'No data to display.'}
    </p>;
  }

  const addedHeaders = [
    { key: 'uniqueId', title: 'Unique ID' },
    { key: 'rating', title: 'Rating' },
    { key: 'reliabilityScore', title: 'Reliability' },
    { key: 'notes', title: 'Notes' },
  ];

  const allColumns = [
    ...originalHeaders.map(h => ({ key: h, title: h })),
    ...addedHeaders.map(h => ({ key: h.key, title: h.title }))
  ];

  const visibleOriginalHeaders = originalHeaders.filter(h => visibleColumns.has(h));
  const visibleAddedHeaders = addedHeaders.filter(h => visibleColumns.has(h.key));
  const totalColSpan = visibleOriginalHeaders.length + visibleAddedHeaders.length;

  useEffect(() => {
    setColumnWidths(prevWidths => {
        const newWidths = { ...prevWidths };
        visibleOriginalHeaders.forEach(h => {
            if (!newWidths[h]) newWidths[h] = 100;
        });
        visibleAddedHeaders.forEach(h => {
            if (!newWidths[h.key]) {
                if (h.key === 'notes') newWidths[h.key] = 400;
                else if (h.key === 'reliabilityScore') newWidths[h.key] = 90;
                else if (h.key === 'uniqueId') newWidths[h.key] = 100;
                else newWidths[h.key] = 90;
            }
        });
        return newWidths;
    });
  }, [visibleOriginalHeaders, visibleAddedHeaders]);

  const handleMouseDown = useCallback((e: React.MouseEvent<HTMLDivElement>, headerKey: string) => {
    isResizing.current = headerKey;
    const startX = e.clientX;
    const startWidth = columnWidths[headerKey] || 0;

    const handleMouseMove = (moveEvent: MouseEvent) => {
      if (isResizing.current !== headerKey) return;
      const width = startWidth + (moveEvent.clientX - startX);
      if (width > 50) { // Min width
        setColumnWidths(prev => ({ ...prev, [headerKey]: width }));
      }
    };

    const handleMouseUp = () => {
      isResizing.current = null;
      window.removeEventListener('mousemove', handleMouseMove);
      window.removeEventListener('mouseup', handleMouseUp);
      document.body.style.cursor = 'default';
      document.body.style.userSelect = 'auto';
    };

    window.addEventListener('mousemove', handleMouseMove);
    window.addEventListener('mouseup', handleMouseUp);
    e.preventDefault();
    document.body.style.cursor = 'col-resize';
    document.body.style.userSelect = 'none';
  }, [columnWidths]);

  const renderUniqueId = (item: any, originalIndex: number) => {
    if (item.isUpdating) {
        return (
           <div className="flex items-center space-x-2">
               <div className="w-3 h-3 border-2 border-blue-600 border-dashed rounded-full animate-spin"></div>
               <span className="text-xs text-gray-500">Updating...</span>
           </div>
        );
    }

    const isExpanded = expandedRowIndex === originalIndex;

    return (
      <button 
          onClick={(e) => toggleRow(e, originalIndex, item.uniqueId)}
          className={`flex items-center space-x-2 px-2 py-1 rounded transition-colors w-full text-left font-mono text-xs border ${isExpanded ? 'bg-blue-600 text-white border-blue-600' : 'text-blue-700 hover:bg-blue-50 border-transparent hover:border-blue-200'}`}
          title="Click to view details & edit"
          aria-expanded={isExpanded}
      >
          <span>{item.uniqueId}</span>
          <svg 
            xmlns="http://www.w3.org/2000/svg" 
            className={`h-3 w-3 transition-transform duration-200 ${isExpanded ? 'rotate-180' : ''}`} 
            fill="none" 
            viewBox="0 0 24 24" 
            stroke="currentColor"
          >
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 9l-7 7-7-7" />
          </svg>
      </button>
    );
  };

  const addedColumnRenderers: Record<string, (item: any, originalIndex: number) => React.ReactNode> = {
    uniqueId: (item, originalIndex) => renderUniqueId(item, originalIndex),
    rating: (item) => <RatingBadge rating={item.rating} />,
    reliabilityScore: (item) => (
        <div className="flex items-center" aria-label={`Reliability: ${item.reliabilityScore}%`}>
            <div role="progressbar" aria-valuenow={item.reliabilityScore} aria-valuemin={0} aria-valuemax={100} className="w-16 bg-gray-200 rounded-full h-2.5">
                <div className="bg-blue-600 h-2.5 rounded-full" style={{ width: `${item.reliabilityScore}%` }}></div>
            </div>
            <span className="ml-2 font-medium text-xs">{item.reliabilityScore}%</span>
        </div>
    ),
    notes: (item) => <span className="block leading-tight">{item.notes}</span>,
  };

  // Helper to extract input details for comparison
  const getInputDetail = (item: any, fieldKey: string) => {
      const header = columnMapping[fieldKey];
      if (!header || header === 'N/A') return <span className="text-gray-400 italic">Not mapped</span>;
      const val = item[header];
      return val ? <span className="font-medium text-gray-900">{String(val)}</span> : <span className="text-gray-400 italic">Empty</span>;
  };

  // Parse KDE string for display in comparison grid
  const parseMatchedKDE = (kdeString: string) => {
      if (!kdeString || kdeString === 'N/A') return { species: 'N/A', location: 'N/A', method: 'N/A' };
      const parts = kdeString.split(' | ');
      if (parts.length >= 3) {
          return {
              species: parts[0],
              location: parts[1],
              method: parts.slice(2).join(' | ')
          };
      }
      return { species: kdeString, location: '-', method: '-' };
  };


  return (
    <div className="w-full bg-white p-6 md:p-8 rounded-lg shadow-lg border border-gray-200 relative">
      <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center mb-6 gap-4">
        <div className="flex-grow">
          <h2 id="results-heading" className="text-2xl font-bold text-gray-800">Analysis Results</h2>
          <p className="text-sm text-gray-500 mt-1">Tip: Click a Unique ID to expand the row and compare details.</p>
          {filterTitle && (
            <div className="flex items-center gap-3 mt-2">
                <p className="text-sm text-gray-600">
                    Showing data for: <span className="font-semibold bg-blue-100 text-blue-800 px-2 py-1 rounded-md">{filterTitle}</span>
                </p>
                <button 
                    onClick={onClearFilter}
                    className="text-sm text-blue-600 hover:underline"
                >
                    Clear Filter
                </button>
            </div>
          )}
          <div className="mt-4 flex items-center gap-4">
            <div className="relative flex-grow max-w-sm">
                <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
                    <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5 text-gray-400" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" />
                    </svg>
                </div>
                <input
                    type="search"
                    id="table-search"
                    aria-label="Search results"
                    placeholder={`Search in ${results.length} results...`}
                    value={searchTerm}
                    onChange={(e) => setSearchTerm(e.target.value)}
                    className="block w-full pl-10 pr-3 py-2 border border-gray-300 rounded-md leading-5 bg-white placeholder-gray-500 focus:outline-none focus:placeholder-gray-400 focus:ring-1 focus:ring-blue-500 focus:border-blue-500 sm:text-sm"
                />
            </div>
            {searchTerm && (
                <button
                    onClick={() => setSearchTerm('')}
                    className="text-sm text-blue-600 hover:underline"
                >
                    Clear Search
                </button>
            )}
          </div>
        </div>
        <div className="flex items-center gap-4 flex-shrink-0">
          <ColumnToggler 
            allColumns={allColumns}
            visibleColumns={visibleColumns}
            onVisibilityChange={onVisibleColumnsChange}
          />
          <button
            onClick={onExport}
            className="flex items-center gap-2 px-4 py-2 text-sm font-semibold text-white bg-green-600 rounded-md hover:bg-green-700 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-green-600 transition-colors duration-200"
          >
            <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth="2">
                <path strokeLinecap="round" strokeLinejoin="round" d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-4l-4 4m0 0l-4-4m4 4V4" />
            </svg>
            Export Full Dataset (CSV)
          </button>
        </div>
      </div>

      {/* Top Scrollbar */}
      <div 
        ref={topScrollRef}
        className="overflow-x-auto w-full mb-1"
        style={{ height: '12px' }}
      >
        <div style={{ width: scrollWidth, height: '1px' }}></div>
      </div>

      <div 
        ref={tableContainerRef}
        className="overflow-x-auto max-h-[70vh]" // Constrain height for sticky header
      >
        {filteredAndSortedResults.length > 0 ? (
            <table className="min-w-full divide-y divide-gray-200 table-fixed" aria-labelledby="results-heading">
            {/* Sticky Header */}
            <thead className="bg-gray-100 sticky top-0 z-10 shadow-sm">
                <tr>
                {visibleOriginalHeaders.map((header) => (
                    <th 
                        key={header} 
                        scope="col" 
                        className="px-2 py-2 text-left text-xs font-bold text-gray-600 uppercase tracking-wider relative group bg-gray-100 align-bottom border-b border-gray-200"
                        style={{ width: columnWidths[header] ? `${columnWidths[header]}px` : undefined }}
                        aria-sort={sortConfig?.key === header ? sortConfig.direction : 'none'}
                    >
                    <button onClick={() => requestSort(header)} className="flex items-end w-full h-full">
                        <span className="whitespace-normal break-words leading-tight">{header}</span>
                        <SortIcon direction={sortConfig?.key === header ? sortConfig.direction : null} />
                    </button>
                    <div
                        onMouseDown={(e) => handleMouseDown(e, header)}
                        aria-hidden="true"
                        className="absolute top-0 right-0 h-full w-2 cursor-col-resize hover:bg-blue-200"
                    />
                    </th>
                ))}
                {visibleAddedHeaders.map((header) => (
                    <th 
                        key={header.key} 
                        scope="col" 
                        className="px-2 py-2 text-left text-xs font-bold text-blue-800 bg-blue-100 uppercase tracking-wider relative group align-bottom border-b border-blue-200"
                        style={{ width: columnWidths[header.key] ? `${columnWidths[header.key]}px` : undefined }}
                        aria-sort={sortConfig?.key === header.key ? sortConfig.direction : 'none'}
                    >
                    <button onClick={() => requestSort(header.key)} className="flex items-end w-full h-full">
                        <span className="whitespace-normal break-words leading-tight">{header.title}</span>
                        <SortIcon direction={sortConfig?.key === header.key ? sortConfig.direction : null} />
                    </button>
                    <div
                        onMouseDown={(e) => handleMouseDown(e, header.key)}
                        aria-hidden="true"
                        className="absolute top-0 right-0 h-full w-2 cursor-col-resize hover:bg-blue-300"
                    />
                    </th>
                ))}
                </tr>
            </thead>
            <tbody className="bg-white divide-y divide-gray-200">
                {filteredAndSortedResults.map((item, index) => {
                    const isExpanded = expandedRowIndex === item._originalIndex;
                    const matchDetails = parseMatchedKDE(item.matchedKDEs);

                    return (
                        <React.Fragment key={index}>
                            <tr className={`${isExpanded ? 'bg-blue-50' : 'hover:bg-gray-50'}`}>
                                {visibleOriginalHeaders.map((header) => (
                                <td key={`${header}-${index}`} className="px-2 py-2 text-xs text-gray-700 break-words align-top leading-tight">
                                    {item[header]}
                                </td>
                                ))}
                                {visibleAddedHeaders.map((header) => (
                                    <td key={`${header.key}-${index}`} className="px-2 py-2 text-xs text-gray-700 bg-blue-50/50 align-top leading-tight">
                                        {addedColumnRenderers[header.key](item, item._originalIndex)}
                                    </td>
                                ))}
                            </tr>
                            {isExpanded && (
                                <tr className="bg-slate-100 shadow-inner">
                                    <td colSpan={totalColSpan} className="px-4 py-6">
                                        <div className="bg-white rounded-lg shadow-sm border border-gray-200 overflow-hidden max-w-5xl mx-auto">
                                            {/* Header */}
                                            <div className="bg-gray-50 px-6 py-3 border-b border-gray-200 flex justify-between items-center">
                                                <h4 className="font-bold text-gray-700 text-sm uppercase tracking-wide">Match Analysis & Comparison</h4>
                                                <div className="text-xs text-gray-500">
                                                    Comparing row {index + 1}
                                                </div>
                                            </div>

                                            {/* Comparison Grid */}
                                            <div className="grid grid-cols-1 md:grid-cols-12 text-sm">
                                                {/* Column Headers (Visible on MD+) */}
                                                <div className="hidden md:contents">
                                                    <div className="col-span-12 grid grid-cols-12 border-b border-gray-100 bg-gray-50/50 py-2 px-6 font-semibold text-gray-500 text-xs uppercase">
                                                        <div className="col-span-2">Attribute</div>
                                                        <div className="col-span-5 border-l border-gray-200 pl-4">Your Input (Product Details)</div>
                                                        <div className="col-span-5 border-l border-gray-200 pl-4 text-blue-700">Seafood Watch Match</div>
                                                    </div>
                                                </div>

                                                {/* Row: Common Name */}
                                                <div className="col-span-12 grid grid-cols-1 md:grid-cols-12 border-b border-gray-100 py-3 px-6 hover:bg-gray-50 items-center">
                                                    <div className="md:col-span-2 font-medium text-gray-600 text-xs uppercase md:text-sm md:normal-case md:text-gray-600 mb-1 md:mb-0">Species / Common Name</div>
                                                    <div className="md:col-span-5 md:border-l border-gray-200 md:pl-4 mb-2 md:mb-0">{getInputDetail(item, 'Common name')}</div>
                                                    <div className="md:col-span-5 md:border-l border-gray-200 md:pl-4 font-medium text-gray-800">{matchDetails.species}</div>
                                                </div>

                                                {/* Row: Location */}
                                                <div className="col-span-12 grid grid-cols-1 md:grid-cols-12 border-b border-gray-100 py-3 px-6 hover:bg-gray-50 items-center">
                                                    <div className="md:col-span-2 font-medium text-gray-600 text-xs uppercase md:text-sm md:normal-case md:text-gray-600 mb-1 md:mb-0">Location / Country</div>
                                                    <div className="md:col-span-5 md:border-l border-gray-200 md:pl-4 mb-2 md:mb-0">{getInputDetail(item, 'Source country')}</div>
                                                    <div className="md:col-span-5 md:border-l border-gray-200 md:pl-4 text-gray-800">{matchDetails.location}</div>
                                                </div>

                                                {/* Row: Method */}
                                                <div className="col-span-12 grid grid-cols-1 md:grid-cols-12 border-b border-gray-100 py-3 px-6 hover:bg-gray-50 items-center">
                                                    <div className="md:col-span-2 font-medium text-gray-600 text-xs uppercase md:text-sm md:normal-case md:text-gray-600 mb-1 md:mb-0">Method</div>
                                                    <div className="md:col-span-5 md:border-l border-gray-200 md:pl-4 mb-2 md:mb-0">{getInputDetail(item, 'Production Method')}</div>
                                                    <div className="md:col-span-5 md:border-l border-gray-200 md:pl-4 text-gray-800">{matchDetails.method}</div>
                                                </div>

                                                {/* Row: Rating & Confidence */}
                                                <div className="col-span-12 grid grid-cols-1 md:grid-cols-12 py-4 px-6 bg-blue-50/30 items-center">
                                                    <div className="md:col-span-2 font-medium text-gray-600 text-xs uppercase md:text-sm md:normal-case md:text-gray-600 mb-1 md:mb-0">Result</div>
                                                    <div className="md:col-span-5 md:border-l border-gray-200 md:pl-4 flex items-center gap-2 mb-2 md:mb-0">
                                                        <span className="text-gray-400 text-xs italic">Wild/Farmed Input: </span>
                                                        {getInputDetail(item, 'Wild or Farmed')}
                                                    </div>
                                                    <div className="md:col-span-5 md:border-l border-gray-200 md:pl-4">
                                                        <div className="flex flex-wrap items-center gap-4">
                                                            <div className="flex items-center gap-2 bg-white px-2 py-1 rounded border border-gray-200">
                                                                    <span className="text-gray-500 text-xs uppercase font-bold">Rating:</span>
                                                                    <RatingBadge rating={item.rating} />
                                                            </div>
                                                            <div className="flex items-center gap-2 bg-white px-2 py-1 rounded border border-gray-200">
                                                                    <span className="text-gray-500 text-xs uppercase font-bold">Reliability:</span>
                                                                    <span className={`font-bold ${item.reliabilityScore > 80 ? 'text-green-600' : 'text-yellow-600'}`}>{item.reliabilityScore}%</span>
                                                            </div>
                                                        </div>
                                                    </div>
                                                </div>
                                            </div>

                                            {/* Footer: Edit ID */}
                                            <div className="bg-gray-50 px-6 py-4 border-t border-gray-200 flex flex-col md:flex-row items-start md:items-center gap-4">
                                                <div className="flex-grow">
                                                    <label htmlFor={`edit-id-${index}`} className="block text-xs font-bold text-gray-700 mb-1">
                                                        Is this match incorrect? Manually update the Unique ID:
                                                    </label>
                                                    <div className="flex gap-2 max-w-md">
                                                        <input 
                                                            id={`edit-id-${index}`}
                                                            type="text" 
                                                            value={editValue} 
                                                            onChange={(e) => setEditValue(e.target.value)}
                                                            className="flex-grow text-sm border border-gray-300 rounded px-3 py-1.5 focus:outline-none focus:ring-1 focus:ring-blue-500 shadow-sm"
                                                            placeholder="Enter official Seafood Watch ID..."
                                                        />
                                                        <button 
                                                            onClick={() => handleSubmitEdit(item._originalIndex)}
                                                            className="bg-blue-600 text-white text-xs px-4 py-1.5 rounded font-semibold hover:bg-blue-700 focus:outline-none focus:ring-2 focus:ring-offset-1 focus:ring-blue-600 disabled:opacity-50 disabled:cursor-not-allowed shadow-sm"
                                                            disabled={!editValue || editValue === item.uniqueId}
                                                        >
                                                            Update ID
                                                        </button>
                                                    </div>
                                                </div>
                                                <div className="text-xs text-gray-500 italic max-w-xs">
                                                    Tip: Updating the ID will force the system to use the official details associated with that ID.
                                                </div>
                                            </div>
                                        </div>
                                    </td>
                                </tr>
                            )}
                        </React.Fragment>
                    );
                })}
            </tbody>
            </table>
        ) : (
            <p className="text-center text-gray-500 my-8 py-4">
                No results found for your search: "{searchTerm}".
            </p>
        )}
      </div>
    </div>
  );
};

export default ResultsTable;

import React, { useState, useCallback, useRef, useEffect, useMemo } from 'react';
import { SeafoodResultItem } from '../types';
import RatingBadge from './RatingBadge';
import ColumnToggler from './ColumnToggler';

interface ResultsTableProps {
  results: any[];
  originalHeaders: string[];
  columnMapping?: Record<string, string>;
  onExport: () => void;
  filterTitle?: string;
  onClearFilter?: () => void;
  visibleColumns: Set<string>;
  onVisibleColumnsChange: (newVisible: Set<string>) => void;
  onUpdateResult?: (index: number, newUniqueId: string) => Promise<void>;
}

type SortDirection = 'ascending' | 'descending';

const SortIcon: React.FC<{ direction: SortDirection | null }> = ({ direction }) => {
    if (!direction) return null;
    return (
      <svg
        className="w-4 h-4 ml-1 inline-block text-gray-500 flex-shrink-0"
        aria-hidden="true"
        fill="currentColor"
        viewBox="0 0 20 20"
        xmlns="http://www.w3.org/2000/svg"
      >
        {direction === 'descending' ? (
          <path
            fillRule="evenodd"
            d="M5.293 7.293a1 1 0 011.414 0L10 10.586l3.293-3.293a1 1 0 111.414 1.414l-4 4a1 1 0 01-1.414 0l-4-4a1 1 0 010-1.414z"
            clipRule="evenodd"
          />
        ) : (
          <path
            fillRule="evenodd"
            d="M14.707 12.707a1 1 0 01-1.414 0L10 9.414l-3.293 3.293a1 1 0 01-1.414-1.414l4-4a1 1 0 011.414 0l4 4a1 1 0 010 1.414z"
            clipRule="evenodd"
          />
        )}
      </svg>
    );
};


const ResultsTable: React.FC<ResultsTableProps> = ({ 
  results, 
  originalHeaders,
  columnMapping = {},
  onExport, 
  filterTitle, 
  onClearFilter,
  visibleColumns, 
  onVisibleColumnsChange,
  onUpdateResult
}) => {
  const [columnWidths, setColumnWidths] = useState<Record<string, number>>({});
  const isResizing = useRef<string | null>(null);
  const [sortConfig, setSortConfig] = useState<{ key: string; direction: SortDirection } | null>(null);
  const [searchTerm, setSearchTerm] = useState('');

  // Expanded Row State (Accordion)
  const [expandedRowIndex, setExpandedRowIndex] = useState<number | null>(null);
  // Temporary state for the input field inside the expanded view
  const [editValue, setEditValue] = useState<string>('');


  // Refs for synced scrolling
  const tableContainerRef = useRef<HTMLDivElement>(null);
  const topScrollRef = useRef<HTMLDivElement>(null);
  const [scrollWidth, setScrollWidth] = useState(0);

  const sortedResults = useMemo(() => {
    // Add original index to items to track them after sorting
    const itemsWithIndex = results.map((item, index) => ({ ...item, _originalIndex: index }));

    if (!sortConfig) {
      return itemsWithIndex;
    }
    const sortableItems = [...itemsWithIndex];
    sortableItems.sort((a, b) => {
        const aVal = a[sortConfig.key];
        const bVal = b[sortConfig.key];

        if (aVal == null) return 1;
        if (bVal == null) return -1;

        if (typeof aVal === 'number' && typeof bVal === 'number') {
            return sortConfig.direction === 'ascending' ? aVal - bVal : bVal - aVal;
        }

        const aStr = String(aVal);
        const bStr = String(bVal);
        const comparison = aStr.localeCompare(bStr, undefined, { numeric: true, sensitivity: 'base' });

        return sortConfig.direction === 'ascending' ? comparison : -comparison;
      });

    return sortableItems;
  }, [results, sortConfig]);

  const filteredAndSortedResults = useMemo(() => {
    if (!searchTerm) {
      return sortedResults;
    }
    const lowercasedFilter = searchTerm.toLowerCase();
    return sortedResults.filter(item => {
       const { _originalIndex, isUpdating, ...searchableItem } = item;
      return Object.values(searchableItem).some(value =>
        String(value).toLowerCase().includes(lowercasedFilter)
      );
    });
  }, [sortedResults, searchTerm]);

  // Sync scrollbars
  useEffect(() => {
    const syncScroll = (source: 'top' | 'bottom') => {
      const top = topScrollRef.current;
      const bottom = tableContainerRef.current;
      if (!top || !bottom) return;

      if (source === 'top') {
        bottom.scrollLeft = top.scrollLeft;
      } else {
        top.scrollLeft = bottom.scrollLeft;
      }
    };

    const top = topScrollRef.current;
    const bottom = tableContainerRef.current;

    if (top && bottom) {
      const handleTopScroll = () => syncScroll('top');
      const handleBottomScroll = () => syncScroll('bottom');

      top.addEventListener('scroll', handleTopScroll);
      bottom.addEventListener('scroll', handleBottomScroll);

      return () => {
        top.removeEventListener('scroll', handleTopScroll);
        bottom.removeEventListener('scroll', handleBottomScroll);
      };
    }
  }, []);

  // Update scroll width when data or columns change
  useEffect(() => {
    if (tableContainerRef.current) {
      setScrollWidth(tableContainerRef.current.scrollWidth);
    }
  }, [visibleColumns, filteredAndSortedResults, columnWidths]);


  const requestSort = (key: string) => {
    let direction: SortDirection = 'ascending';
    if (sortConfig && sortConfig.key === key && sortConfig.direction === 'ascending') {
      direction = 'descending';
    }
    setSortConfig({ key, direction });
  };

  const toggleRow = (e: React.MouseEvent, rowIndex: number, currentId: string) => {
      e.stopPropagation();
      if (expandedRowIndex === rowIndex) {
          setExpandedRowIndex(null);
          setEditValue('');
      } else {
          setExpandedRowIndex(rowIndex);
          setEditValue(currentId);
      }
  };

  const handleSubmitEdit = async (index: number) => {
      if (onUpdateResult && editValue) {
          await onUpdateResult(index, editValue);
          // Don't close row automatically, user might want to see update.
      }
  };


  if (!results.length) {
    return <p className="text-center text-gray-500 my-8">
        {filterTitle ? `No data matches the filter "${filterTitle}".` : 'No data to display.'}
    </p>;
  }

  const addedHeaders = [
    { key: 'uniqueId', title: 'Unique ID' },
    { key: 'rating', title: 'Rating' },
    { key: 'reliabilityScore', title: 'Reliability' },
    { key: 'notes', title: 'Notes' },
  ];

  const allColumns = [
    ...originalHeaders.map(h => ({ key: h, title: h })),
    ...addedHeaders.map(h => ({ key: h.key, title: h.title }))
  ];

  const visibleOriginalHeaders = originalHeaders.filter(h => visibleColumns.has(h));
  const visibleAddedHeaders = addedHeaders.filter(h => visibleColumns.has(h.key));
  const totalColSpan = visibleOriginalHeaders.length + visibleAddedHeaders.length;

  useEffect(() => {
    setColumnWidths(prevWidths => {
        const newWidths = { ...prevWidths };
        visibleOriginalHeaders.forEach(h => {
            if (!newWidths[h]) newWidths[h] = 100;
        });
        visibleAddedHeaders.forEach(h => {
            if (!newWidths[h.key]) {
                if (h.key === 'notes') newWidths[h.key] = 400;
                else if (h.key === 'reliabilityScore') newWidths[h.key] = 90;
                else if (h.key === 'uniqueId') newWidths[h.key] = 100;
                else newWidths[h.key] = 90;
            }
        });
        return newWidths;
    });
  }, [visibleOriginalHeaders, visibleAddedHeaders]);

  const handleMouseDown = useCallback((e: React.MouseEvent<HTMLDivElement>, headerKey: string) => {
    isResizing.current = headerKey;
    const startX = e.clientX;
    const startWidth = columnWidths[headerKey] || 0;

    const handleMouseMove = (moveEvent: MouseEvent) => {
      if (isResizing.current !== headerKey) return;
      const width = startWidth + (moveEvent.clientX - startX);
      if (width > 50) { // Min width
        setColumnWidths(prev => ({ ...prev, [headerKey]: width }));
      }
    };

    const handleMouseUp = () => {
      isResizing.current = null;
      window.removeEventListener('mousemove', handleMouseMove);
      window.removeEventListener('mouseup', handleMouseUp);
      document.body.style.cursor = 'default';
      document.body.style.userSelect = 'auto';
    };

    window.addEventListener('mousemove', handleMouseMove);
    window.addEventListener('mouseup', handleMouseUp);
    e.preventDefault();
    document.body.style.cursor = 'col-resize';
    document.body.style.userSelect = 'none';
  }, [columnWidths]);

  const renderUniqueId = (item: any, originalIndex: number) => {
    if (item.isUpdating) {
        return (
           <div className="flex items-center space-x-2">
               <div className="w-3 h-3 border-2 border-blue-600 border-dashed rounded-full animate-spin"></div>
               <span className="text-xs text-gray-500">Updating...</span>
           </div>
        );
    }

    const isExpanded = expandedRowIndex === originalIndex;

    return (
      <button 
          onClick={(e) => toggleRow(e, originalIndex, item.uniqueId)}
          className={`flex items-center space-x-2 px-2 py-1 rounded transition-colors w-full text-left font-mono text-xs border ${isExpanded ? 'bg-blue-600 text-white border-blue-600' : 'text-blue-700 hover:bg-blue-50 border-transparent hover:border-blue-200'}`}
          title="Click to view details & edit"
          aria-expanded={isExpanded}
      >
          <span>{item.uniqueId}</span>
          <svg 
            xmlns="http://www.w3.org/2000/svg" 
            className={`h-3 w-3 transition-transform duration-200 ${isExpanded ? 'rotate-180' : ''}`} 
            fill="none" 
            viewBox="0 0 24 24" 
            stroke="currentColor"
          >
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 9l-7 7-7-7" />
          </svg>
      </button>
    );
  };

  const addedColumnRenderers: Record<string, (item: any, originalIndex: number) => React.ReactNode> = {
    uniqueId: (item, originalIndex) => renderUniqueId(item, originalIndex),
    rating: (item) => <RatingBadge rating={item.rating} />,
    reliabilityScore: (item) => (
        <div className="flex items-center" aria-label={`Reliability: ${item.reliabilityScore}%`}>
            <div role="progressbar" aria-valuenow={item.reliabilityScore} aria-valuemin={0} aria-valuemax={100} className="w-16 bg-gray-200 rounded-full h-2.5">
                <div className="bg-blue-600 h-2.5 rounded-full" style={{ width: `${item.reliabilityScore}%` }}></div>
            </div>
            <span className="ml-2 font-medium text-xs">{item.reliabilityScore}%</span>
        </div>
    ),
    notes: (item) => <span className="block leading-tight">{item.notes}</span>,
  };

  // Helper to extract input details for comparison
  const getInputDetail = (item: any, fieldKey: string) => {
      const header = columnMapping[fieldKey];
      if (!header || header === 'N/A') return <span className="text-gray-400 italic">Not mapped</span>;
      const val = item[header];
      return val ? <span className="font-medium text-gray-900">{String(val)}</span> : <span className="text-gray-400 italic">Empty</span>;
  };

  // Parse KDE string for display in comparison grid
  const parseMatchedKDE = (kdeString: string) => {
      if (!kdeString || kdeString === 'N/A') return { species: 'N/A', location: 'N/A', method: 'N/A' };
      const parts = kdeString.split(' | ');
      if (parts.length >= 3) {
          return {
              species: parts[0],
              location: parts[1],
              method: parts.slice(2).join(' | ')
          };
      }
      return { species: kdeString, location: '-', method: '-' };
  };


  return (
    <div className="w-full bg-white p-6 md:p-8 rounded-lg shadow-lg border border-gray-200 relative">
      <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center mb-6 gap-4">
        <div className="flex-grow">
          <h2 id="results-heading" className="text-2xl font-bold text-gray-800">Analysis Results</h2>
          <p className="text-sm text-gray-500 mt-1">Tip: Click a Unique ID to expand the row and compare details.</p>
          {filterTitle && (
            <div className="flex items-center gap-3 mt-2">
                <p className="text-sm text-gray-600">
                    Showing data for: <span className="font-semibold bg-blue-100 text-blue-800 px-2 py-1 rounded-md">{filterTitle}</span>
                </p>
                <button 
                    onClick={onClearFilter}
                    className="text-sm text-blue-600 hover:underline"
                >
                    Clear Filter
                </button>
            </div>
          )}
          <div className="mt-4 flex items-center gap-4">
            <div className="relative flex-grow max-w-sm">
                <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
                    <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5 text-gray-400" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" />
                    </svg>
                </div>
                <input
                    type="search"
                    id="table-search"
                    aria-label="Search results"
                    placeholder={`Search in ${results.length} results...`}
                    value={searchTerm}
                    onChange={(e) => setSearchTerm(e.target.value)}
                    className="block w-full pl-10 pr-3 py-2 border border-gray-300 rounded-md leading-5 bg-white placeholder-gray-500 focus:outline-none focus:placeholder-gray-400 focus:ring-1 focus:ring-blue-500 focus:border-blue-500 sm:text-sm"
                />
            </div>
            {searchTerm && (
                <button
                    onClick={() => setSearchTerm('')}
                    className="text-sm text-blue-600 hover:underline"
                >
                    Clear Search
                </button>
            )}
          </div>
        </div>
        <div className="flex items-center gap-4 flex-shrink-0">
          <ColumnToggler 
            allColumns={allColumns}
            visibleColumns={visibleColumns}
            onVisibilityChange={onVisibleColumnsChange}
          />
          <button
            onClick={onExport}
            className="flex items-center gap-2 px-4 py-2 text-sm font-semibold text-white bg-green-600 rounded-md hover:bg-green-700 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-green-600 transition-colors duration-200"
          >
            <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth="2">
                <path strokeLinecap="round" strokeLinejoin="round" d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-4l-4 4m0 0l-4-4m4 4V4" />
            </svg>
            Export Full Dataset (CSV)
          </button>
        </div>
      </div>

      {/* Top Scrollbar */}
      <div 
        ref={topScrollRef}
        className="overflow-x-auto w-full mb-1"
        style={{ height: '12px' }}
      >
        <div style={{ width: scrollWidth, height: '1px' }}></div>
      </div>

      <div 
        ref={tableContainerRef}
        className="overflow-x-auto max-h-[70vh]" // Constrain height for sticky header
      >
        {filteredAndSortedResults.length > 0 ? (
            <table className="min-w-full divide-y divide-gray-200 table-fixed" aria-labelledby="results-heading">
            {/* Sticky Header */}
            <thead className="bg-gray-100 sticky top-0 z-10 shadow-sm">
                <tr>
                {visibleOriginalHeaders.map((header) => (
                    <th 
                        key={header} 
                        scope="col" 
                        className="px-2 py-2 text-left text-xs font-bold text-gray-600 uppercase tracking-wider relative group bg-gray-100 align-bottom border-b border-gray-200"
                        style={{ width: columnWidths[header] ? `${columnWidths[header]}px` : undefined }}
                        aria-sort={sortConfig?.key === header ? sortConfig.direction : 'none'}
                    >
                    <button onClick={() => requestSort(header)} className="flex items-end w-full h-full">
                        <span className="whitespace-normal break-words leading-tight">{header}</span>
                        <SortIcon direction={sortConfig?.key === header ? sortConfig.direction : null} />
                    </button>
                    <div
                        onMouseDown={(e) => handleMouseDown(e, header)}
                        aria-hidden="true"
                        className="absolute top-0 right-0 h-full w-2 cursor-col-resize hover:bg-blue-200"
                    />
                    </th>
                ))}
                {visibleAddedHeaders.map((header) => (
                    <th 
                        key={header.key} 
                        scope="col" 
                        className="px-2 py-2 text-left text-xs font-bold text-blue-800 bg-blue-100 uppercase tracking-wider relative group align-bottom border-b border-blue-200"
                        style={{ width: columnWidths[header.key] ? `${columnWidths[header.key]}px` : undefined }}
                        aria-sort={sortConfig?.key === header.key ? sortConfig.direction : 'none'}
                    >
                    <button onClick={() => requestSort(header.key)} className="flex items-end w-full h-full">
                        <span className="whitespace-normal break-words leading-tight">{header.title}</span>
                        <SortIcon direction={sortConfig?.key === header.key ? sortConfig.direction : null} />
                    </button>
                    <div
                        onMouseDown={(e) => handleMouseDown(e, header.key)}
                        aria-hidden="true"
                        className="absolute top-0 right-0 h-full w-2 cursor-col-resize hover:bg-blue-300"
                    />
                    </th>
                ))}
                </tr>
            </thead>
            <tbody className="bg-white divide-y divide-gray-200">
                {filteredAndSortedResults.map((item, index) => {
                    const isExpanded = expandedRowIndex === item._originalIndex;
                    const matchDetails = parseMatchedKDE(item.matchedKDEs);

                    // Logic to determine if Body of Water row should be shown
                    const wildOrFarmedHeader = columnMapping['Wild or Farmed'];
                    const wildOrFarmedVal = wildOrFarmedHeader && item[wildOrFarmedHeader] ? String(item[wildOrFarmedHeader]).toLowerCase() : '';
                    const isWild = wildOrFarmedVal.includes('wild') || (wildOrFarmedVal && !wildOrFarmedVal.includes('farmed')); 

                    const bodyOfWaterHeader = columnMapping['Body of Water'];
                    const bodyOfWaterVal = bodyOfWaterHeader ? item[bodyOfWaterHeader] : '';
                    const showBodyOfWater = !!bodyOfWaterVal || isWild;

                    return (
                        <React.Fragment key={index}>
                            <tr className={`${isExpanded ? 'bg-blue-50' : 'hover:bg-gray-50'}`}>
                                {visibleOriginalHeaders.map((header) => (
                                <td key={`${header}-${index}`} className="px-2 py-2 text-xs text-gray-700 break-words align-top leading-tight">
                                    {item[header]}
                                </td>
                                ))}
                                {visibleAddedHeaders.map((header) => (
                                    <td key={`${header.key}-${index}`} className="px-2 py-2 text-xs text-gray-700 bg-blue-50/50 align-top leading-tight">
                                        {addedColumnRenderers[header.key](item, item._originalIndex)}
                                    </td>
                                ))}
                            </tr>
                            {isExpanded && (
                                <tr className="bg-slate-100 shadow-inner">
                                    <td colSpan={totalColSpan} className="px-4 py-6">
                                        <div className="bg-white rounded-lg shadow-sm border border-gray-200 overflow-hidden max-w-5xl mx-auto">
                                            {/* Header */}
                                            <div className="bg-gray-50 px-6 py-3 border-b border-gray-200 flex justify-between items-center">
                                                <h4 className="font-bold text-gray-700 text-sm uppercase tracking-wide">Match Analysis & Comparison</h4>
                                                <div className="text-xs text-gray-500">
                                                    Comparing row {index + 1}
                                                </div>
                                            </div>

                                            {/* Comparison Grid */}
                                            <div className="grid grid-cols-1 md:grid-cols-12 text-sm">
                                                {/* Column Headers (Visible on MD+) */}
                                                <div className="hidden md:contents">
                                                    <div className="col-span-12 grid grid-cols-12 border-b border-gray-100 bg-gray-50/50 py-2 px-6 font-semibold text-gray-500 text-xs uppercase">
                                                        <div className="col-span-2">Attribute</div>
                                                        <div className="col-span-5 border-l border-gray-200 pl-4">Your Input (Product Details)</div>
                                                        <div className="col-span-5 border-l border-gray-200 pl-4 text-blue-700">Seafood Watch Match</div>
                                                    </div>
                                                </div>

                                                 {/* Row: Wild or Farmed (Moved to top) */}
                                                 <div className="col-span-12 grid grid-cols-1 md:grid-cols-12 border-b border-gray-100 py-3 px-6 hover:bg-gray-50 items-center">
                                                    <div className="md:col-span-2 font-medium text-gray-600 text-xs uppercase md:text-sm md:normal-case md:text-gray-600 mb-1 md:mb-0">Wild or Farmed</div>
                                                    <div className="md:col-span-5 md:border-l border-gray-200 md:pl-4 mb-2 md:mb-0">{getInputDetail(item, 'Wild or Farmed')}</div>
                                                    <div className="md:col-span-5 md:border-l border-gray-200 md:pl-4 text-gray-400 italic text-xs">-</div>
                                                </div>

                                                {/* Row: Species (Renamed) */}
                                                <div className="col-span-12 grid grid-cols-1 md:grid-cols-12 border-b border-gray-100 py-3 px-6 hover:bg-gray-50 items-center">
                                                    <div className="md:col-span-2 font-medium text-gray-600 text-xs uppercase md:text-sm md:normal-case md:text-gray-600 mb-1 md:mb-0">Species</div>
                                                    <div className="md:col-span-5 md:border-l border-gray-200 md:pl-4 mb-2 md:mb-0">{getInputDetail(item, 'Common name')}</div>
                                                    <div className="md:col-span-5 md:border-l border-gray-200 md:pl-4 font-medium text-gray-800">{matchDetails.species}</div>
                                                </div>

                                                {/* Row: Country (Renamed) */}
                                                <div className="col-span-12 grid grid-cols-1 md:grid-cols-12 border-b border-gray-100 py-3 px-6 hover:bg-gray-50 items-center">
                                                    <div className="md:col-span-2 font-medium text-gray-600 text-xs uppercase md:text-sm md:normal-case md:text-gray-600 mb-1 md:mb-0">Country</div>
                                                    <div className="md:col-span-5 md:border-l border-gray-200 md:pl-4 mb-2 md:mb-0">{getInputDetail(item, 'Source country')}</div>
                                                    <div className="md:col-span-5 md:border-l border-gray-200 md:pl-4 text-gray-800">{matchDetails.location}</div>
                                                </div>

                                                 {/* Row: Body of Water (Conditional) */}
                                                 {showBodyOfWater && (
                                                    <div className="col-span-12 grid grid-cols-1 md:grid-cols-12 border-b border-gray-100 py-3 px-6 hover:bg-gray-50 items-center">
                                                        <div className="md:col-span-2 font-medium text-gray-600 text-xs uppercase md:text-sm md:normal-case md:text-gray-600 mb-1 md:mb-0">Body of Water</div>
                                                        <div className="md:col-span-5 md:border-l border-gray-200 md:pl-4 mb-2 md:mb-0">{getInputDetail(item, 'Body of Water')}</div>
                                                        <div className="md:col-span-5 md:border-l border-gray-200 md:pl-4 text-gray-400 italic text-xs">-</div>
                                                    </div>
                                                 )}

                                                {/* Row: Method */}
                                                <div className="col-span-12 grid grid-cols-1 md:grid-cols-12 border-b border-gray-100 py-3 px-6 hover:bg-gray-50 items-center">
                                                    <div className="md:col-span-2 font-medium text-gray-600 text-xs uppercase md:text-sm md:normal-case md:text-gray-600 mb-1 md:mb-0">Method</div>
                                                    <div className="md:col-span-5 md:border-l border-gray-200 md:pl-4 mb-2 md:mb-0">{getInputDetail(item, 'Production Method')}</div>
                                                    <div className="md:col-span-5 md:border-l border-gray-200 md:pl-4 text-gray-800">{matchDetails.method}</div>
                                                </div>

                                                {/* Row: Rating & Confidence */}
                                                <div className="col-span-12 grid grid-cols-1 md:grid-cols-12 py-4 px-6 bg-blue-50/30 items-center">
                                                    <div className="md:col-span-2 font-medium text-gray-600 text-xs uppercase md:text-sm md:normal-case md:text-gray-600 mb-1 md:mb-0">Result</div>
                                                    <div className="md:col-span-5 md:border-l border-gray-200 md:pl-4 flex items-center gap-2 mb-2 md:mb-0">
                                                        {/* Wild/Farmed moved to separate row above */}
                                                    </div>
                                                    <div className="md:col-span-5 md:border-l border-gray-200 md:pl-4">
                                                        <div className="flex flex-wrap items-center gap-4">
                                                            <div className="flex items-center gap-2 bg-white px-2 py-1 rounded border border-gray-200">
                                                                    <span className="text-gray-500 text-xs uppercase font-bold">Rating:</span>
                                                                    <RatingBadge rating={item.rating} />
                                                            </div>
                                                            <div className="flex items-center gap-2 bg-white px-2 py-1 rounded border border-gray-200">
                                                                    <span className="text-gray-500 text-xs uppercase font-bold">Reliability:</span>
                                                                    <span className={`font-bold ${item.reliabilityScore > 80 ? 'text-green-600' : 'text-yellow-600'}`}>{item.reliabilityScore}%</span>
                                                            </div>
                                                        </div>
                                                    </div>
                                                </div>
                                            </div>

                                            {/* Footer: Edit ID */}
                                            <div className="bg-gray-50 px-6 py-4 border-t border-gray-200 flex flex-col md:flex-row items-start md:items-center gap-4">
                                                <div className="flex-grow">
                                                    <label htmlFor={`edit-id-${index}`} className="block text-xs font-bold text-gray-700 mb-1">
                                                        Is this match incorrect? Manually update the Unique ID:
                                                    </label>
                                                    <div className="flex gap-2 max-w-md">
                                                        <input 
                                                            id={`edit-id-${index}`}
                                                            type="text" 
                                                            value={editValue} 
                                                            onChange={(e) => setEditValue(e.target.value)}
                                                            className="flex-grow text-sm border border-gray-300 rounded px-3 py-1.5 focus:outline-none focus:ring-1 focus:ring-blue-500 shadow-sm"
                                                            placeholder="Enter official Seafood Watch ID..."
                                                        />
                                                        <button 
                                                            onClick={() => handleSubmitEdit(item._originalIndex)}
                                                            className="bg-blue-600 text-white text-xs px-4 py-1.5 rounded font-semibold hover:bg-blue-700 focus:outline-none focus:ring-2 focus:ring-offset-1 focus:ring-blue-600 disabled:opacity-50 disabled:cursor-not-allowed shadow-sm"
                                                            disabled={!editValue || editValue === item.uniqueId}
                                                        >
                                                            Update ID
                                                        </button>
                                                    </div>
                                                </div>
                                                <div className="text-xs text-gray-500 italic max-w-xs">
                                                    Tip: Updating the ID will force the system to use the official details associated with that ID.
                                                </div>
                                            </div>
                                        </div>
                                    </td>
                                </tr>
                            )}
                        </React.Fragment>
                    );
                })}
            </tbody>
            </table>
        ) : (
            <p className="text-center text-gray-500 my-8 py-4">
                No results found for your search: "{searchTerm}".
            </p>
        )}
      </div>
    </div>
  );
};

export default ResultsTable;

import React, { useState, useCallback, useRef, useEffect, useMemo } from 'react';
import { SeafoodResultItem } from '../types';
import RatingBadge from './RatingBadge';
import ColumnToggler from './ColumnToggler';

interface ResultsTableProps {
  results: any[];
  originalHeaders: string[];
  columnMapping?: Record<string, string>;
  onExport: () => void;
  filterTitle?: string;
  onClearFilter?: () => void;
  visibleColumns: Set<string>;
  onVisibleColumnsChange: (newVisible: Set<string>) => void;
  onUpdateResult?: (index: number, newUniqueId: string) => Promise<void>;
}

type SortDirection = 'ascending' | 'descending';

const SortIcon: React.FC<{ direction: SortDirection | null }> = ({ direction }) => {
    if (!direction) return null;
    return (
      <svg
        className="w-4 h-4 ml-1 inline-block text-gray-500 flex-shrink-0"
        aria-hidden="true"
        fill="currentColor"
        viewBox="0 0 20 20"
        xmlns="http://www.w3.org/2000/svg"
      >
        {direction === 'descending' ? (
          <path
            fillRule="evenodd"
            d="M5.293 7.293a1 1 0 011.414 0L10 10.586l3.293-3.293a1 1 0 111.414 1.414l-4 4a1 1 0 01-1.414 0l-4-4a1 1 0 010-1.414z"
            clipRule="evenodd"
          />
        ) : (
          <path
            fillRule="evenodd"
            d="M14.707 12.707a1 1 0 01-1.414 0L10 9.414l-3.293 3.293a1 1 0 01-1.414-1.414l4-4a1 1 0 011.414 0l4 4a1 1 0 010 1.414z"
            clipRule="evenodd"
          />
        )}
      </svg>
    );
};


const ResultsTable: React.FC<ResultsTableProps> = ({ 
  results, 
  originalHeaders,
  columnMapping = {},
  onExport, 
  filterTitle, 
  onClearFilter,
  visibleColumns, 
  onVisibleColumnsChange,
  onUpdateResult
}) => {
  const [columnWidths, setColumnWidths] = useState<Record<string, number>>({});
  const isResizing = useRef<string | null>(null);
  const [sortConfig, setSortConfig] = useState<{ key: string; direction: SortDirection } | null>(null);
  const [searchTerm, setSearchTerm] = useState('');

  // Expanded Row State (Accordion)
  const [expandedRowIndex, setExpandedRowIndex] = useState<number | null>(null);
  // Temporary state for the input field inside the expanded view
  const [editValue, setEditValue] = useState<string>('');


  // Refs for synced scrolling
  const tableContainerRef = useRef<HTMLDivElement>(null);
  const topScrollRef = useRef<HTMLDivElement>(null);
  const [scrollWidth, setScrollWidth] = useState(0);

  const sortedResults = useMemo(() => {
    // Add original index to items to track them after sorting
    const itemsWithIndex = results.map((item, index) => ({ ...item, _originalIndex: index }));

    if (!sortConfig) {
      return itemsWithIndex;
    }
    const sortableItems = [...itemsWithIndex];
    sortableItems.sort((a, b) => {
        const aVal = a[sortConfig.key];
        const bVal = b[sortConfig.key];

        if (aVal == null) return 1;
        if (bVal == null) return -1;

        if (typeof aVal === 'number' && typeof bVal === 'number') {
            return sortConfig.direction === 'ascending' ? aVal - bVal : bVal - aVal;
        }

        const aStr = String(aVal);
        const bStr = String(bVal);
        const comparison = aStr.localeCompare(bStr, undefined, { numeric: true, sensitivity: 'base' });

        return sortConfig.direction === 'ascending' ? comparison : -comparison;
      });

    return sortableItems;
  }, [results, sortConfig]);

  const filteredAndSortedResults = useMemo(() => {
    if (!searchTerm) {
      return sortedResults;
    }
    const lowercasedFilter = searchTerm.toLowerCase();
    return sortedResults.filter(item => {
       const { _originalIndex, isUpdating, ...searchableItem } = item;
      return Object.values(searchableItem).some(value =>
        String(value).toLowerCase().includes(lowercasedFilter)
      );
    });
  }, [sortedResults, searchTerm]);

  // Sync scrollbars
  useEffect(() => {
    const syncScroll = (source: 'top' | 'bottom') => {
      const top = topScrollRef.current;
      const bottom = tableContainerRef.current;
      if (!top || !bottom) return;

      if (source === 'top') {
        bottom.scrollLeft = top.scrollLeft;
      } else {
        top.scrollLeft = bottom.scrollLeft;
      }
    };

    const top = topScrollRef.current;
    const bottom = tableContainerRef.current;

    if (top && bottom) {
      const handleTopScroll = () => syncScroll('top');
      const handleBottomScroll = () => syncScroll('bottom');

      top.addEventListener('scroll', handleTopScroll);
      bottom.addEventListener('scroll', handleBottomScroll);

      return () => {
        top.removeEventListener('scroll', handleTopScroll);
        bottom.removeEventListener('scroll', handleBottomScroll);
      };
    }
  }, []);

  // Update scroll width when data or columns change
  useEffect(() => {
    if (tableContainerRef.current) {
      setScrollWidth(tableContainerRef.current.scrollWidth);
    }
  }, [visibleColumns, filteredAndSortedResults, columnWidths]);


  const requestSort = (key: string) => {
    let direction: SortDirection = 'ascending';
    if (sortConfig && sortConfig.key === key && sortConfig.direction === 'ascending') {
      direction = 'descending';
    }
    setSortConfig({ key, direction });
  };

  const toggleRow = (e: React.MouseEvent, rowIndex: number, currentId: string) => {
      e.stopPropagation();
      if (expandedRowIndex === rowIndex) {
          setExpandedRowIndex(null);
          setEditValue('');
      } else {
          setExpandedRowIndex(rowIndex);
          setEditValue(currentId);
      }
  };

  const handleSubmitEdit = async (index: number) => {
      if (onUpdateResult && editValue) {
          await onUpdateResult(index, editValue);
          // Don't close row automatically, user might want to see update.
      }
  };


  if (!results.length) {
    return <p className="text-center text-gray-500 my-8">
        {filterTitle ? `No data matches the filter "${filterTitle}".` : 'No data to display.'}
    </p>;
  }

  const addedHeaders = [
    { key: 'uniqueId', title: 'Unique ID' },
    { key: 'rating', title: 'Rating' },
    { key: 'reliabilityScore', title: 'Reliability' },
    { key: 'notes', title: 'Notes' },
  ];

  const allColumns = [
    ...originalHeaders.map(h => ({ key: h, title: h })),
    ...addedHeaders.map(h => ({ key: h.key, title: h.title }))
  ];

  const visibleOriginalHeaders = originalHeaders.filter(h => visibleColumns.has(h));
  const visibleAddedHeaders = addedHeaders.filter(h => visibleColumns.has(h.key));
  const totalColSpan = visibleOriginalHeaders.length + visibleAddedHeaders.length;

  useEffect(() => {
    setColumnWidths(prevWidths => {
        const newWidths = { ...prevWidths };
        visibleOriginalHeaders.forEach(h => {
            if (!newWidths[h]) newWidths[h] = 100;
        });
        visibleAddedHeaders.forEach(h => {
            if (!newWidths[h.key]) {
                if (h.key === 'notes') newWidths[h.key] = 400;
                else if (h.key === 'reliabilityScore') newWidths[h.key] = 90;
                else if (h.key === 'uniqueId') newWidths[h.key] = 100;
                else newWidths[h.key] = 90;
            }
        });
        return newWidths;
    });
  }, [visibleOriginalHeaders, visibleAddedHeaders]);

  const handleMouseDown = useCallback((e: React.MouseEvent<HTMLDivElement>, headerKey: string) => {
    isResizing.current = headerKey;
    const startX = e.clientX;
    const startWidth = columnWidths[headerKey] || 0;

    const handleMouseMove = (moveEvent: MouseEvent) => {
      if (isResizing.current !== headerKey) return;
      const width = startWidth + (moveEvent.clientX - startX);
      if (width > 50) { // Min width
        setColumnWidths(prev => ({ ...prev, [headerKey]: width }));
      }
    };

    const handleMouseUp = () => {
      isResizing.current = null;
      window.removeEventListener('mousemove', handleMouseMove);
      window.removeEventListener('mouseup', handleMouseUp);
      document.body.style.cursor = 'default';
      document.body.style.userSelect = 'auto';
    };

    window.addEventListener('mousemove', handleMouseMove);
    window.addEventListener('mouseup', handleMouseUp);
    e.preventDefault();
    document.body.style.cursor = 'col-resize';
    document.body.style.userSelect = 'none';
  }, [columnWidths]);

  const renderUniqueId = (item: any, originalIndex: number) => {
    if (item.isUpdating) {
        return (
           <div className="flex items-center space-x-2">
               <div className="w-3 h-3 border-2 border-blue-600 border-dashed rounded-full animate-spin"></div>
               <span className="text-xs text-gray-500">Updating...</span>
           </div>
        );
    }

    const isExpanded = expandedRowIndex === originalIndex;

    return (
      <button 
          onClick={(e) => toggleRow(e, originalIndex, item.uniqueId)}
          className={`flex items-center space-x-2 px-2 py-1 rounded transition-colors w-full text-left font-mono text-xs border ${isExpanded ? 'bg-blue-600 text-white border-blue-600' : 'text-blue-700 hover:bg-blue-50 border-transparent hover:border-blue-200'}`}
          title="Click to view details & edit"
          aria-expanded={isExpanded}
      >
          <span>{item.uniqueId}</span>
          <svg 
            xmlns="http://www.w3.org/2000/svg" 
            className={`h-3 w-3 transition-transform duration-200 ${isExpanded ? 'rotate-180' : ''}`} 
            fill="none" 
            viewBox="0 0 24 24" 
            stroke="currentColor"
          >
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 9l-7 7-7-7" />
          </svg>
      </button>
    );
  };

  const addedColumnRenderers: Record<string, (item: any, originalIndex: number) => React.ReactNode> = {
    uniqueId: (item, originalIndex) => renderUniqueId(item, originalIndex),
    rating: (item) => <RatingBadge rating={item.rating} />,
    reliabilityScore: (item) => (
        <div className="flex items-center" aria-label={`Reliability: ${item.reliabilityScore}%`}>
            <div role="progressbar" aria-valuenow={item.reliabilityScore} aria-valuemin={0} aria-valuemax={100} className="w-16 bg-gray-200 rounded-full h-2.5">
                <div className="bg-blue-600 h-2.5 rounded-full" style={{ width: `${item.reliabilityScore}%` }}></div>
            </div>
            <span className="ml-2 font-medium text-xs">{item.reliabilityScore}%</span>
        </div>
    ),
    notes: (item) => <span className="block leading-tight">{item.notes}</span>,
  };

  // Helper to extract input details for comparison
  const getInputDetail = (item: any, fieldKey: string) => {
      const header = columnMapping[fieldKey];
      if (!header || header === 'N/A') return <span className="text-gray-400 italic">Not mapped</span>;
      const val = item[header];
      return val ? <span className="font-medium text-gray-900">{String(val)}</span> : <span className="text-gray-400 italic">Empty</span>;
  };

  // Helper to check if input data exists for conditional rendering
  const hasInputData = (item: any, fieldKey: string) => {
      const header = columnMapping[fieldKey];
      if (!header || header === 'N/A') return false;
      const val = item[header];
      return val !== undefined && val !== null && String(val).trim() !== '';
  };

  // Parse KDE string for display in comparison grid
  const parseMatchedKDE = (kdeString: string) => {
      if (!kdeString || kdeString === 'N/A') return { species: 'N/A', location: 'N/A', method: 'N/A' };
      const parts = kdeString.split(' | ');
      if (parts.length >= 3) {
          return {
              species: parts[0],
              location: parts[1],
              method: parts.slice(2).join(' | ')
          };
      }
      return { species: kdeString, location: '-', method: '-' };
  };


  return (
    <div className="w-full bg-white p-6 md:p-8 rounded-lg shadow-lg border border-gray-200 relative">
      <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center mb-6 gap-4">
        <div className="flex-grow">
          <h2 id="results-heading" className="text-2xl font-bold text-gray-800">Analysis Results</h2>
          <p className="text-sm text-gray-500 mt-1">Tip: Click a Unique ID to expand the row and compare details.</p>
          {filterTitle && (
            <div className="flex items-center gap-3 mt-2">
                <p className="text-sm text-gray-600">
                    Showing data for: <span className="font-semibold bg-blue-100 text-blue-800 px-2 py-1 rounded-md">{filterTitle}</span>
                </p>
                <button 
                    onClick={onClearFilter}
                    className="text-sm text-blue-600 hover:underline"
                >
                    Clear Filter
                </button>
            </div>
          )}
          <div className="mt-4 flex items-center gap-4">
            <div className="relative flex-grow max-w-sm">
                <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
                    <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5 text-gray-400" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" />
                    </svg>
                </div>
                <input
                    type="search"
                    id="table-search"
                    aria-label="Search results"
                    placeholder={`Search in ${results.length} results...`}
                    value={searchTerm}
                    onChange={(e) => setSearchTerm(e.target.value)}
                    className="block w-full pl-10 pr-3 py-2 border border-gray-300 rounded-md leading-5 bg-white placeholder-gray-500 focus:outline-none focus:placeholder-gray-400 focus:ring-1 focus:ring-blue-500 focus:border-blue-500 sm:text-sm"
                />
            </div>
            {searchTerm && (
                <button
                    onClick={() => setSearchTerm('')}
                    className="text-sm text-blue-600 hover:underline"
                >
                    Clear Search
                </button>
            )}
          </div>
        </div>
        <div className="flex items-center gap-4 flex-shrink-0">
          <ColumnToggler 
            allColumns={allColumns}
            visibleColumns={visibleColumns}
            onVisibilityChange={onVisibleColumnsChange}
          />
          <button
            onClick={onExport}
            className="flex items-center gap-2 px-4 py-2 text-sm font-semibold text-white bg-green-600 rounded-md hover:bg-green-700 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-green-600 transition-colors duration-200"
          >
            <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth="2">
                <path strokeLinecap="round" strokeLinejoin="round" d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-4l-4 4m0 0l-4-4m4 4V4" />
            </svg>
            Export Full Dataset (CSV)
          </button>
        </div>
      </div>

      {/* Top Scrollbar */}
      <div 
        ref={topScrollRef}
        className="overflow-x-auto w-full mb-1"
        style={{ height: '12px' }}
      >
        <div style={{ width: scrollWidth, height: '1px' }}></div>
      </div>

      <div 
        ref={tableContainerRef}
        className="overflow-x-auto max-h-[70vh]" // Constrain height for sticky header
      >
        {filteredAndSortedResults.length > 0 ? (
            <table className="min-w-full divide-y divide-gray-200 table-fixed" aria-labelledby="results-heading">
            {/* Sticky Header */}
            <thead className="bg-gray-100 sticky top-0 z-10 shadow-sm">
                <tr>
                {visibleOriginalHeaders.map((header) => (
                    <th 
                        key={header} 
                        scope="col" 
                        className="px-2 py-2 text-left text-xs font-bold text-gray-600 uppercase tracking-wider relative group bg-gray-100 align-bottom border-b border-gray-200"
                        style={{ width: columnWidths[header] ? `${columnWidths[header]}px` : undefined }}
                        aria-sort={sortConfig?.key === header ? sortConfig.direction : 'none'}
                    >
                    <button onClick={() => requestSort(header)} className="flex items-end w-full h-full">
                        <span className="whitespace-normal break-words leading-tight">{header}</span>
                        <SortIcon direction={sortConfig?.key === header ? sortConfig.direction : null} />
                    </button>
                    <div
                        onMouseDown={(e) => handleMouseDown(e, header)}
                        aria-hidden="true"
                        className="absolute top-0 right-0 h-full w-2 cursor-col-resize hover:bg-blue-200"
                    />
                    </th>
                ))}
                {visibleAddedHeaders.map((header) => (
                    <th 
                        key={header.key} 
                        scope="col" 
                        className="px-2 py-2 text-left text-xs font-bold text-blue-800 bg-blue-100 uppercase tracking-wider relative group align-bottom border-b border-blue-200"
                        style={{ width: columnWidths[header.key] ? `${columnWidths[header.key]}px` : undefined }}
                        aria-sort={sortConfig?.key === header.key ? sortConfig.direction : 'none'}
                    >
                    <button onClick={() => requestSort(header.key)} className="flex items-end w-full h-full">
                        <span className="whitespace-normal break-words leading-tight">{header.title}</span>
                        <SortIcon direction={sortConfig?.key === header.key ? sortConfig.direction : null} />
                    </button>
                    <div
                        onMouseDown={(e) => handleMouseDown(e, header.key)}
                        aria-hidden="true"
                        className="absolute top-0 right-0 h-full w-2 cursor-col-resize hover:bg-blue-300"
                    />
                    </th>
                ))}
                </tr>
            </thead>
            <tbody className="bg-white divide-y divide-gray-200">
                {filteredAndSortedResults.map((item, index) => {
                    const isExpanded = expandedRowIndex === item._originalIndex;
                    const matchDetails = parseMatchedKDE(item.matchedKDEs);

                    return (
                        <React.Fragment key={index}>
                            <tr className={`${isExpanded ? 'bg-blue-50' : 'hover:bg-gray-50'}`}>
                                {visibleOriginalHeaders.map((header) => (
                                <td key={`${header}-${index}`} className="px-2 py-2 text-xs text-gray-700 break-words align-top leading-tight">
                                    {item[header]}
                                </td>
                                ))}
                                {visibleAddedHeaders.map((header) => (
                                    <td key={`${header.key}-${index}`} className="px-2 py-2 text-xs text-gray-700 bg-blue-50/50 align-top leading-tight">
                                        {addedColumnRenderers[header.key](item, item._originalIndex)}
                                    </td>
                                ))}
                            </tr>
                            {isExpanded && (
                                <tr className="bg-slate-100 shadow-inner">
                                    <td colSpan={totalColSpan} className="px-4 py-6">
                                        <div className="bg-white rounded-lg shadow-sm border border-gray-200 overflow-hidden max-w-5xl mx-auto">
                                            {/* Header */}
                                            <div className="bg-gray-50 px-6 py-3 border-b border-gray-200 flex justify-between items-center">
                                                <h4 className="font-bold text-gray-700 text-sm uppercase tracking-wide">Match Analysis & Comparison</h4>
                                                <div className="text-xs text-gray-500">
                                                    Comparing row {index + 1}
                                                </div>
                                            </div>

                                            {/* Comparison Grid */}
                                            <div className="grid grid-cols-1 md:grid-cols-12 text-sm">
                                                {/* Column Headers (Visible on MD+) */}
                                                <div className="hidden md:contents">
                                                    <div className="col-span-12 grid grid-cols-12 border-b border-gray-100 bg-gray-50/50 py-2 px-6 font-semibold text-gray-500 text-xs uppercase">
                                                        <div className="col-span-2">Attribute</div>
                                                        <div className="col-span-5 border-l border-gray-200 pl-4">Your Input (Product Details)</div>
                                                        <div className="col-span-5 border-l border-gray-200 pl-4 text-blue-700">Seafood Watch Match</div>
                                                    </div>
                                                </div>

                                                 {/* Row: Wild or Farmed */}
                                                 {hasInputData(item, 'Wild or Farmed') && (
                                                    <div className="col-span-12 grid grid-cols-1 md:grid-cols-12 border-b border-gray-100 py-3 px-6 hover:bg-gray-50 items-center">
                                                        <div className="md:col-span-2 font-medium text-gray-600 text-xs uppercase md:text-sm md:normal-case md:text-gray-600 mb-1 md:mb-0">Wild or Farmed</div>
                                                        <div className="md:col-span-5 md:border-l border-gray-200 md:pl-4 mb-2 md:mb-0">{getInputDetail(item, 'Wild or Farmed')}</div>
                                                        <div className="md:col-span-5 md:border-l border-gray-200 md:pl-4 text-gray-400 italic text-xs">-</div>
                                                    </div>
                                                 )}

                                                {/* Row: Species */}
                                                {hasInputData(item, 'Common name') && (
                                                    <div className="col-span-12 grid grid-cols-1 md:grid-cols-12 border-b border-gray-100 py-3 px-6 hover:bg-gray-50 items-center">
                                                        <div className="md:col-span-2 font-medium text-gray-600 text-xs uppercase md:text-sm md:normal-case md:text-gray-600 mb-1 md:mb-0">Species</div>
                                                        <div className="md:col-span-5 md:border-l border-gray-200 md:pl-4 mb-2 md:mb-0">{getInputDetail(item, 'Common name')}</div>
                                                        <div className="md:col-span-5 md:border-l border-gray-200 md:pl-4 font-medium text-gray-800">{matchDetails.species}</div>
                                                    </div>
                                                )}

                                                {/* Row: Country */}
                                                {hasInputData(item, 'Source country') && (
                                                    <div className="col-span-12 grid grid-cols-1 md:grid-cols-12 border-b border-gray-100 py-3 px-6 hover:bg-gray-50 items-center">
                                                        <div className="md:col-span-2 font-medium text-gray-600 text-xs uppercase md:text-sm md:normal-case md:text-gray-600 mb-1 md:mb-0">Country</div>
                                                        <div className="md:col-span-5 md:border-l border-gray-200 md:pl-4 mb-2 md:mb-0">{getInputDetail(item, 'Source country')}</div>
                                                        <div className="md:col-span-5 md:border-l border-gray-200 md:pl-4 text-gray-800">{matchDetails.location}</div>
                                                    </div>
                                                )}

                                                 {/* Row: Body of Water */}
                                                 {hasInputData(item, 'Body of Water') && (
                                                    <div className="col-span-12 grid grid-cols-1 md:grid-cols-12 border-b border-gray-100 py-3 px-6 hover:bg-gray-50 items-center">
                                                        <div className="md:col-span-2 font-medium text-gray-600 text-xs uppercase md:text-sm md:normal-case md:text-gray-600 mb-1 md:mb-0">Body of Water</div>
                                                        <div className="md:col-span-5 md:border-l border-gray-200 md:pl-4 mb-2 md:mb-0">{getInputDetail(item, 'Body of Water')}</div>
                                                        <div className="md:col-span-5 md:border-l border-gray-200 md:pl-4 text-gray-400 italic text-xs">-</div>
                                                    </div>
                                                 )}

                                                {/* Row: Method */}
                                                {hasInputData(item, 'Production Method') && (
                                                    <div className="col-span-12 grid grid-cols-1 md:grid-cols-12 border-b border-gray-100 py-3 px-6 hover:bg-gray-50 items-center">
                                                        <div className="md:col-span-2 font-medium text-gray-600 text-xs uppercase md:text-sm md:normal-case md:text-gray-600 mb-1 md:mb-0">Method</div>
                                                        <div className="md:col-span-5 md:border-l border-gray-200 md:pl-4 mb-2 md:mb-0">{getInputDetail(item, 'Production Method')}</div>
                                                        <div className="md:col-span-5 md:border-l border-gray-200 md:pl-4 text-gray-800">{matchDetails.method}</div>
                                                    </div>
                                                )}

                                                {/* Row: Rating & Confidence */}
                                                <div className="col-span-12 grid grid-cols-1 md:grid-cols-12 py-4 px-6 bg-blue-50/30 items-center">
                                                    <div className="md:col-span-2 font-medium text-gray-600 text-xs uppercase md:text-sm md:normal-case md:text-gray-600 mb-1 md:mb-0">Result</div>
                                                    <div className="md:col-span-5 md:border-l border-gray-200 md:pl-4 flex items-center gap-2 mb-2 md:mb-0">
                                                        {/* Wild/Farmed moved to separate row above */}
                                                    </div>
                                                    <div className="md:col-span-5 md:border-l border-gray-200 md:pl-4">
                                                        <div className="flex flex-wrap items-center gap-4">
                                                            <div className="flex items-center gap-2 bg-white px-2 py-1 rounded border border-gray-200">
                                                                    <span className="text-gray-500 text-xs uppercase font-bold">Rating:</span>
                                                                    <RatingBadge rating={item.rating} />
                                                            </div>
                                                            <div className="flex items-center gap-2 bg-white px-2 py-1 rounded border border-gray-200">
                                                                    <span className="text-gray-500 text-xs uppercase font-bold">Reliability:</span>
                                                                    <span className={`font-bold ${item.reliabilityScore > 80 ? 'text-green-600' : 'text-yellow-600'}`}>{item.reliabilityScore}%</span>
                                                            </div>
                                                        </div>
                                                    </div>
                                                </div>
                                            </div>

                                            {/* Footer: Edit ID */}
                                            <div className="bg-gray-50 px-6 py-4 border-t border-gray-200 flex flex-col md:flex-row items-start md:items-center gap-4">
                                                <div className="flex-grow">
                                                    <label htmlFor={`edit-id-${index}`} className="block text-xs font-bold text-gray-700 mb-1">
                                                        Is this match incorrect? Manually update the Unique ID:
                                                    </label>
                                                    <div className="flex gap-2 max-w-md">
                                                        <input 
                                                            id={`edit-id-${index}`}
                                                            type="text" 
                                                            value={editValue} 
                                                            onChange={(e) => setEditValue(e.target.value)}
                                                            className="flex-grow text-sm border border-gray-300 rounded px-3 py-1.5 focus:outline-none focus:ring-1 focus:ring-blue-500 shadow-sm"
                                                            placeholder="Enter official Seafood Watch ID..."
                                                        />
                                                        <button 
                                                            onClick={() => handleSubmitEdit(item._originalIndex)}
                                                            className="bg-blue-600 text-white text-xs px-4 py-1.5 rounded font-semibold hover:bg-blue-700 focus:outline-none focus:ring-2 focus:ring-offset-1 focus:ring-blue-600 disabled:opacity-50 disabled:cursor-not-allowed shadow-sm"
                                                            disabled={!editValue || editValue === item.uniqueId}
                                                        >
                                                            Update ID
                                                        </button>
                                                    </div>
                                                </div>
                                                <div className="text-xs text-gray-500 italic max-w-xs">
                                                    Tip: Updating the ID will force the system to use the official details associated with that ID.
                                                </div>
                                            </div>
                                        </div>
                                    </td>
                                </tr>
                            )}
                        </React.Fragment>
                    );
                })}
            </tbody>
            </table>
        ) : (
            <p className="text-center text-gray-500 my-8 py-4">
                No results found for your search: "{searchTerm}".
            </p>
        )}
      </div>
    </div>
  );
};

export default ResultsTable;

import React, { useState, useCallback, useRef, useEffect, useMemo } from 'react';
import { SeafoodResultItem } from '../types';
import RatingBadge from './RatingBadge';
import ColumnToggler from './ColumnToggler';

interface ResultsTableProps {
  results: any[];
  originalHeaders: string[];
  columnMapping?: Record<string, string>;
  onExport: () => void;
  filterTitle?: string;
  onClearFilter?: () => void;
  visibleColumns: Set<string>;
  onVisibleColumnsChange: (newVisible: Set<string>) => void;
  onUpdateResult?: (index: number, newUniqueId: string) => Promise<void>;
}

type SortDirection = 'ascending' | 'descending';

const SortIcon: React.FC<{ direction: SortDirection | null }> = ({ direction }) => {
    if (!direction) return null;
    return (
      <svg
        className="w-4 h-4 ml-1 inline-block text-gray-500 flex-shrink-0"
        aria-hidden="true"
        fill="currentColor"
        viewBox="0 0 20 20"
        xmlns="http://www.w3.org/2000/svg"
      >
        {direction === 'descending' ? (
          <path
            fillRule="evenodd"
            d="M5.293 7.293a1 1 0 011.414 0L10 10.586l3.293-3.293a1 1 0 111.414 1.414l-4 4a1 1 0 01-1.414 0l-4-4a1 1 0 010-1.414z"
            clipRule="evenodd"
          />
        ) : (
          <path
            fillRule="evenodd"
            d="M14.707 12.707a1 1 0 01-1.414 0L10 9.414l-3.293 3.293a1 1 0 01-1.414-1.414l4-4a1 1 0 011.414 0l4 4a1 1 0 010 1.414z"
            clipRule="evenodd"
          />
        )}
      </svg>
    );
};


const ResultsTable: React.FC<ResultsTableProps> = ({ 
  results, 
  originalHeaders,
  columnMapping = {},
  onExport, 
  filterTitle, 
  onClearFilter,
  visibleColumns, 
  onVisibleColumnsChange,
  onUpdateResult
}) => {
  const [columnWidths, setColumnWidths] = useState<Record<string, number>>({});
  const isResizing = useRef<string | null>(null);
  const [sortConfig, setSortConfig] = useState<{ key: string; direction: SortDirection } | null>(null);
  const [searchTerm, setSearchTerm] = useState('');

  // Expanded Row State (Accordion)
  const [expandedRowIndex, setExpandedRowIndex] = useState<number | null>(null);
  // Temporary state for the input field inside the expanded view
  const [editValue, setEditValue] = useState<string>('');


  // Refs for synced scrolling
  const tableContainerRef = useRef<HTMLDivElement>(null);
  const topScrollRef = useRef<HTMLDivElement>(null);
  const [scrollWidth, setScrollWidth] = useState(0);

  const sortedResults = useMemo(() => {
    // Add original index to items to track them after sorting
    const itemsWithIndex = results.map((item, index) => ({ ...item, _originalIndex: index }));

    if (!sortConfig) {
      return itemsWithIndex;
    }
    const sortableItems = [...itemsWithIndex];
    sortableItems.sort((a, b) => {
        const aVal = a[sortConfig.key];
        const bVal = b[sortConfig.key];

        if (aVal == null) return 1;
        if (bVal == null) return -1;

        if (typeof aVal === 'number' && typeof bVal === 'number') {
            return sortConfig.direction === 'ascending' ? aVal - bVal : bVal - aVal;
        }

        const aStr = String(aVal);
        const bStr = String(bVal);
        const comparison = aStr.localeCompare(bStr, undefined, { numeric: true, sensitivity: 'base' });

        return sortConfig.direction === 'ascending' ? comparison : -comparison;
      });

    return sortableItems;
  }, [results, sortConfig]);

  const filteredAndSortedResults = useMemo(() => {
    if (!searchTerm) {
      return sortedResults;
    }
    const lowercasedFilter = searchTerm.toLowerCase();
    return sortedResults.filter(item => {
       const { _originalIndex, isUpdating, ...searchableItem } = item;
      return Object.values(searchableItem).some(value =>
        String(value).toLowerCase().includes(lowercasedFilter)
      );
    });
  }, [sortedResults, searchTerm]);

  // Sync scrollbars
  useEffect(() => {
    const syncScroll = (source: 'top' | 'bottom') => {
      const top = topScrollRef.current;
      const bottom = tableContainerRef.current;
      if (!top || !bottom) return;

      if (source === 'top') {
        bottom.scrollLeft = top.scrollLeft;
      } else {
        top.scrollLeft = bottom.scrollLeft;
      }
    };

    const top = topScrollRef.current;
    const bottom = tableContainerRef.current;

    if (top && bottom) {
      const handleTopScroll = () => syncScroll('top');
      const handleBottomScroll = () => syncScroll('bottom');

      top.addEventListener('scroll', handleTopScroll);
      bottom.addEventListener('scroll', handleBottomScroll);

      return () => {
        top.removeEventListener('scroll', handleTopScroll);
        bottom.removeEventListener('scroll', handleBottomScroll);
      };
    }
  }, []);

  // Update scroll width when data or columns change
  useEffect(() => {
    if (tableContainerRef.current) {
      setScrollWidth(tableContainerRef.current.scrollWidth);
    }
  }, [visibleColumns, filteredAndSortedResults, columnWidths]);


  const requestSort = (key: string) => {
    let direction: SortDirection = 'ascending';
    if (sortConfig && sortConfig.key === key && sortConfig.direction === 'ascending') {
      direction = 'descending';
    }
    setSortConfig({ key, direction });
  };

  const toggleRow = (e: React.MouseEvent, rowIndex: number, currentId: string) => {
      e.stopPropagation();
      if (expandedRowIndex === rowIndex) {
          setExpandedRowIndex(null);
          setEditValue('');
      } else {
          setExpandedRowIndex(rowIndex);
          setEditValue(currentId);
      }
  };

  const handleSubmitEdit = async (index: number) => {
      if (onUpdateResult && editValue) {
          await onUpdateResult(index, editValue);
          // Don't close row automatically, user might want to see update.
      }
  };


  if (!results.length) {
    return <p className="text-center text-gray-500 my-8">
        {filterTitle ? `No data matches the filter "${filterTitle}".` : 'No data to display.'}
    </p>;
  }

  const addedHeaders = [
    { key: 'uniqueId', title: 'Unique ID' },
    { key: 'rating', title: 'Rating' },
    { key: 'reliabilityScore', title: 'Reliability' },
    { key: 'notes', title: 'Notes' },
  ];

  const allColumns = [
    ...originalHeaders.map(h => ({ key: h, title: h })),
    ...addedHeaders.map(h => ({ key: h.key, title: h.title }))
  ];

  const visibleOriginalHeaders = originalHeaders.filter(h => visibleColumns.has(h));
  const visibleAddedHeaders = addedHeaders.filter(h => visibleColumns.has(h.key));
  const totalColSpan = visibleOriginalHeaders.length + visibleAddedHeaders.length;

  // Calculate sticky offsets for the added headers (they will be stuck to the right)
  const stickyOffsets = useMemo(() => {
      const offsets: Record<string, number> = {};
      let currentRight = 0;
      // Reverse order because right:0 is the last column
      [...visibleAddedHeaders].reverse().forEach(h => {
          offsets[h.key] = currentRight;
          currentRight += (columnWidths[h.key] || (h.key === 'notes' ? 450 : 100));
      });
      return offsets;
  }, [visibleAddedHeaders, columnWidths]);


  useEffect(() => {
    setColumnWidths(prevWidths => {
        const newWidths = { ...prevWidths };
        visibleOriginalHeaders.forEach(h => {
            if (!newWidths[h]) newWidths[h] = 100;
        });
        visibleAddedHeaders.forEach(h => {
            if (!newWidths[h.key]) {
                if (h.key === 'notes') newWidths[h.key] = 450;
                else if (h.key === 'reliabilityScore') newWidths[h.key] = 90;
                else if (h.key === 'uniqueId') newWidths[h.key] = 120;
                else newWidths[h.key] = 90;
            }
        });
        return newWidths;
    });
  }, [visibleOriginalHeaders, visibleAddedHeaders]);

  const handleMouseDown = useCallback((e: React.MouseEvent<HTMLDivElement>, headerKey: string) => {
    isResizing.current = headerKey;
    const startX = e.clientX;
    const startWidth = columnWidths[headerKey] || 0;

    const handleMouseMove = (moveEvent: MouseEvent) => {
      if (isResizing.current !== headerKey) return;
      const width = startWidth + (moveEvent.clientX - startX);
      if (width > 50) { // Min width
        setColumnWidths(prev => ({ ...prev, [headerKey]: width }));
      }
    };

    const handleMouseUp = () => {
      isResizing.current = null;
      window.removeEventListener('mousemove', handleMouseMove);
      window.removeEventListener('mouseup', handleMouseUp);
      document.body.style.cursor = 'default';
      document.body.style.userSelect = 'auto';
    };

    window.addEventListener('mousemove', handleMouseMove);
    window.addEventListener('mouseup', handleMouseUp);
    e.preventDefault();
    document.body.style.cursor = 'col-resize';
    document.body.style.userSelect = 'none';
  }, [columnWidths]);

  const renderUniqueId = (item: any, originalIndex: number) => {
    if (item.isUpdating) {
        return (
           <div className="flex items-center space-x-2">
               <div className="w-3 h-3 border-2 border-blue-600 border-dashed rounded-full animate-spin"></div>
               <span className="text-xs text-gray-500">Updating...</span>
           </div>
        );
    }

    const isExpanded = expandedRowIndex === originalIndex;

    return (
      <button 
          onClick={(e) => toggleRow(e, originalIndex, item.uniqueId)}
          className={`flex items-center space-x-2 px-2 py-1 rounded transition-colors w-full text-left font-mono text-xs border ${isExpanded ? 'bg-blue-600 text-white border-blue-600' : 'text-blue-700 hover:bg-blue-200 border-transparent hover:border-blue-300'}`}
          title="Click to view details & edit"
          aria-expanded={isExpanded}
      >
          <span>{item.uniqueId}</span>
          <svg 
            xmlns="http://www.w3.org/2000/svg" 
            className={`h-3 w-3 transition-transform duration-200 ${isExpanded ? 'rotate-180' : ''}`} 
            fill="none" 
            viewBox="0 0 24 24" 
            stroke="currentColor"
          >
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 9l-7 7-7-7" />
          </svg>
      </button>
    );
  };

  const addedColumnRenderers: Record<string, (item: any, originalIndex: number) => React.ReactNode> = {
    uniqueId: (item, originalIndex) => renderUniqueId(item, originalIndex),
    rating: (item) => <RatingBadge rating={item.rating} />,
    reliabilityScore: (item) => (
        <div className="flex items-center" aria-label={`Reliability: ${item.reliabilityScore}%`}>
            <div role="progressbar" aria-valuenow={item.reliabilityScore} aria-valuemin={0} aria-valuemax={100} className="w-16 bg-gray-200 rounded-full h-2.5">
                <div className="bg-blue-600 h-2.5 rounded-full" style={{ width: `${item.reliabilityScore}%` }}></div>
            </div>
            <span className="ml-2 font-medium text-xs">{item.reliabilityScore}%</span>
        </div>
    ),
    notes: (item) => <span className="block leading-tight">{item.notes}</span>,
  };

  // Helper to extract input details for comparison
  const getInputDetail = (item: any, fieldKey: string) => {
      const header = columnMapping[fieldKey];
      if (!header || header === 'N/A') return <span className="text-gray-400 italic">Not mapped</span>;
      const val = item[header];
      return val ? <span className="font-medium text-gray-900">{String(val)}</span> : <span className="text-gray-400 italic">Empty</span>;
  };

  // Helper to check if input data exists for conditional rendering
  const hasInputData = (item: any, fieldKey: string) => {
      const header = columnMapping[fieldKey];
      if (!header || header === 'N/A') return false;
      const val = item[header];
      return val !== undefined && val !== null && String(val).trim() !== '';
  };

  // Parse KDE string for display in comparison grid
  const parseMatchedKDE = (kdeString: string) => {
      if (!kdeString || kdeString === 'N/A') return { species: 'N/A', location: 'N/A', method: 'N/A' };
      const parts = kdeString.split(' | ');
      if (parts.length >= 3) {
          return {
              species: parts[0],
              location: parts[1],
              method: parts.slice(2).join(' | ')
          };
      }
      return { species: kdeString, location: '-', method: '-' };
  };


  return (
    <div className="w-full bg-white p-6 md:p-8 rounded-lg shadow-lg border border-gray-200 relative">
      <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center mb-6 gap-4">
        <div className="flex-grow">
          <h2 id="results-heading" className="text-2xl font-bold text-gray-800">Analysis Results</h2>
          <p className="text-sm text-gray-500 mt-1">Tip: Click a Unique ID to expand the row and compare details.</p>
          {filterTitle && (
            <div className="flex items-center gap-3 mt-2">
                <p className="text-sm text-gray-600">
                    Showing data for: <span className="font-semibold bg-blue-100 text-blue-800 px-2 py-1 rounded-md">{filterTitle}</span>
                </p>
                <button 
                    onClick={onClearFilter}
                    className="text-sm text-blue-600 hover:underline"
                >
                    Clear Filter
                </button>
            </div>
          )}
          <div className="mt-4 flex items-center gap-4">
            <div className="relative flex-grow max-w-sm">
                <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
                    <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5 text-gray-400" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" />
                    </svg>
                </div>
                <input
                    type="search"
                    id="table-search"
                    aria-label="Search results"
                    placeholder={`Search in ${results.length} results...`}
                    value={searchTerm}
                    onChange={(e) => setSearchTerm(e.target.value)}
                    className="block w-full pl-10 pr-3 py-2 border border-gray-300 rounded-md leading-5 bg-white placeholder-gray-500 focus:outline-none focus:placeholder-gray-400 focus:ring-1 focus:ring-blue-500 focus:border-blue-500 sm:text-sm"
                />
            </div>
            {searchTerm && (
                <button
                    onClick={() => setSearchTerm('')}
                    className="text-sm text-blue-600 hover:underline"
                >
                    Clear Search
                </button>
            )}
          </div>
        </div>
        <div className="flex items-center gap-4 flex-shrink-0">
          <ColumnToggler 
            allColumns={allColumns}
            visibleColumns={visibleColumns}
            onVisibilityChange={onVisibleColumnsChange}
          />
          <button
            onClick={onExport}
            className="flex items-center gap-2 px-4 py-2 text-sm font-semibold text-white bg-green-600 rounded-md hover:bg-green-700 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-green-600 transition-colors duration-200"
          >
            <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth="2">
                <path strokeLinecap="round" strokeLinejoin="round" d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-4l-4 4m0 0l-4-4m4 4V4" />
            </svg>
            Export Full Dataset (CSV)
          </button>
        </div>
      </div>

      {/* Top Scrollbar */}
      <div 
        ref={topScrollRef}
        className="overflow-x-auto w-full mb-1"
        style={{ height: '12px' }}
      >
        <div style={{ width: scrollWidth, height: '1px' }}></div>
      </div>

      <div 
        ref={tableContainerRef}
        className="overflow-x-auto max-h-[70vh]" // Constrain height for sticky header
      >
        {filteredAndSortedResults.length > 0 ? (
            <table className="min-w-full divide-y divide-gray-200 table-fixed" aria-labelledby="results-heading">
            {/* Sticky Header */}
            <thead className="bg-gray-100 sticky top-0 z-40 shadow-sm">
                <tr>
                {visibleOriginalHeaders.map((header) => (
                    <th 
                        key={header} 
                        scope="col" 
                        className="px-2 py-2 text-left text-xs font-bold text-gray-600 uppercase tracking-wider relative group bg-gray-100 align-bottom border-b border-gray-200"
                        style={{ width: columnWidths[header] ? `${columnWidths[header]}px` : undefined }}
                        aria-sort={sortConfig?.key === header ? sortConfig.direction : 'none'}
                    >
                    <button onClick={() => requestSort(header)} className="flex items-end w-full h-full">
                        <span className="whitespace-normal break-words leading-tight">{header}</span>
                        <SortIcon direction={sortConfig?.key === header ? sortConfig.direction : null} />
                    </button>
                    <div
                        onMouseDown={(e) => handleMouseDown(e, header)}
                        aria-hidden="true"
                        className="absolute top-0 right-0 h-full w-2 cursor-col-resize hover:bg-blue-200"
                    />
                    </th>
                ))}
                {visibleAddedHeaders.map((header) => (
                    <th 
                        key={header.key} 
                        scope="col" 
                        className="px-2 py-2 text-left text-xs font-bold text-blue-800 bg-blue-100 uppercase tracking-wider relative group align-bottom border-b border-blue-200"
                        style={{ 
                            width: columnWidths[header.key] ? `${columnWidths[header.key]}px` : undefined,
                            position: 'sticky',
                            right: stickyOffsets[header.key],
                            zIndex: 30, // Higher than row content
                            boxShadow: header.key === 'uniqueId' ? '-4px 0 8px -2px rgba(0,0,0,0.1)' : 'none',
                            borderLeft: header.key === 'uniqueId' ? '1px solid #d1d5db' : undefined
                        }}
                        aria-sort={sortConfig?.key === header.key ? sortConfig.direction : 'none'}
                    >
                    <button onClick={() => requestSort(header.key)} className="flex items-end w-full h-full">
                        <span className="whitespace-normal break-words leading-tight">{header.title}</span>
                        <SortIcon direction={sortConfig?.key === header.key ? sortConfig.direction : null} />
                    </button>
                    <div
                        onMouseDown={(e) => handleMouseDown(e, header.key)}
                        aria-hidden="true"
                        className="absolute top-0 right-0 h-full w-2 cursor-col-resize hover:bg-blue-300"
                    />
                    </th>
                ))}
                </tr>
            </thead>
            <tbody className="bg-white divide-y divide-gray-200">
                {filteredAndSortedResults.map((item, index) => {
                    const isExpanded = expandedRowIndex === item._originalIndex;
                    const matchDetails = parseMatchedKDE(item.matchedKDEs);

                    return (
                        <React.Fragment key={index}>
                            <tr className={`${isExpanded ? 'bg-blue-50' : 'hover:bg-gray-50'}`}>
                                {visibleOriginalHeaders.map((header) => (
                                <td key={`${header}-${index}`} className="px-2 py-2 text-xs text-gray-700 break-words align-top leading-tight">
                                    {item[header]}
                                </td>
                                ))}
                                {visibleAddedHeaders.map((header) => (
                                    <td 
                                        key={`${header.key}-${index}`} 
                                        className="px-2 py-2 text-xs text-gray-700 align-top leading-tight bg-blue-50"
                                        style={{
                                            position: 'sticky',
                                            right: stickyOffsets[header.key],
                                            zIndex: 20,
                                            boxShadow: header.key === 'uniqueId' ? '-4px 0 8px -2px rgba(0,0,0,0.1)' : 'none',
                                            borderLeft: header.key === 'uniqueId' ? '1px solid #d1d5db' : undefined
                                        }}
                                    >
                                        {addedColumnRenderers[header.key](item, item._originalIndex)}
                                    </td>
                                ))}
                            </tr>
                            {isExpanded && (
                                <tr className="bg-slate-100 shadow-inner">
                                    <td 
                                        colSpan={totalColSpan} 
                                        className="px-4 py-6"
                                        style={{
                                            position: 'sticky',
                                            left: 0,
                                            zIndex: 10
                                        }}
                                    >
                                        <div className="bg-white rounded-lg shadow-sm border border-gray-200 overflow-hidden max-w-5xl mx-auto">
                                            {/* Header */}
                                            <div className="bg-gray-50 px-6 py-3 border-b border-gray-200 flex justify-between items-center">
                                                <h4 className="font-bold text-gray-700 text-sm uppercase tracking-wide">Match Analysis & Comparison</h4>
                                                <div className="text-xs text-gray-500">
                                                    Comparing row {index + 1}
                                                </div>
                                            </div>

                                            {/* Comparison Grid */}
                                            <div className="grid grid-cols-1 md:grid-cols-12 text-sm">
                                                {/* Column Headers (Visible on MD+) */}
                                                <div className="hidden md:contents">
                                                    <div className="col-span-12 grid grid-cols-12 border-b border-gray-100 bg-gray-50/50 py-2 px-6 font-semibold text-gray-500 text-xs uppercase">
                                                        <div className="col-span-2">Attribute</div>
                                                        <div className="col-span-5 border-l border-gray-200 pl-4">Your Input (Product Details)</div>
                                                        <div className="col-span-5 border-l border-gray-200 pl-4 text-blue-700">Seafood Watch Match</div>
                                                    </div>
                                                </div>

                                                 {/* Row: Wild or Farmed */}
                                                 {hasInputData(item, 'Wild or Farmed') && (
                                                    <div className="col-span-12 grid grid-cols-1 md:grid-cols-12 border-b border-gray-100 py-3 px-6 hover:bg-gray-50 items-center">
                                                        <div className="md:col-span-2 font-medium text-gray-600 text-xs uppercase md:text-sm md:normal-case md:text-gray-600 mb-1 md:mb-0">Wild or Farmed</div>
                                                        <div className="md:col-span-5 md:border-l border-gray-200 md:pl-4 mb-2 md:mb-0">{getInputDetail(item, 'Wild or Farmed')}</div>
                                                        <div className="md:col-span-5 md:border-l border-gray-200 md:pl-4 text-gray-400 italic text-xs">-</div>
                                                    </div>
                                                 )}

                                                {/* Row: Species */}
                                                {hasInputData(item, 'Common name') && (
                                                    <div className="col-span-12 grid grid-cols-1 md:grid-cols-12 border-b border-gray-100 py-3 px-6 hover:bg-gray-50 items-center">
                                                        <div className="md:col-span-2 font-medium text-gray-600 text-xs uppercase md:text-sm md:normal-case md:text-gray-600 mb-1 md:mb-0">Species</div>
                                                        <div className="md:col-span-5 md:border-l border-gray-200 md:pl-4 mb-2 md:mb-0">{getInputDetail(item, 'Common name')}</div>
                                                        <div className="md:col-span-5 md:border-l border-gray-200 md:pl-4 font-medium text-gray-800">{matchDetails.species}</div>
                                                    </div>
                                                )}

                                                {/* Row: Country */}
                                                {hasInputData(item, 'Source country') && (
                                                    <div className="col-span-12 grid grid-cols-1 md:grid-cols-12 border-b border-gray-100 py-3 px-6 hover:bg-gray-50 items-center">
                                                        <div className="md:col-span-2 font-medium text-gray-600 text-xs uppercase md:text-sm md:normal-case md:text-gray-600 mb-1 md:mb-0">Country</div>
                                                        <div className="md:col-span-5 md:border-l border-gray-200 md:pl-4 mb-2 md:mb-0">{getInputDetail(item, 'Source country')}</div>
                                                        <div className="md:col-span-5 md:border-l border-gray-200 md:pl-4 text-gray-800">{matchDetails.location}</div>
                                                    </div>
                                                )}

                                                 {/* Row: Body of Water */}
                                                 {hasInputData(item, 'Body of Water') && (
                                                    <div className="col-span-12 grid grid-cols-1 md:grid-cols-12 border-b border-gray-100 py-3 px-6 hover:bg-gray-50 items-center">
                                                        <div className="md:col-span-2 font-medium text-gray-600 text-xs uppercase md:text-sm md:normal-case md:text-gray-600 mb-1 md:mb-0">Body of Water</div>
                                                        <div className="md:col-span-5 md:border-l border-gray-200 md:pl-4 mb-2 md:mb-0">{getInputDetail(item, 'Body of Water')}</div>
                                                        <div className="md:col-span-5 md:border-l border-gray-200 md:pl-4 text-gray-400 italic text-xs">-</div>
                                                    </div>
                                                 )}

                                                {/* Row: Method */}
                                                {hasInputData(item, 'Production Method') && (
                                                    <div className="col-span-12 grid grid-cols-1 md:grid-cols-12 border-b border-gray-100 py-3 px-6 hover:bg-gray-50 items-center">
                                                        <div className="md:col-span-2 font-medium text-gray-600 text-xs uppercase md:text-sm md:normal-case md:text-gray-600 mb-1 md:mb-0">Method</div>
                                                        <div className="md:col-span-5 md:border-l border-gray-200 md:pl-4 mb-2 md:mb-0">{getInputDetail(item, 'Production Method')}</div>
                                                        <div className="md:col-span-5 md:border-l border-gray-200 md:pl-4 text-gray-800">{matchDetails.method}</div>
                                                    </div>
                                                )}

                                                {/* Row: Rating & Confidence */}
                                                <div className="col-span-12 grid grid-cols-1 md:grid-cols-12 py-4 px-6 bg-blue-50/30 items-center">
                                                    <div className="md:col-span-2 font-medium text-gray-600 text-xs uppercase md:text-sm md:normal-case md:text-gray-600 mb-1 md:mb-0">Result</div>
                                                    <div className="md:col-span-5 md:border-l border-gray-200 md:pl-4 flex items-center gap-2 mb-2 md:mb-0">
                                                        {/* Wild/Farmed moved to separate row above */}
                                                    </div>
                                                    <div className="md:col-span-5 md:border-l border-gray-200 md:pl-4">
                                                        <div className="flex flex-wrap items-center gap-4">
                                                            <div className="flex items-center gap-2 bg-white px-2 py-1 rounded border border-gray-200">
                                                                    <span className="text-gray-500 text-xs uppercase font-bold">Rating:</span>
                                                                    <RatingBadge rating={item.rating} />
                                                            </div>
                                                            <div className="flex items-center gap-2 bg-white px-2 py-1 rounded border border-gray-200">
                                                                    <span className="text-gray-500 text-xs uppercase font-bold">Reliability:</span>
                                                                    <span className={`font-bold ${item.reliabilityScore > 80 ? 'text-green-600' : 'text-yellow-600'}`}>{item.reliabilityScore}%</span>
                                                            </div>
                                                        </div>
                                                    </div>
                                                </div>
                                            </div>

                                            {/* Footer: Edit ID */}
                                            <div className="bg-gray-50 px-6 py-4 border-t border-gray-200 flex flex-col md:flex-row items-start md:items-center gap-4">
                                                <div className="flex-grow">
                                                    <label htmlFor={`edit-id-${index}`} className="block text-xs font-bold text-gray-700 mb-1">
                                                        Is this match incorrect? Manually update the Unique ID:
                                                    </label>
                                                    <div className="flex gap-2 max-w-md">
                                                        <input 
                                                            id={`edit-id-${index}`}
                                                            type="text" 
                                                            value={editValue} 
                                                            onChange={(e) => setEditValue(e.target.value)}
                                                            className="flex-grow text-sm border border-gray-300 rounded px-3 py-1.5 focus:outline-none focus:ring-1 focus:ring-blue-500 shadow-sm"
                                                            placeholder="Enter official Seafood Watch ID..."
                                                        />
                                                        <button 
                                                            onClick={() => handleSubmitEdit(item._originalIndex)}
                                                            className="bg-blue-600 text-white text-xs px-4 py-1.5 rounded font-semibold hover:bg-blue-700 focus:outline-none focus:ring-2 focus:ring-offset-1 focus:ring-blue-600 disabled:opacity-50 disabled:cursor-not-allowed shadow-sm"
                                                            disabled={!editValue || editValue === item.uniqueId}
                                                        >
                                                            Update ID
                                                        </button>
                                                    </div>
                                                </div>
                                                <div className="text-xs text-gray-500 italic max-w-xs">
                                                    Tip: Updating the ID will force the system to use the official details associated with that ID.
                                                </div>
                                            </div>
                                        </div>
                                    </td>
                                </tr>
                            )}
                        </React.Fragment>
                    );
                })}
            </tbody>
            </table>
        ) : (
            <p className="text-center text-gray-500 my-8 py-4">
                No results found for your search: "{searchTerm}".
            </p>
        )}
      </div>
    </div>
  );
};

export default ResultsTable;

import React, { useState, useCallback, useRef, useEffect, useMemo } from 'react';
import { SeafoodResultItem } from '../types';
import RatingBadge from './RatingBadge';
import ColumnToggler from './ColumnToggler';

interface ResultsTableProps {
  results: any[];
  originalHeaders: string[];
  columnMapping?: Record<string, string>;
  onExport: () => void;
  filterTitle?: string;
  onClearFilter?: () => void;
  visibleColumns: Set<string>;
  onVisibleColumnsChange: (newVisible: Set<string>) => void;
  onUpdateResult?: (index: number, newUniqueId: string) => Promise<void>;
}

type SortDirection = 'ascending' | 'descending';

const SortIcon: React.FC<{ direction: SortDirection | null }> = ({ direction }) => {
    if (!direction) return null;
    return (
      <svg
        className="w-4 h-4 ml-1 inline-block text-gray-500 flex-shrink-0"
        aria-hidden="true"
        fill="currentColor"
        viewBox="0 0 20 20"
        xmlns="http://www.w3.org/2000/svg"
      >
        {direction === 'descending' ? (
          <path
            fillRule="evenodd"
            d="M5.293 7.293a1 1 0 011.414 0L10 10.586l3.293-3.293a1 1 0 111.414 1.414l-4 4a1 1 0 01-1.414 0l-4-4a1 1 0 010-1.414z"
            clipRule="evenodd"
          />
        ) : (
          <path
            fillRule="evenodd"
            d="M14.707 12.707a1 1 0 01-1.414 0L10 9.414l-3.293 3.293a1 1 0 01-1.414-1.414l4-4a1 1 0 011.414 0l4 4a1 1 0 010 1.414z"
            clipRule="evenodd"
          />
        )}
      </svg>
    );
};


const ResultsTable: React.FC<ResultsTableProps> = ({ 
  results, 
  originalHeaders,
  columnMapping = {},
  onExport, 
  filterTitle, 
  onClearFilter,
  visibleColumns, 
  onVisibleColumnsChange,
  onUpdateResult
}) => {
  const [columnWidths, setColumnWidths] = useState<Record<string, number>>({});
  const isResizing = useRef<string | null>(null);
  const [sortConfig, setSortConfig] = useState<{ key: string; direction: SortDirection } | null>(null);
  const [searchTerm, setSearchTerm] = useState('');

  // Expanded Row State (Accordion)
  const [expandedRowIndex, setExpandedRowIndex] = useState<number | null>(null);
  // Temporary state for the input field inside the expanded view
  const [editValue, setEditValue] = useState<string>('');


  // Refs for synced scrolling
  const tableContainerRef = useRef<HTMLDivElement>(null);
  const topScrollRef = useRef<HTMLDivElement>(null);
  const [scrollWidth, setScrollWidth] = useState(0);

  const sortedResults = useMemo(() => {
    // Add original index to items to track them after sorting
    const itemsWithIndex = results.map((item, index) => ({ ...item, _originalIndex: index }));

    if (!sortConfig) {
      return itemsWithIndex;
    }
    const sortableItems = [...itemsWithIndex];
    sortableItems.sort((a, b) => {
        const aVal = a[sortConfig.key];
        const bVal = b[sortConfig.key];

        if (aVal == null) return 1;
        if (bVal == null) return -1;

        if (typeof aVal === 'number' && typeof bVal === 'number') {
            return sortConfig.direction === 'ascending' ? aVal - bVal : bVal - aVal;
        }

        const aStr = String(aVal);
        const bStr = String(bVal);
        const comparison = aStr.localeCompare(bStr, undefined, { numeric: true, sensitivity: 'base' });

        return sortConfig.direction === 'ascending' ? comparison : -comparison;
      });

    return sortableItems;
  }, [results, sortConfig]);

  const filteredAndSortedResults = useMemo(() => {
    if (!searchTerm) {
      return sortedResults;
    }
    const lowercasedFilter = searchTerm.toLowerCase();
    return sortedResults.filter(item => {
       const { _originalIndex, isUpdating, ...searchableItem } = item;
      return Object.values(searchableItem).some(value =>
        String(value).toLowerCase().includes(lowercasedFilter)
      );
    });
  }, [sortedResults, searchTerm]);

  // Sync scrollbars
  useEffect(() => {
    const syncScroll = (source: 'top' | 'bottom') => {
      const top = topScrollRef.current;
      const bottom = tableContainerRef.current;
      if (!top || !bottom) return;

      if (source === 'top') {
        bottom.scrollLeft = top.scrollLeft;
      } else {
        top.scrollLeft = bottom.scrollLeft;
      }
    };

    const top = topScrollRef.current;
    const bottom = tableContainerRef.current;

    if (top && bottom) {
      const handleTopScroll = () => syncScroll('top');
      const handleBottomScroll = () => syncScroll('bottom');

      top.addEventListener('scroll', handleTopScroll);
      bottom.addEventListener('scroll', handleBottomScroll);

      return () => {
        top.removeEventListener('scroll', handleTopScroll);
        bottom.removeEventListener('scroll', handleBottomScroll);
      };
    }
  }, []);

  // Update scroll width when data or columns change
  useEffect(() => {
    if (tableContainerRef.current) {
      setScrollWidth(tableContainerRef.current.scrollWidth);
    }
  }, [visibleColumns, filteredAndSortedResults, columnWidths]);


  const requestSort = (key: string) => {
    let direction: SortDirection = 'ascending';
    if (sortConfig && sortConfig.key === key && sortConfig.direction === 'ascending') {
      direction = 'descending';
    }
    setSortConfig({ key, direction });
  };

  const toggleRow = (e: React.MouseEvent, rowIndex: number, currentId: string) => {
      e.stopPropagation();
      if (expandedRowIndex === rowIndex) {
          setExpandedRowIndex(null);
          setEditValue('');
      } else {
          setExpandedRowIndex(rowIndex);
          setEditValue(currentId);
      }
  };

  const handleSubmitEdit = async (index: number) => {
      if (onUpdateResult && editValue) {
          await onUpdateResult(index, editValue);
          // Don't close row automatically, user might want to see update.
      }
  };


  if (!results.length) {
    return <p className="text-center text-gray-500 my-8">
        {filterTitle ? `No data matches the filter "${filterTitle}".` : 'No data to display.'}
    </p>;
  }

  const addedHeaders = [
    { key: 'uniqueId', title: 'Unique ID' },
    { key: 'rating', title: 'Rating' },
    { key: 'reliabilityScore', title: 'Reliability' },
    { key: 'notes', title: 'Notes' },
  ];

  const allColumns = [
    ...originalHeaders.map(h => ({ key: h, title: h })),
    ...addedHeaders.map(h => ({ key: h.key, title: h.title }))
  ];

  const visibleOriginalHeaders = originalHeaders.filter(h => visibleColumns.has(h));
  const visibleAddedHeaders = addedHeaders.filter(h => visibleColumns.has(h.key));
  const totalColSpan = visibleOriginalHeaders.length + visibleAddedHeaders.length;

  // Calculate sticky offsets for the added headers (they will be stuck to the right)
  const stickyOffsets = useMemo(() => {
      const offsets: Record<string, number> = {};
      let currentRight = 0;
      // Reverse order because right:0 is the last column (Notes)
      [...visibleAddedHeaders].reverse().forEach(h => {
          offsets[h.key] = currentRight;
          currentRight += (columnWidths[h.key] || (h.key === 'notes' ? 450 : (h.key === 'uniqueId' ? 120 : 90)));
      });
      return offsets;
  }, [visibleAddedHeaders, columnWidths]);


  useEffect(() => {
    setColumnWidths(prevWidths => {
        const newWidths = { ...prevWidths };
        visibleOriginalHeaders.forEach(h => {
            if (!newWidths[h]) newWidths[h] = 100;
        });
        visibleAddedHeaders.forEach(h => {
            if (!newWidths[h.key]) {
                if (h.key === 'notes') newWidths[h.key] = 450;
                else if (h.key === 'reliabilityScore') newWidths[h.key] = 90;
                else if (h.key === 'uniqueId') newWidths[h.key] = 120;
                else newWidths[h.key] = 90;
            }
        });
        return newWidths;
    });
  }, [visibleOriginalHeaders, visibleAddedHeaders]);

  const handleMouseDown = useCallback((e: React.MouseEvent<HTMLDivElement>, headerKey: string) => {
    isResizing.current = headerKey;
    const startX = e.clientX;
    const startWidth = columnWidths[headerKey] || 0;

    const handleMouseMove = (moveEvent: MouseEvent) => {
      if (isResizing.current !== headerKey) return;
      const width = startWidth + (moveEvent.clientX - startX);
      if (width > 50) { // Min width
        setColumnWidths(prev => ({ ...prev, [headerKey]: width }));
      }
    };

    const handleMouseUp = () => {
      isResizing.current = null;
      window.removeEventListener('mousemove', handleMouseMove);
      window.removeEventListener('mouseup', handleMouseUp);
      document.body.style.cursor = 'default';
      document.body.style.userSelect = 'auto';
    };

    window.addEventListener('mousemove', handleMouseMove);
    window.addEventListener('mouseup', handleMouseUp);
    e.preventDefault();
    document.body.style.cursor = 'col-resize';
    document.body.style.userSelect = 'none';
  }, [columnWidths]);

  const renderUniqueId = (item: any, originalIndex: number) => {
    if (item.isUpdating) {
        return (
           <div className="flex items-center space-x-2">
               <div className="w-3 h-3 border-2 border-blue-600 border-dashed rounded-full animate-spin"></div>
               <span className="text-xs text-gray-500">Updating...</span>
           </div>
        );
    }

    const isExpanded = expandedRowIndex === originalIndex;

    return (
      <button 
          onClick={(e) => toggleRow(e, originalIndex, item.uniqueId)}
          className={`flex items-center space-x-2 px-2 py-1 rounded transition-colors w-full text-left font-mono text-xs border ${isExpanded ? 'bg-blue-600 text-white border-blue-600' : 'text-blue-700 hover:bg-blue-100 border-transparent hover:border-blue-200'}`}
          title="Click to view details & edit"
          aria-expanded={isExpanded}
      >
          <span>{item.uniqueId}</span>
          <svg 
            xmlns="http://www.w3.org/2000/svg" 
            className={`h-3 w-3 transition-transform duration-200 ${isExpanded ? 'rotate-180' : ''}`} 
            fill="none" 
            viewBox="0 0 24 24" 
            stroke="currentColor"
          >
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 9l-7 7-7-7" />
          </svg>
      </button>
    );
  };

  const addedColumnRenderers: Record<string, (item: any, originalIndex: number) => React.ReactNode> = {
    uniqueId: (item, originalIndex) => renderUniqueId(item, originalIndex),
    rating: (item) => <RatingBadge rating={item.rating} />,
    reliabilityScore: (item) => (
        <div className="flex items-center" aria-label={`Reliability: ${item.reliabilityScore}%`}>
            <div role="progressbar" aria-valuenow={item.reliabilityScore} aria-valuemin={0} aria-valuemax={100} className="w-16 bg-gray-200 rounded-full h-2.5">
                <div className="bg-blue-600 h-2.5 rounded-full" style={{ width: `${item.reliabilityScore}%` }}></div>
            </div>
            <span className="ml-2 font-medium text-xs">{item.reliabilityScore}%</span>
        </div>
    ),
    notes: (item) => <span className="block leading-tight">{item.notes}</span>,
  };

  // Helper to extract input details for comparison
  const getInputDetail = (item: any, fieldKey: string) => {
      const header = columnMapping[fieldKey];
      if (!header || header === 'N/A') return <span className="text-gray-400 italic">Not mapped</span>;
      const val = item[header];
      return val ? <span className="font-medium text-gray-900">{String(val)}</span> : <span className="text-gray-400 italic">Empty</span>;
  };

  // Helper to check if input data exists for conditional rendering
  const hasInputData = (item: any, fieldKey: string) => {
      const header = columnMapping[fieldKey];
      if (!header || header === 'N/A') return false;
      const val = item[header];
      return val !== undefined && val !== null && String(val).trim() !== '';
  };

  // Parse KDE string for display in comparison grid
  const parseMatchedKDE = (kdeString: string) => {
      if (!kdeString || kdeString === 'N/A') return { species: 'N/A', location: 'N/A', method: 'N/A' };
      const parts = kdeString.split(' | ');
      if (parts.length >= 3) {
          return {
              species: parts[0],
              location: parts[1],
              method: parts.slice(2).join(' | ')
          };
      }
      return { species: kdeString, location: '-', method: '-' };
  };


  return (
    <div className="w-full bg-white p-6 md:p-8 rounded-lg shadow-lg border border-gray-200 relative">
      <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center mb-6 gap-4">
        <div className="flex-grow">
          <h2 id="results-heading" className="text-2xl font-bold text-gray-800">Analysis Results</h2>
          <p className="text-sm text-gray-500 mt-1">Tip: Click a Unique ID to expand the row and compare details.</p>
          {filterTitle && (
            <div className="flex items-center gap-3 mt-2">
                <p className="text-sm text-gray-600">
                    Showing data for: <span className="font-semibold bg-blue-100 text-blue-800 px-2 py-1 rounded-md">{filterTitle}</span>
                </p>
                <button 
                    onClick={onClearFilter}
                    className="text-sm text-blue-600 hover:underline"
                >
                    Clear Filter
                </button>
            </div>
          )}
          <div className="mt-4 flex items-center gap-4">
            <div className="relative flex-grow max-w-sm">
                <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
                    <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5 text-gray-400" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" />
                    </svg>
                </div>
                <input
                    type="search"
                    id="table-search"
                    aria-label="Search results"
                    placeholder={`Search in ${results.length} results...`}
                    value={searchTerm}
                    onChange={(e) => setSearchTerm(e.target.value)}
                    className="block w-full pl-10 pr-3 py-2 border border-gray-300 rounded-md leading-5 bg-white placeholder-gray-500 focus:outline-none focus:placeholder-gray-400 focus:ring-1 focus:ring-blue-500 focus:border-blue-500 sm:text-sm"
                />
            </div>
            {searchTerm && (
                <button
                    onClick={() => setSearchTerm('')}
                    className="text-sm text-blue-600 hover:underline"
                >
                    Clear Search
                </button>
            )}
          </div>
        </div>
        <div className="flex items-center gap-4 flex-shrink-0">
          <ColumnToggler 
            allColumns={allColumns}
            visibleColumns={visibleColumns}
            onVisibilityChange={onVisibleColumnsChange}
          />
          <button
            onClick={onExport}
            className="flex items-center gap-2 px-4 py-2 text-sm font-semibold text-white bg-green-600 rounded-md hover:bg-green-700 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-green-600 transition-colors duration-200"
          >
            <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth="2">
                <path strokeLinecap="round" strokeLinejoin="round" d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-4l-4 4m0 0l-4-4m4 4V4" />
            </svg>
            Export Full Dataset (CSV)
          </button>
        </div>
      </div>

      {/* Top Scrollbar */}
      <div 
        ref={topScrollRef}
        className="overflow-x-auto w-full mb-1"
        style={{ height: '12px' }}
      >
        <div style={{ width: scrollWidth, height: '1px' }}></div>
      </div>

      <div 
        ref={tableContainerRef}
        className="overflow-x-auto max-h-[70vh] border border-gray-200 rounded-md shadow-sm" // Added border/shadow
      >
        {filteredAndSortedResults.length > 0 ? (
            <table className="min-w-full divide-y divide-gray-200 table-fixed" aria-labelledby="results-heading">
            {/* Sticky Header */}
            <thead className="bg-gray-100 sticky top-0 z-40 shadow-sm">
                <tr>
                {visibleOriginalHeaders.map((header) => (
                    <th 
                        key={header} 
                        scope="col" 
                        className="px-2 py-2 text-left text-xs font-bold text-gray-600 uppercase tracking-wider relative group bg-gray-100 align-bottom border-b border-gray-200"
                        style={{ width: columnWidths[header] ? `${columnWidths[header]}px` : undefined }}
                        aria-sort={sortConfig?.key === header ? sortConfig.direction : 'none'}
                    >
                    <button onClick={() => requestSort(header)} className="flex items-end w-full h-full">
                        <span className="whitespace-normal break-words leading-tight">{header}</span>
                        <SortIcon direction={sortConfig?.key === header ? sortConfig.direction : null} />
                    </button>
                    <div
                        onMouseDown={(e) => handleMouseDown(e, header)}
                        aria-hidden="true"
                        className="absolute top-0 right-0 h-full w-2 cursor-col-resize hover:bg-blue-200"
                    />
                    </th>
                ))}
                {visibleAddedHeaders.map((header) => (
                    <th 
                        key={header.key} 
                        scope="col" 
