export default ResultsTable;

import { GoogleGenAI, Type } from "@google/genai";
import { SeafoodInputItem, SeafoodResultItem, Rating } from "../types";
import { getSeafoodById, findCandidates } from "./referenceDatabase";

// This declaration is necessary because the library is loaded from a script tag in index.html
declare var process: {
  env: {
    API_KEY: string;
  };
};

// Schema for a single analysis result
const singleItemSchema = {
  type: Type.OBJECT,
  properties: {
    uniqueId: {
      type: Type.STRING,
      description: "The official Seafood Watch Recommendation ID selected from the provided candidates. If no candidate matches well, use 'N/A'.",
    },
    officialKDEs: {
      type: Type.STRING,
      description: "The official description (Species | Location | Method) corresponding to the selected ID.",
    },
    rating: {
      type: Type.STRING,
      enum: [Rating.BestChoice, Rating.GoodAlternative, Rating.Avoid, Rating.Certified, Rating.NA],
      description: "The rating associated with the selected candidate.",
    },
    reliabilityScore: {
      type: Type.NUMBER,
      description: "Confidence score (0-100). High if the input closely matches the selected candidate.",
    },
    notes: {
      type: Type.STRING,
      description: "Explain why this candidate was chosen or why 'N/A' was returned.",
    },
  },
  required: ["uniqueId", "officialKDEs", "rating", "reliabilityScore", "notes"],
};

// Schema for the batched response, which is an array of single items
const responseSchema = {
    type: Type.ARRAY,
    items: singleItemSchema
};

const systemInstruction = `You are a strict data matching engine for the Seafood Watch program. 

TASK:
For each seafood product provided, you will receive a list of "Candidates" from the official database. 
Your ONLY job is to select the best matching Candidate ID for the product.

RULES:
1. **Selection Only**: You must choose one of the IDs provided in the "Candidates" list. Do NOT invent new IDs.
2. **Fallback**: If the product is "Certified" (MSC/ASC), or if NONE of the candidates are a reasonable match for the species and country, return "N/A" for the uniqueId.
3. **Data Integrity**: Use the exact Rating and Official Description from the selected candidate. Do not modify them.

OUTPUT:
Return a JSON array where each object corresponds to the input product in the exact same order.`;

type AnalysisResult = Pick<SeafoodResultItem, 'uniqueId' | 'matchedKDEs' | 'rating' | 'reliabilityScore' | 'notes'>;

// drastically reduced batch size to avoid token limits on free/low tiers
const BATCH_SIZE = 3; 
const API_DELAY_MS = 15000; // Increased delay between batches to 15 seconds to stay safe for free-tier RPM limits

interface BatchItemWithCandidates {
    index: number;
    data: SeafoodInputItem;
    candidates: { id: string; desc: string; rating: string }[];
}

// Helper to check for 429 status in error objects
function isRateLimitError(error: any): boolean {
    const errString = JSON.stringify(error).toUpperCase();
    return errString.includes('429') || errString.includes('RESOURCE_EXHAUSTED') || errString.includes('RATE_LIMIT');
}

async function rateBatch(items: SeafoodInputItem[]): Promise<AnalysisResult[]> {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const totalRetries = 6;
    let retries = totalRetries;
    let delay = 15000; // Start with 15s delay for retries

    const failedResult: AnalysisResult = {
        uniqueId: "N/A",
        matchedKDEs: "Analysis Failed",
        rating: Rating.NA,
        reliabilityScore: 0,
        notes: "An error occurred during analysis.",
    };
    const rateLimitResult: AnalysisResult = {
        uniqueId: "N/A",
        matchedKDEs: "Rate Limit Exceeded",
        rating: Rating.NA,
        reliabilityScore: 0,
        notes: "Rate limit exceeded. Try a smaller file or wait a minute.",
    }

    // Pre-processing: Find candidates for each item locally
    const batchWithCandidates: BatchItemWithCandidates[] = items.map((item, index) => {
        const candidates = findCandidates({
            species: String(item['Common name'] || ''),
            country: String(item['Source country'] || ''),
            method: String(item['Production Method'] || ''),
            farmedWild: String(item['Wild or Farmed'] || '')
        }, 5); // Top 5 candidates

        return {
            index,
            data: item,
            candidates: candidates.map(c => ({
                id: c.record.UniqueID,
                desc: c.description,
                rating: c.record.RatingColor
            }))
        };
    });

    while (retries > 0) {
        try {
            const prompt = `Analyze these ${items.length} products. For each, pick the best ID from the provided Candidates.\n\n` + 
                JSON.stringify(batchWithCandidates, null, 2);

            const response = await ai.models.generateContent({
                model: 'gemini-2.5-flash',
                contents: prompt,
                config: {
                    systemInstruction: systemInstruction,
                    responseMimeType: "application/json",
                    responseSchema: responseSchema,
                    temperature: 0.0,
                },
            });

            const jsonText = response.text.trim();
            const results: any[] = JSON.parse(jsonText);

            if (!Array.isArray(results) || results.length !== items.length) {
                console.error(`API response mismatch: expected ${items.length} items, got ${results.length}.`);
                throw new Error(`API returned an incorrect number of items for the batch.`);
            }

            return results.map(result => {
                const uniqueId = result.uniqueId || "N/A";
                let matchedKDEs = result.officialKDEs || "N/A";
                let rating = result.rating || Rating.NA;

                if (uniqueId !== "N/A") {
                    const officialRecord = getSeafoodById(uniqueId);
                    if (officialRecord) {
                        matchedKDEs = officialRecord.matchedKDEs;
                        rating = officialRecord.rating;
                    } else {
                        return { ...failedResult, notes: "AI selected an invalid ID." };
                    }
                }

                return {
                    uniqueId,
                    matchedKDEs, 
                    rating,
                    reliabilityScore: result.reliabilityScore || 0,
                    notes: result.notes || "No notes provided.",
                };
            });

        } catch (error: any) {
            console.error("Error processing batch with Gemini:", error);

            if (isRateLimitError(error)) {
                retries--;
                if (retries === 0) {
                    return items.map(() => rateLimitResult);
                }
                const jitter = Math.random() * 5000;
                console.warn(`Rate limit hit. Retrying in ${Math.round((delay + jitter) / 1000)}s... (${retries} retries left)`);
                await new Promise(resolve => setTimeout(resolve, delay + jitter));
                delay *= 2; 
            } else {
                return items.map(() => failedResult);
            }
        }
    }

    return items.map(() => rateLimitResult);
}

export async function rateSeafoodData(
  data: SeafoodInputItem[],
  onProgress: (processed: number, total: number) => void,
  signal?: AbortSignal
): Promise<AnalysisResult[]> {
  const allResults: AnalysisResult[] = [];
  const total = data.length;

  const rateLimitNote = "Rate limit exceeded. Try a smaller file or wait a minute.";
  const processingStoppedNote = "Processing stopped due to API rate limits.";

  for (let i = 0; i < total; i += BATCH_SIZE) {
    if (signal?.aborted) {
        throw new DOMException('Analysis aborted by user', 'AbortError');
    }

    const batch = data.slice(i, i + BATCH_SIZE);
    const batchResults = await rateBatch(batch);
    allResults.push(...batchResults);

    const processedCount = allResults.length;
    onProgress(processedCount, total);

    const isRateLimited = batchResults.every(r => r.notes === rateLimitNote);
    if (isRateLimited) {
        console.warn("API rate limit hit. Aborting further processing.");

        const remainingCount = total - processedCount;
        if (remainingCount > 0) {
            const stoppedResult: AnalysisResult = {
                uniqueId: "N/A",
                matchedKDEs: "Aborted",
                rating: Rating.NA,
                reliabilityScore: 0,
                notes: processingStoppedNote,
            };
            for (let j = 0; j < remainingCount; j++) {
                allResults.push(stoppedResult);
            }
            onProgress(total, total);
        }
        break;
    }

    if (processedCount < total) {
      // Pause between batches to respect rate limits
      await new Promise(resolve => setTimeout(resolve, API_DELAY_MS));
    }
  }

  return allResults;
}

export async function updateAnalysisForId(
  item: SeafoodInputItem,
  newId: string
): Promise<AnalysisResult> {
    const officialRecord = getSeafoodById(newId);

    if (officialRecord) {
