};

// Renamed helper to avoid conflicts and improve clarity
function parseMatchedKDEs(kdeString: string) {
    if (!kdeString || kdeString === 'N/A') return { species: 'N/A', location: 'N/A', method: 'N/A' };
    const parts = kdeString.split(' | ');
    if (parts.length >= 3) {
        return {
            species: parts[0],
            location: parts[1],
            method: parts.slice(2).join(' | ')
        };
    }
    return { species: kdeString, location: '-', method: '-' };
}

export default ResultsTable;

import { GoogleGenAI, Type } from "@google/genai";
import { SeafoodInputItem, SeafoodResultItem, Rating } from "../types";
import { getSeafoodById, findCandidates } from "./referenceDatabase";

declare var process: {
  env: {
    API_KEY: string;
  };
};

const singleItemSchema = {
  type: Type.OBJECT,
  properties: {
    uniqueId: {
      type: Type.STRING,
      description: "The official ID from provided candidates. Use 'N/A' if no good match.",
    },
    officialKDEs: {
      type: Type.STRING,
      description: "Species | Location | Method string from the selected candidate.",
    },
    rating: {
      type: Type.STRING,
      enum: [Rating.BestChoice, Rating.GoodAlternative, Rating.Avoid, Rating.Certified, Rating.NA],
      description: "Rating color of the selected candidate.",
    },
    reliabilityScore: {
      type: Type.NUMBER,
      description: "Confidence (0-100).",
    },
    notes: {
      type: Type.STRING,
      description: "Brief reasoning.",
    },
  },
  required: ["uniqueId", "officialKDEs", "rating", "reliabilityScore", "notes"],
};

const responseSchema = {
    type: Type.ARRAY,
    items: singleItemSchema
};

const analysisSystemInstruction = `You are a strict data matching engine for Seafood Watch. Your task is to receive a list of seafood products and their corresponding official database candidates, then pick the best Candidate ID for each. 

Rules: 
1. Only use IDs from the provided 'candidates' list or 'N/A'. 
2. Match Species name, Country/Location, and Production Method as closely as possible. 
3. If the input specifies a Certification like MSC or ASC, prioritize 'N/A' as the UniqueID as it is handled via certification, not a specific recommendation ID.
4. Return a JSON array of results in the exact same order as the input items.`;

type AnalysisResult = Pick<SeafoodResultItem, 'uniqueId' | 'matchedKDEs' | 'rating' | 'reliabilityScore' | 'notes'>;

// PERFORMANCE CONFIGURATION
// Reduced batch size and increased concurrency to provide more frequent UI updates
const BATCH_SIZE = 5; 
const MAX_CONCURRENT_BATCHES = 4;
const API_DELAY_MS = 2500; 

interface BatchItemWithCandidates {
    index: number;
    data: SeafoodInputItem;
    candidates: { id: string; desc: string; rating: string }[];
}

function isRateLimitError(error: any): boolean {
    const errString = JSON.stringify(error).toUpperCase();
    return errString.includes('429') || errString.includes('RESOURCE_EXHAUSTED') || errString.includes('RATE_LIMIT');
}

function getRowSignature(item: SeafoodInputItem): string {
    return `${item['Common name']}|${item['Source country']}|${item['Production Method']}|${item['Wild or Farmed']}`.toLowerCase();
}

async function rateBatch(items: SeafoodInputItem[]): Promise<AnalysisResult[]> {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    let retries = 5;
    let delay = 5000;

    const failedResult: AnalysisResult = {
        uniqueId: "N/A",
        matchedKDEs: "Analysis Failed",
        rating: Rating.NA,
        reliabilityScore: 0,
        notes: "An error occurred during analysis.",
    };

    const batchWithCandidates: BatchItemWithCandidates[] = items.map((item, index) => {
        const candidates = findCandidates({
            species: String(item['Common name'] || ''),
            country: String(item['Source country'] || ''),
            method: String(item['Production Method'] || ''),
            farmedWild: String(item['Wild or Farmed'] || '')
        }, 5);

        return {
            index,
            data: item,
            candidates: candidates.map(c => ({
                id: c.record.UniqueID,
                desc: c.description,
                rating: c.record.RatingColor
            }))
        };
    });

    while (retries > 0) {
        try {
            const prompt = `Please match the following ${items.length} products to their best candidate IDs:\n${JSON.stringify(batchWithCandidates)}`;

            const response = await ai.models.generateContent({
                model: 'gemini-3-flash-preview',
                contents: prompt,
                config: {
                    systemInstruction: analysisSystemInstruction,
                    responseMimeType: "application/json",
                    responseSchema: responseSchema,
                    temperature: 0.0,
                },
            });

            const results: any[] = JSON.parse(response.text.trim());

            return results.map(result => {
                const uniqueId = result.uniqueId || "N/A";
                let matchedKDEs = result.officialKDEs || "N/A";
                let rating = result.rating || Rating.NA;

                if (uniqueId !== "N/A") {
                    const officialRecord = getSeafoodById(uniqueId);
                    if (officialRecord) {
                        matchedKDEs = officialRecord.matchedKDEs;
                        rating = officialRecord.rating;
                    }
                }

                return {
                    uniqueId,
                    matchedKDEs, 
                    rating,
                    reliabilityScore: result.reliabilityScore || 0,
                    notes: result.notes || "Analyzed by AI.",
                };
            });

        } catch (error: any) {
            if (isRateLimitError(error) && --retries > 0) {
                await new Promise(resolve => setTimeout(resolve, delay + Math.random() * 2000));
                delay *= 1.5;
                continue;
            }
            return items.map(() => failedResult);
        }
    }
    return items.map(() => failedResult);
}

export async function rateSeafoodData(
  data: SeafoodInputItem[],
  onProgress: (processed: number, total: number) => void,
  signal?: AbortSignal
): Promise<AnalysisResult[]> {
  const total = data.length;

  const uniqueItems: SeafoodInputItem[] = [];
  const signatureToIndices = new Map<string, number[]>();

  data.forEach((item, index) => {
      const sig = getRowSignature(item);
      if (!signatureToIndices.has(sig)) {
          signatureToIndices.set(sig, []);
          uniqueItems.push(item);
      }
      signatureToIndices.get(sig)!.push(index);
  });

  const uniqueTotal = uniqueItems.length;
  const uniqueResults: AnalysisResult[] = new Array(uniqueTotal);
  let totalRowsFullyProcessed = 0;

  for (let i = 0; i < uniqueTotal; i += (BATCH_SIZE * MAX_CONCURRENT_BATCHES)) {
    if (signal?.aborted) throw new DOMException('Aborted', 'AbortError');

    const batchPromises = [];
    for (let j = 0; j < MAX_CONCURRENT_BATCHES; j++) {
        const start = i + (j * BATCH_SIZE);
        if (start >= uniqueTotal) break;

        const batch = uniqueItems.slice(start, start + BATCH_SIZE);

        // Wrap batch call to update progress as soon as this individual batch returns
        const p = rateBatch(batch).then(results => {
            results.forEach((res, idx) => {
                const uniqueIdx = start + idx;
                uniqueResults[uniqueIdx] = res;

                // Add all occurrences of this unique item to the progress count
                const sig = getRowSignature(uniqueItems[uniqueIdx]);
                totalRowsFullyProcessed += signatureToIndices.get(sig)?.length || 0;
            });

            // Trigger UI update immediately after batch completion
            onProgress(Math.min(totalRowsFullyProcessed, total), total);
            return { start, results };
        });

        batchPromises.push(p);
    }

    await Promise.all(batchPromises);

    if (i + (BATCH_SIZE * MAX_CONCURRENT_BATCHES) < uniqueTotal) {
      await new Promise(resolve => setTimeout(resolve, API_DELAY_MS));
    }
  }

  const finalResults: AnalysisResult[] = new Array(total);
  uniqueItems.forEach((item, uniqueIdx) => {
      const sig = getRowSignature(item);
      const res = uniqueResults[uniqueIdx];
      signatureToIndices.get(sig)?.forEach(originalIdx => {
          finalResults[originalIdx] = res;
      });
  });

  onProgress(total, total);
  return finalResults;
}

export async function updateAnalysisForId(
  item: SeafoodInputItem,
  newId: string
): Promise<AnalysisResult> {
    const officialRecord = getSeafoodById(newId);
    if (officialRecord) {
        return {
            uniqueId: newId,
            matchedKDEs: officialRecord.matchedKDEs,
            rating: officialRecord.rating,
            reliabilityScore: 100, 
            notes: "Manually verified.",
        };
    }
    return {
        uniqueId: newId,
        matchedKDEs: "Unknown ID",
        rating: Rating.NA,
        reliabilityScore: 0,
        notes: "Invalid ID provided.",
    };
}

export async function getColumnMapping(
  mappableFields: string[],
  fileHeaders: string[]
): Promise<{ mapping: Record<string, string>; isFallback: boolean }> {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  const properties: Record<string, object> = {};
  mappableFields.forEach(field => {
    properties[field] = {
      type: Type.STRING,
      enum: [...fileHeaders, 'N/A'],
      description: `The best matching column header for '${field}'.`
    };
  });

  const schema = {
    type: Type.OBJECT,
    properties: properties,
    required: mappableFields,
  };

  const systemInstruction = `You are an expert data mapping specialist. Map required seafood sourcing fields to file headers. Consider synonyms: 'Origin' = 'Source Country', 'Gear' = 'Production Method', 'Species' = 'Common Name'. Use 'N/A' if no match exists.`;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: `Map these fields: ${JSON.stringify(mappableFields)} to these headers: ${JSON.stringify(fileHeaders)}`,
      config: { 
          systemInstruction,
          responseMimeType: "application/json", 
          responseSchema: schema, 
          temperature: 0 
      },
    });
    return { mapping: JSON.parse(response.text.trim()), isFallback: false };
  } catch {
    return { mapping: performStaticMapping(mappableFields, fileHeaders), isFallback: true };
  }
}

export async function analyzeSheetLayout(
  sheetPreviews: { sheetName: string; data: (string | number)[][] }[]
): Promise<{ bestSheetName: string; bestHeaderRow: number }> {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  const schema = {
    type: Type.OBJECT,
    properties: { 
        bestSheetName: { type: Type.STRING, description: "Name of the sheet containing seafood sourcing data." }, 
        bestHeaderRow: { type: Type.NUMBER, description: "1-based index of the header row." } 
    },
    required: ["bestSheetName", "bestHeaderRow"],
  };

  const systemInstruction = `You are an expert spreadsheet analyst. Identify the sheet containing the main seafood sourcing dataset. Look for columns like 'Common Name', 'Species', 'Country', 'Method', 'Volume'. The 'bestHeaderRow' is the 1-based index of the row containing these titles. It is often row 1, but may be lower if there are title rows.`;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: `Identify the best sheet and header row index (1-based) from these previews: ${JSON.stringify(sheetPreviews)}`,
      config: { 
          systemInstruction,
          responseMimeType: "application/json", 
          responseSchema: schema, 
          temperature: 0 
      },
    });
    return JSON.parse(response.text.trim());
  } catch (err) {
    console.error("Layout analysis error:", err);
    return { bestSheetName: sheetPreviews[0]?.sheetName || '', bestHeaderRow: 1 };
  }
}

function performStaticMapping(mappableFields: string[], fileHeaders: string[]): Record<string, string> {
  const mapping: Record<string, string> = {};
  const lowerHeaders = fileHeaders.map(h => h.toLowerCase());

  mappableFields.forEach(field => {
    const fLow = field.toLowerCase();
    const idx = lowerHeaders.findIndex(h => h.includes(fLow) || fLow.includes(h));
    mapping[field] = idx !== -1 ? fileHeaders[idx] : 'N/A';
  });
  return mapping;
}

import { Rating } from '../types';

export interface SeafoodRecord {
  UniqueID: string;
  CommonName: string;
  SubnationalArea: string;
  EconomicZone: string;
  Methods: string;
  RatingColor: string;
}

let parsedDatabase: Map<string, SeafoodRecord> | null = null;
let databaseArray: SeafoodRecord[] = [];
// Pre-calculated index for faster species lookups
let speciesIndex: Map<string, SeafoodRecord[]> = new Map();

function parseCSVLine(line: string): string[] {
  const result: string[] = [];
  let current = '';
  let inQuotes = false;

  for (let i = 0; i < line.length; i++) {
    const char = line[i];
    if (char === '"') {
      if (inQuotes && line[i + 1] === '"') {
        current += '"';
        i++;
      } else {
        inQuotes = !inQuotes;
      }
    } else if (char === ',' && !inQuotes) {
      result.push(current);
      current = '';
    } else {
      current += char;
    }
  }
  result.push(current);
  return result;
}

function parseAndPopulate(csvText: string) {
  const newMap = new Map<string, SeafoodRecord>();
  const newArray: SeafoodRecord[] = [];
  const newIndex = new Map<string, SeafoodRecord[]>();

  const lines = csvText.split('\n');
  const headerLine = lines[0];
  if (!headerLine) return;

  const headers = parseCSVLine(headerLine);
  const idIndex = headers.indexOf('UniqueID');
  const commonNameIndex = headers.indexOf('CommonName');
  const subnationalIndex = headers.indexOf('SubnationalArea');
  const economicZoneIndex = headers.indexOf('EconomicZone');
  const methodsIndex = headers.indexOf('Methods');
  const ratingColorIndex = headers.indexOf('RatingColor');

  for (let i = 1; i < lines.length; i++) {
    const line = lines[i].trim();
    if (!line) continue;

    const cols = parseCSVLine(line);
    const id = cols[idIndex];

    if (id) {
      const record = {
        UniqueID: id,
        CommonName: cols[commonNameIndex] || '',
        SubnationalArea: cols[subnationalIndex] || '',
        EconomicZone: cols[economicZoneIndex] || '',
        Methods: cols[methodsIndex] || '',
        RatingColor: cols[ratingColorIndex] || ''
      };
      newMap.set(id, record);
      newArray.push(record);

      const nameKey = record.CommonName.toLowerCase();
      if (!newIndex.has(nameKey)) newIndex.set(nameKey, []);
      newIndex.get(nameKey)!.push(record);
    }
  }

  parsedDatabase = newMap;
  databaseArray = newArray;
  speciesIndex = newIndex;
}

export async function loadDatabaseFromUrl(url: string) {
  try {
    const response = await fetch(url);
    if (!response.ok) throw new Error(`Failed to fetch database: ${response.status}`);
    const text = await response.text();
    parseAndPopulate(text);
  } catch (error) {
    console.warn(`Falling back to embedded data.`, error);
    parseAndPopulate(REFERENCE_CSV);
  }
}

function initializeDatabase() {
  if (parsedDatabase) return;
  parseAndPopulate(REFERENCE_CSV);
}

export function getSeafoodById(id: string): { matchedKDEs: string; rating: Rating; notes?: string } | null {
  initializeDatabase();
  const record = parsedDatabase?.get(id);
  if (!record) return null;

  return {
    matchedKDEs: formatKDE(record),
    rating: mapColorToRating(record.RatingColor)
  };
}

function formatKDE(record: SeafoodRecord): string {
    const locationParts = [record.SubnationalArea, record.EconomicZone]
        .filter(p => p && p !== '""' && p !== 'N/A')
        .join(', ');
    return `${record.CommonName} | ${locationParts || 'Global'} | ${record.Methods}`;
}

function mapColorToRating(color: string): Rating {
    const c = (color || '').toLowerCase();
    if (c === 'green') return Rating.BestChoice;
    if (c === 'yellow') return Rating.GoodAlternative;
    if (c === 'red') return Rating.Avoid;
    if (c === 'certified') return Rating.Certified;
    return Rating.NA;
}

export interface Candidate {
    record: SeafoodRecord;
    score: number;
    description: string;
}

export function findCandidates(
    criteria: { species?: string; country?: string; method?: string; farmedWild?: string }, 
    limit: number = 5
): Candidate[] {
    initializeDatabase();

    const species = (criteria.species || '').toLowerCase().trim();
    const country = (criteria.country || '').toLowerCase().trim();
    const method = (criteria.method || '').toLowerCase().trim();

    // PERFORMANCE: Start with records that match species name exactly if possible
    let recordsToSearch = databaseArray;
    if (species && speciesIndex.has(species)) {
        recordsToSearch = speciesIndex.get(species)!;
        // If we have enough species matches, only search those to save time. 
        // Otherwise search everything in case it's a "Contains" match.
        if (recordsToSearch.length < 2) {
            recordsToSearch = databaseArray;
        }
    }

    const candidates = recordsToSearch.map(record => {
        let score = 0;
        const recName = record.CommonName.toLowerCase();
        const recZone = record.EconomicZone.toLowerCase();
        const recSub = record.SubnationalArea.toLowerCase();
        const recMethod = record.Methods.toLowerCase();

        // SCORING LOGIC
        // 1. Exact Species Match (Highest)
        if (species === recName) score += 100;
        else if (species && recName.includes(species)) score += 40;

        // 2. Country/Location Match
        if (country) {
            if (recZone === country || recSub === country) score += 60;
            else if (recZone.includes(country) || recSub.includes(country)) score += 30;
        }

        // 3. Method Match
        if (method) {
            if (recMethod === method) score += 40;
            else if (recMethod.includes(method)) score += 20;
        }

        return {
            record,
            score,
            description: formatKDE(record)
        };
    });

    return candidates
        .filter(c => c.score > 0)
        .sort((a, b) => b.score - a.score)
        .slice(0, limit);
}

