import { GoogleGenAI, Type } from "@google/genai";
import { SeafoodInputItem, SeafoodResultItem, Rating } from "../types";
import { getSeafoodById, findCandidates, Candidate } from "./referenceDatabase";

declare var process: {
  env: {
    API_KEY: string;
  };
};

const singleItemSchema = {
  type: Type.OBJECT,
  properties: {
    uniqueId: {
      type: Type.STRING,
      description: "The official ID from provided candidates. Use 'N/A' if no good match.",
    },
    reliabilityScore: {
      type: Type.NUMBER,
      description: "Confidence (0-100).",
    },
    notes: {
      type: Type.STRING,
      description: "Brief reasoning.",
    },
  },
  required: ["uniqueId", "reliabilityScore", "notes"],
};

const responseSchema = {
    type: Type.ARRAY,
    items: singleItemSchema
};

const analysisSystemInstruction = `You are a strict data matching engine for Seafood Watch. Your task is to receive a list of seafood products and their corresponding official database candidates, then pick the best Candidate ID for each. 

Rules: 
1. Only use IDs from the provided 'candidates' list or 'N/A'. 
2. Match Species name, Country/Location, and Production Method as closely as possible. 
3. If the input specifies a Certification like MSC or ASC, prioritize 'N/A' as the UniqueID.
4. Return a JSON array of results in the exact same order as the input items.`;

type AnalysisResult = Pick<SeafoodResultItem, 'uniqueId' | 'matchedKDEs' | 'rating' | 'reliabilityScore' | 'notes'>;

// PERFORMANCE CONFIGURATION
const BATCH_SIZE = 20; // Increased significantly
const MAX_CONCURRENT_BATCHES = 2; // Balanced for throughput and rate limits
const API_DELAY_MS = 1500; 

interface MinifiedInput {
    id: number;
    spec: string;
    cntry: string;
    mthd: string;
    fw: string;
}

interface BatchItemWithCandidates {
    index: number;
    data: MinifiedInput;
    candidates: { id: string; desc: string; rating: string }[];
}

function isRateLimitError(error: any): boolean {
    const errString = JSON.stringify(error).toUpperCase();
    return errString.includes('429') || errString.includes('RESOURCE_EXHAUSTED') || errString.includes('RATE_LIMIT');
}

function getRowSignature(item: SeafoodInputItem): string {
    return `${item['Common name']}|${item['Source country']}|${item['Production Method']}|${item['Wild or Farmed']}`.toLowerCase();
}

async function rateBatch(items: { input: SeafoodInputItem; index: number }[]): Promise<AnalysisResult[]> {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    let retries = 5;
    let delay = 5000;

    const failedResult: AnalysisResult = {
        uniqueId: "N/A",
        matchedKDEs: "Analysis Failed",
        rating: Rating.NA,
        reliabilityScore: 0,
        notes: "An error occurred during analysis.",
    };

    const batchWithCandidates: BatchItemWithCandidates[] = items.map((item) => {
        const candidates = findCandidates({
