export async function getColumnMapping(
  mappableFields: string[],
  fileHeaders: string[]
): Promise<{ mapping: Record<string, string>; isFallback: boolean }> {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  const properties: Record<string, object> = {};
  mappableFields.forEach(field => {
    properties[field] = {
      type: Type.STRING,
      enum: [...fileHeaders, 'N/A'],
      description: `Best column for '${field}'.`
    };
  });

  const schema = {
    type: Type.OBJECT,
    properties: properties,
    required: mappableFields,
  };

  const systemInstruction = `You are an expert data mapping specialist. Map required seafood sourcing fields to file headers. Synonyms: 'Origin' = 'Source Country', 'Gear' = 'Production Method', 'Species' = 'Common Name'. Use 'N/A' if no match exists.`;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: `Map: ${JSON.stringify(mappableFields)} to ${JSON.stringify(fileHeaders)}`,
      config: { 
          systemInstruction,
          responseMimeType: "application/json", 
          responseSchema: schema, 
          temperature: 0 
      },
    });
    return { mapping: JSON.parse(response.text.trim()), isFallback: false };
  } catch {
    return { mapping: performStaticMapping(mappableFields, fileHeaders), isFallback: true };
  }
}

export async function analyzeSheetLayout(
  sheetPreviews: { sheetName: string; data: (string | number)[][] }[]
): Promise<{ bestSheetName: string; bestHeaderRow: number }> {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  const schema = {
    type: Type.OBJECT,
    properties: { 
        bestSheetName: { type: Type.STRING }, 
        bestHeaderRow: { type: Type.NUMBER } 
    },
    required: ["bestSheetName", "bestHeaderRow"],
  };

  const systemInstruction = `Expert spreadsheet analyst. Identify the main seafood sourcing sheet and the 1-based index of the header row.`;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: `Analyze layout: ${JSON.stringify(sheetPreviews)}`,
      config: { 
          systemInstruction,
          responseMimeType: "application/json", 
          responseSchema: schema, 
          temperature: 0 
      },
    });
    return JSON.parse(response.text.trim());
  } catch (err) {
    return { bestSheetName: sheetPreviews[0]?.sheetName || '', bestHeaderRow: 1 };
  }
}

function performStaticMapping(mappableFields: string[], fileHeaders: string[]): Record<string, string> {
  const mapping: Record<string, string> = {};
  const lowerHeaders = fileHeaders.map(h => h.toLowerCase());

  mappableFields.forEach(field => {
    const fLow = field.toLowerCase();
    const idx = lowerHeaders.findIndex(h => h.includes(fLow) || fLow.includes(h));
    mapping[field] = idx !== -1 ? fileHeaders[idx] : 'N/A';
  });
  return mapping;
}

import React, { useState, useEffect } from 'react';
import { getColumnMapping } from '../services/geminiService';

interface ColumnMapperProps {
  fileHeaders: string[];
  mappableFields: string[];
  onConfirm: (mapping: Record<string, string>) => void;
  onCancel: () => void;
}

const ColumnMapper: React.FC<ColumnMapperProps> = ({ fileHeaders, mappableFields, onConfirm, onCancel }) => {
  const [mapping, setMapping] = useState<Record<string, string>>({});
  const [isAutoMapping, setIsAutoMapping] = useState<boolean>(true);
  const [autoMapError, setAutoMapError] = useState<boolean>(false);

  useEffect(() => {
    const generateMapping = async () => {
      setIsAutoMapping(true);
      setAutoMapError(false);
      try {
        const { mapping: newMapping, isFallback } = await getColumnMapping(mappableFields, fileHeaders);
        if (isFallback) {
          setAutoMapError(true);
        }
        setMapping(newMapping);
      } catch (err: any) {
        console.error("Failed to get column mapping:", err);
        setAutoMapError(true);
        const initialMapping: Record<string, string> = {};
        mappableFields.forEach(field => {
            initialMapping[field] = 'N/A';
        });
        setMapping(initialMapping);
      } finally {
        setIsAutoMapping(false);
      }
    };

    generateMapping();
  }, [fileHeaders, mappableFields]);

  const handleMappingChange = (field: string, header: string) => {
    setMapping(prev => ({ ...prev, [field]: header }));
  };

  return (
    <div className="w-full max-w-4xl mx-auto bg-white p-8 rounded-lg shadow-lg border border-gray-200">
      <h2 className="text-2xl font-bold text-gray-800 mb-6">Map Your Data Columns</h2>

      {autoMapError && (
        <div className="bg-yellow-100 border-l-4 border-yellow-500 text-yellow-700 p-4 mb-6" role="alert">
          <p className="font-bold">AI Mapping Unsuccessful</p>
          <p>We couldn't use AI to map your columns, so we've fallen back to basic keyword matching. Please review manually.</p>
        </div>
      )}

      {isAutoMapping ? (
        <div className="flex flex-col items-center justify-center space-y-4 my-12">
            <div className="w-12 h-12 border-4 border-[#62B6F3] border-dashed rounded-full animate-spin"></div>
            <p className="text-gray-600 text-lg">AI is analyzing your columns...</p>
        </div>
      ) : (
        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
          {mappableFields.map(field => (
            <div key={field} className="flex flex-col">
              <label className="block text-sm font-medium text-gray-700 mb-1">
                {field} <span className="text-red-500">*</span>
              </label>
              <select
                value={mapping[field] || 'N/A'}
                onChange={(e) => handleMappingChange(field, e.target.value)}
                className={`w-full px-3 py-2 border rounded-md shadow-sm focus:outline-none focus:ring-blue-500 focus:border-blue-500 ${mapping[field] && mapping[field] !== 'N/A' ? 'border-green-500 bg-green-50' : 'border-gray-300'}`}
              >
                <option value="N/A">-- Select Column --</option>
                {fileHeaders.map(header => (
                  <option key={header} value={header}>
                    {header}
                  </option>
                ))}
              </select>
            </div>
          ))}
        </div>
      )}

      <div className="mt-8 flex justify-end gap-4">
        <button
          onClick={onCancel}
          className="px-6 py-2 font-semibold text-gray-700 bg-gray-200 rounded-md hover:bg-gray-300 focus:outline-none transition-colors duration-200"
        >
          Back
        </button>
        <button
          onClick={() => onConfirm(mapping)}
          disabled={isAutoMapping}
          className="px-6 py-2 font-semibold text-white bg-[#00629B] rounded-md hover:bg-[#00497b] focus:outline-none disabled:bg-gray-400 disabled:cursor-not-allowed transition-colors duration-200"
        >
          Confirm & Analyze Data
        </button>
      </div>
    </div>
  );
};

export default ColumnMapper;

