  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    setInputValue(e.target.value);
  };

  const commitValue = () => {
    const newRow = parseInt(inputValue, 10);
    if (!isNaN(newRow) && newRow > 0) {
      onHeaderRowChange(newRow);
